// Generated from Google Search Central structured data docs (read 2026-10-04) by
// docs/validator-specs/build_specs.py. Do not edit by hand.
export default {"specs":[{"feature":"Article","slug":"article","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/article","status":"active","statusNote":"There are no required properties; Google says to add the properties that apply to your content. Helps Google show better title text, images, and date information for news, blog, and sports article pages.","triggerTypes":["Article","NewsArticle","BlogPosting"],"entity":{"properties":[{"name":"author","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"Include all authors. When specifying multiple authors, list each author in their own author field. Use Person for people and Organization for organizations."},"message":"Add author: the author of the article (Person or Organization). List each author in their own author field.","nested":{"properties":[{"name":"name","level":"optional","expects":["Text"],"array":false,"constraints":{"note":"Only specify the author's name in author.name. Do not add job titles, honorifics, publisher names, or introductory phrases such as 'posted by'."},"message":"Add author.name: the name of the author. Only the name, no titles, honorifics or publisher names."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add author.url: a link to a web page that uniquely identifies the author of the article, for example the author's social media page, an about me page, or a bio page."}],"anyOf":[]}},{"name":"dateModified","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format."},"message":"Add dateModified: the date and time the article was most recently modified, in ISO 8601 format."},{"name":"datePublished","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format. Google recommends providing timezone information; otherwise it defaults to the timezone used by Googlebot."},"message":"Add datePublished: the date and time the article was first published, in ISO 8601 format, ideally with timezone information."},{"name":"headline","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Consider using a concise title, as long titles may be truncated on some devices."},"message":"Add headline: the title of the article. Keep it concise, long titles may be truncated on some devices."},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"minPixels":50000,"aspectRatios":["16x9","4x3","1x1"],"formats":["BMP","GIF","JPEG","PNG","WebP","SVG","AVIF"]},"note":"Image URLs must be crawlable and indexable. Images must represent the marked up content. Images must be in a file format supported by Google Images. For best results provide multiple high-resolution images (minimum of 50K pixels when multiplying width and height) with aspect ratios 16x9, 4x3, and 1x1."},"message":"Add image: the URL to an image that is representative of the article. Provide multiple high-resolution images (at least 50K pixels) in 16x9, 4x3 and 1x1."}],"anyOf":[]},"customChecks":[{"id":"article_author_name_clean","level":"warning","description":"author.name should contain only the author's name: flag values containing job titles, honorifics (Dr., Mr., Ms.), 'posted by' style prefixes, the publisher name, or multiple names joined in one string (for example 'A and B', 'A, B')."},{"id":"article_author_type","level":"warning","description":"author objects should declare @type Person or Organization; flag a bare string author or an author missing @type."},{"id":"article_author_url_or_sameas","level":"warning","description":"Each author should include url (or sameAs) to help Google disambiguate the author."},{"id":"article_date_timezone","level":"warning","description":"datePublished and dateModified should be valid ISO 8601 and include a timezone offset; without it Google uses Googlebot's timezone."},{"id":"article_date_order","level":"warning","description":"dateModified should not be earlier than datePublished."},{"id":"article_image_aspect_ratios","level":"warning","description":"For best results provide multiple images covering the 16x9, 4x3 and 1x1 aspect ratios, each at least 50,000 pixels (width x height), when dimensions are known."},{"id":"article_image_crawlable","level":"warning","description":"Image URLs must be crawlable and indexable (absolute URL, not blocked by robots.txt, not a data URI) and in a format supported by Google Images."}],"guidelines":["Follow Search Essentials and the general structured data guidelines.","Include all authors in the markup, each in its own author field.","Only specify the author's name in author.name; use url or sameAs to identify the author.","Use Person for people and Organization for organizations as the author type.","Images must represent the marked up content and be crawlable and indexable.","For multi-part articles, make sure rel=canonical points at either each individual page or a 'view-all' page, not to page 1 of a multi-part series.","If content is behind a subscription or registration, consider adding paywalled content structured data (isAccessibleForFree / hasPart)."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Book actions","slug":"book","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/book","status":"limited","statusNote":"Limited to book providers with a wide selection of available books (register interest). Delivered via data feeds, not page markup.","triggerTypes":["Book"],"entity":{"properties":[{"name":"@id","level":"required","expects":["URL"],"array":false,"message":"Add @id: a globally unique, stable URL-format ID for the book, unique to your organization."},{"name":"author","level":"required","expects":["Person","Organization"],"array":true,"message":"Add author: the author(s) of the book.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add author.name."},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"Add author.sameAs: a reference page that identifies the person or organization."}],"anyOf":[]}},{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the title of the book."},{"name":"url","level":"required","expects":["URL"],"array":false,"message":"Add url: the page on your site where the book is described (canonical)."},{"name":"workExample","level":"required","expects":["Book"],"array":true,"message":"Add workExample: the edition(s) of the work.","nested":{"properties":[{"name":"@id","level":"required","expects":["URL"],"array":false,"message":"Add @id: a globally unique, stable URL-format ID for the edition, unique to your organization."},{"name":"bookFormat","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/AudiobookFormat","https://schema.org/EBook","https://schema.org/Hardcover","https://schema.org/Paperback"]},"message":"Add bookFormat."},{"name":"inLanguage","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[a-z]{2}$"},"message":"Add inLanguage: an ISO 639-1 alpha-2 language code."},{"name":"isbn","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^(97[89])\\d{10}$","note":"Google Search doesn't accept ISBN-10. Books without ISBN may be included but might not surface."},"message":"Add isbn: the ISBN-13 of the edition. Convert ISBN-10 to ISBN-13."},{"name":"potentialAction","level":"required","expects":["ReadAction","BorrowAction"],"array":true,"message":"Add potentialAction: ReadAction or BorrowAction for users to purchase, download or borrow the book.","nested":{"properties":[{"name":"target","level":"required","expects":["EntryPoint"],"array":true,"message":"Add target: the deep link specification, including supported platforms.","nested":{"properties":[{"name":"urlTemplate","level":"required","expects":["URL"],"array":false,"message":"Add target.urlTemplate: the link that takes users directly to the book's landing page."},{"name":"actionPlatform","level":"required","expects":["URL","Enum"],"array":true,"constraints":{"enum":["https://schema.org/DesktopWebPlatform","https://schema.org/AndroidPlatform","https://schema.org/IOSPlatform"]},"message":"Add target.actionPlatform: one or more supported platforms."}],"anyOf":[]}},{"name":"expectsAcceptanceOf","level":"recommended","expects":["Offer"],"array":true,"constraints":{"note":"Required when @type is ReadAction."},"message":"ReadAction: add expectsAcceptanceOf (required for ReadAction). If multiple Offers, a user matching any of them may access the content.","nested":{"properties":[{"name":"category","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["nologinrequired","free","subscription","purchase","rental"]},"message":"Add expectsAcceptanceOf.category."},{"name":"eligibleRegion","level":"required","expects":["Country"],"array":true,"message":"Add eligibleRegion: the country eligible for this Offer.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$"},"message":"Add eligibleRegion.name: ISO 3166-1 alpha-2 country code."}],"anyOf":[]}},{"name":"availabilityStarts","level":"recommended","expects":["DateTime"],"array":false,"message":"Add availabilityStarts: start of the availability window (ISO 8601)."},{"name":"availabilityEnds","level":"recommended","expects":["DateTime"],"array":false,"message":"Add availabilityEnds: end of the availability window (ISO 8601)."},{"name":"price","level":"recommended","expects":["Number"],"array":false,"message":"Add price: the purchase price. Required when category is purchase or rental."},{"name":"priceCurrency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add priceCurrency in three-letter ISO 4217 format."}],"anyOf":[]}},{"name":"lender","level":"recommended","expects":["LibrarySystem"],"array":false,"constraints":{"note":"Required when @type is BorrowAction; needs @id and @type LibrarySystem."},"message":"BorrowAction: add lender (required for BorrowAction): the library system, referenced by @id and fully described in the library feed."}],"anyOf":[]}},{"name":"author","level":"optional","expects":["Person","Organization"],"array":true,"message":"Add author only when the edition author differs from the work author."},{"name":"bookEdition","level":"recommended","expects":["Text"],"array":false,"message":"Add bookEdition, for example 2nd Edition."},{"name":"datePublished","level":"recommended","expects":["Date"],"array":false,"constraints":{"pattern":"^\\d{4}(-\\d{2}-\\d{2})?$"},"message":"Add datePublished in YYYY-MM-DD or YYYY format."},{"name":"identifier","level":"recommended","expects":["PropertyValue"],"array":true,"message":"Add identifier: external IDs that unambiguously identify this edition.","nested":{"properties":[{"name":"propertyID","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["OCLC_NUMBER","LCCN","JP_E-CODE"]},"message":"Add propertyID."},{"name":"value","level":"required","expects":["Text"],"array":false,"message":"Add value: the external ID with all non-numeric prefixes removed."}],"anyOf":[]}},{"name":"name","level":"optional","expects":["Text"],"array":false,"message":"Add name only when the edition title differs from the work title."},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"Add sameAs: a reference page that unambiguously indicates the edition."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add url: the page on your site where the edition is described."}],"anyOf":[]}},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"Add sameAs: a reference page identifying the work (Wikipedia, Wikidata, VIAF, Library of Congress)."}],"anyOf":[]},"customChecks":[{"id":"action_type_requirements","level":"error","description":"ReadAction requires target and expectsAcceptanceOf (Offer with category and eligibleRegion). BorrowAction requires target and lender (@type LibrarySystem with @id described in the library feed)."},{"id":"price_for_purchase_rental","level":"error","description":"expectsAcceptanceOf.price is required when category is purchase or rental."},{"id":"stale_entities","level":"error","description":"The feed must not contain entities whose availabilityEnds has passed or that are no longer available."},{"id":"unique_ids_urls","level":"error","description":"Each entity needs a unique @id, url and urlTemplate."},{"id":"isbn13","level":"error","description":"isbn must be ISBN-13 (valid checksum); ISBN-10 is not accepted."},{"id":"production_canonical_urls","level":"warning","description":"All url and urlTemplate values must be production, canonical URLs; action links must land on a page that directly supports purchase or borrowing."}],"guidelines":["Links must be canonical URLs containing the book title and information; action links must go directly to a page that supports purchase or borrowing, not to pages with more links to click.","All deep links and URLs must be production URLs.","Don't include stale entities; use availabilityStarts and availabilityEnds for foreseeable changes and remove entities that are no longer available.","Feed files must be under 1 GB uncompressed and use a .json extension; Google fetches the feed once a day and typically indexes within two days.","Grouping editions under one work with at least one ISBN may help matching for books without ISBN."],"lastUpdatedOnDoc":"2025-12-10"},{"feature":"Breadcrumb","slug":"breadcrumb","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/breadcrumb","status":"active","statusNote":"","triggerTypes":["BreadcrumbList"],"entity":{"properties":[{"name":"itemListElement","level":"required","expects":["ListItem"],"array":true,"constraints":{"minItems":2,"note":"An array of breadcrumbs listed in a specific order. Specify each breadcrumb with a ListItem. To specify breadcrumbs, define a BreadcrumbList that contains at least two ListItems."},"message":"Add itemListElement: an ordered array of at least two ListItem breadcrumbs.","nested":{"properties":[{"name":"item","level":"optional","expects":["URL","Thing"],"array":false,"constraints":{"note":"The URL to the webpage that represents the breadcrumb. JSON-LD: use @id (or a URL string). Microdata: href or itemid. RDFa: about, href, or resource. If the breadcrumb is the last item in the breadcrumb trail, item is not required."},"message":"Add item: the URL to the webpage that represents the breadcrumb (not required for the last item in the trail)."},{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the title of the breadcrumb displayed for the user."},{"name":"position","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":1,"note":"Position 1 signifies the beginning of the trail."},"message":"Add position: the position of the breadcrumb in the trail. Position 1 signifies the beginning of the trail."}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"breadcrumb_min_items","level":"error","description":"A BreadcrumbList must contain at least two ListItems."},{"id":"breadcrumb_item_optional_last","level":"error","description":"Every ListItem except the one with the highest position must have item (a URL string, or an object with @id/url). Missing item on the last ListItem is allowed."},{"id":"breadcrumb_name_from_item","level":"error","description":"Each ListItem needs name. Accept ListItem.name, or item.name when item is an object (Thing) carrying the name instead of a plain URL."},{"id":"breadcrumb_positions","level":"error","description":"itemListElement positions must be integers that start at 1 and increase by 1 with no gaps or duplicates."},{"id":"breadcrumb_item_url_valid","level":"error","description":"item URLs (or item @id) must be valid absolute URLs."},{"id":"breadcrumb_multiple_trails","level":"info","description":"Multiple BreadcrumbList objects on one page are allowed (multiple trails); validate each trail independently."}],"guidelines":["Provide breadcrumbs that represent a typical user path to a page, instead of mirroring the URL structure.","It is not required to include a breadcrumb ListItem for the top level path (your site's domain or host name), nor for the page itself.","Some pages may have multiple breadcrumb trails; mark up each as its own BreadcrumbList.","Follow Search Essentials and the general structured data guidelines."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Carousel","slug":"carousel","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/carousel","status":"active","statusNote":"Host carousel rich result (a list-like result people can swipe through on mobile devices). Only eligible when ItemList is combined with one of: Course list, Movie, Recipe, Restaurant.","triggerTypes":["ItemList"],"entity":{"properties":[{"name":"itemListElement","level":"required","expects":["ListItem"],"array":true,"constraints":{"minItems":2,"note":"List of items. To specify a list, define an ItemList that contains at least two ListItem elements. Summary page: each ListItem has position and url. All-in-one page: each ListItem has position and item (with item.name, item.url, plus all properties of the specific type)."},"message":"Add itemListElement: an ItemList must contain at least two ListItem elements.","nested":{"properties":[{"name":"position","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":1,"note":"The item's position in the carousel. This is a 1-based number."},"message":"Add position: the item's position in the carousel (1-based)."},{"name":"url","level":"required","expects":["URL"],"array":false,"constraints":{"note":"Summary page pattern only. The canonical URL of the item detail page. All URLs in the list must be unique, but live on the same domain."},"message":"Add url: the canonical URL of the item detail page. All URLs must be unique and on the same domain."},{"name":"item","level":"required","expects":["Course","Movie","Recipe","Restaurant","Thing"],"array":false,"constraints":{"note":"All-in-one page pattern only. An individual thing in a list. Populate with item.name and item.url plus all the properties of the specific structured data type being described."},"message":"Add item: the full object for this list item (all-in-one page pattern).","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add item.name: the string name of the item, displayed as the title of the individual item in the carousel."},{"name":"url","level":"required","expects":["URL"],"array":false,"constraints":{"note":"The fully-qualified URL and page anchor to this item on the page. The URL must be the current page, and you must include an HTML anchor (name or id tag) in your page near the user-visible text."},"message":"Add item.url: the fully-qualified URL of the current page plus an anchor to this item."}],"anyOf":[]}}],"anyOf":[{"level":"required","props":["url","item"],"message":"Each ListItem needs url (summary page) or item (all-in-one page)."}]}}],"anyOf":[]},"customChecks":[{"id":"carousel_supported_type","level":"error","description":"Items must be one of the supported types: Course (course list), Movie, Recipe, Restaurant. For the summary pattern, the detail pages carry that type; for the all-in-one pattern, item @type must be one of these."},{"id":"carousel_same_type","level":"error","description":"All items in the list must be of the same type (for example only Recipe items in a recipe list)."},{"id":"carousel_mode_consistent","level":"warning","description":"Do not mix patterns: either every ListItem uses url (summary page) or every ListItem uses item (all-in-one page)."},{"id":"carousel_positions","level":"error","description":"position values must be 1-based integers, unique, and increasing by 1."},{"id":"carousel_urls_unique_same_domain","level":"error","description":"Summary pattern: all ListItem.url values must be unique and live on the same domain as each other."},{"id":"carousel_allinone_anchor","level":"error","description":"All-in-one pattern: item.url must equal the current page URL plus a fragment (#anchor), and each fragment should be unique."},{"id":"carousel_item_type_requirements","level":"error","description":"All-in-one pattern: each item must also satisfy the required properties of its own feature spec (Course, Movie, Recipe, Restaurant)."}],"guidelines":["Add the required and recommended properties for the specific content type the carousel is about: Course, Movie, Recipe, or Restaurant.","Use either a summary page with separate detail pages, or a single all-in-one page that contains all list information.","All items in the list must be of the same type.","Make sure the carousel structured data is complete and contains all the items that are listed on the page.","The text visible to the user must be similar to the information contained in the structured data on the page.","Items shown in list format will be shown in the order specified by the position property."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Course info","slug":"course-info","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/course-info","status":"deprecated","statusNote":"Phase-out announced Jun 12, 2025 (Simplifying the search results page). Removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters, and doc removed, Sep 9, 2025 (no longer shown in Google Search results). Doc URL now redirects to the updates changelog.","triggerTypes":["Course"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"course_info_deprecated","level":"warning","description":"Course info rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers. Course list (carousel) is a separate feature that is still documented."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Course list","slug":"course","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/course","status":"active","statusNote":"The course list rich result is available in English in all regions where Google Search is available. Requires Course markup combined with carousel (ItemList) markup on a summary or all-in-one page; at least three courses.","triggerTypes":["Course"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The title of the course. Must be a real course title: no promotional phrases (e.g. 'Best school in the world'), prices (e.g. 'only $30!'), discounts, or non-course titles (e.g. 'Make money fast')."},"message":"Add name: the title of the course."},{"name":"description","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":60,"note":"A description of the course. Display limit of 60 characters (longer text may be truncated)."},"message":"Add description: a description of the course (display limit of 60 characters)."},{"name":"provider","level":"recommended","expects":["Organization"],"array":false,"message":"Add provider: the organization that publishes the source content of the course, for example UC Berkeley."}],"anyOf":[]},"customChecks":[{"id":"course_itemlist_present","level":"error","description":"Course markup must be part of carousel markup: an ItemList whose ListItems either point via url to course detail pages (summary page) or contain Course objects in item (all-in-one page)."},{"id":"course_min_three","level":"error","description":"You must mark up at least three courses (ItemList.itemListElement length >= 3)."},{"id":"course_itemlist_position","level":"error","description":"ListItem.position (Integer) is required: ordinal position of the item page in the list, 1-based, increasing by 1."},{"id":"course_itemlist_url_unique","level":"error","description":"ListItem.url (URL) is required in the summary pattern: the canonical URL of the item page. Every item must have a unique URL."},{"id":"course_name_promotional","level":"warning","description":"Flag course names containing prices or currency amounts, discount language ('% off', 'sale', 'discount'), promotional superlatives ('best', 'top'), or non-course phrases."},{"id":"course_description_length","level":"warning","description":"description longer than 60 characters will be truncated in display."}],"guidelines":["Only use Course markup for educational content that fits the definition: a series or unit of curriculum that contains lectures, lessons, or modules in a particular subject and/or topic.","A course must have an explicit educational outcome of knowledge and/or skill, and be led by one or more instructors with a roster of students.","Not courses: a general public event such as 'Astronomy Day', or a single brief tutorial video.","You must mark up at least three courses, using carousel markup on a summary page or an all-in-one page.","Course names must not include promotional phrases, prices, discounts, or non-course titles.","Follow the carousel guidelines and the general structured data guidelines."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Dataset","slug":"dataset","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/dataset","status":"active","statusNote":"Datasets appear in Google Dataset Search, not as a standard Google Search rich result.","triggerTypes":["Dataset"],"entity":{"properties":[{"name":"description","level":"required","expects":["Text"],"array":false,"constraints":{"minLength":50,"maxLength":5000,"note":"A short summary describing a dataset. The summary must be between 50 and 5000 characters long."},"message":"Add description: a short summary describing the dataset, between 50 and 5000 characters long."},{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"A descriptive name of a dataset, for example 'Snow depth in the Northern Hemisphere'. Use unique names for distinct datasets whenever possible."},"message":"Add name: a descriptive name of the dataset. Use unique names for distinct datasets."},{"name":"alternateName","level":"recommended","expects":["Text"],"array":true,"message":"Add alternateName: alternative names that have been used to refer to this dataset, such as aliases or abbreviations."},{"name":"creator","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"To uniquely identify individuals, use an ORCID ID as the value of sameAs; for institutions, use a ROR ID. Persons: givenName, familyName, name, sameAs. Organizations: name, sameAs, url."},"message":"Add creator: the creator or author of this dataset (Person or Organization), ideally identified with ORCID or ROR IDs in sameAs.","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Add creator.name."},{"name":"sameAs","level":"recommended","expects":["URL"],"array":true,"constraints":{"note":"ORCID ID for a Person, ROR ID for an Organization."},"message":"Add creator.sameAs: an ORCID ID (person) or ROR ID (organization)."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add creator.url for organizations."},{"name":"givenName","level":"recommended","expects":["Text"],"array":false,"message":"Add creator.givenName for persons."},{"name":"familyName","level":"recommended","expects":["Text"],"array":false,"message":"Add creator.familyName for persons."}],"anyOf":[]}},{"name":"citation","level":"recommended","expects":["Text","CreativeWork"],"array":true,"constraints":{"note":"Identifies academic articles that are recommended by the data provider be cited in addition to the dataset itself. Don't use this property to provide citation information for the dataset itself; use identifier for that."},"message":"Add citation: academic articles the data provider recommends be cited in addition to the dataset itself."},{"name":"funder","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"Use ORCID ID for individuals and ROR ID for organizations (via sameAs)."},"message":"Add funder: a person or organization that provides financial support for this dataset."},{"name":"hasPart","level":"recommended","expects":["URL","Dataset"],"array":true,"constraints":{"note":"If the dataset is a collection of smaller datasets, use hasPart to denote the relationship. Conversely, use isPartOf on the smaller datasets."},"message":"Add hasPart when this dataset is a collection of smaller datasets."},{"name":"isPartOf","level":"recommended","expects":["URL","Dataset"],"array":true,"message":"Add isPartOf when this dataset is part of a larger dataset collection."},{"name":"identifier","level":"recommended","expects":["URL","Text","PropertyValue"],"array":true,"constraints":{"note":"An identifier, such as a DOI or a Compact Identifier. If the dataset has more than one identifier, repeat the identifier property."},"message":"Add identifier: an identifier such as a DOI or Compact Identifier. Repeat for multiple identifiers."},{"name":"isAccessibleForFree","level":"recommended","expects":["Boolean"],"array":false,"message":"Add isAccessibleForFree: whether the dataset is accessible without payment."},{"name":"keywords","level":"recommended","expects":["Text"],"array":true,"message":"Add keywords summarizing the dataset."},{"name":"license","level":"recommended","expects":["URL","CreativeWork"],"array":false,"constraints":{"note":"A license under which the dataset is distributed. Provide a URL that unambiguously identifies a specific version of the license used."},"message":"Add license: a URL that unambiguously identifies the specific license version under which the dataset is distributed."},{"name":"measurementTechnique","level":"recommended","expects":["Text","URL"],"array":true,"constraints":{"note":"The technique, technology, or methodology used in a dataset, which can correspond to the variable(s) described in variableMeasured."},"message":"Add measurementTechnique: the technique, technology, or methodology used in the dataset."},{"name":"sameAs","level":"recommended","expects":["URL"],"array":true,"constraints":{"note":"Use when the dataset is republished elsewhere, pointing to the canonical page."},"message":"Add sameAs: the URL of a reference web page that unambiguously indicates the dataset's identity."},{"name":"spatialCoverage","level":"recommended","expects":["Text","Place"],"array":true,"constraints":{"note":"A single point (Place.geo GeoCoordinates with latitude and longitude), a shape (Place.geo GeoShape with box, circle, line, or polygon), or a named place as Text. Points inside box, circle, line, or polygon must be a space separated pair of latitude and longitude, in that order. Box format: 'lat1 long1 lat2 long2'."},"message":"Add spatialCoverage: a named place, a GeoCoordinates point, or a GeoShape describing the dataset's spatial aspect."},{"name":"temporalCoverage","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"ISO 8601 date or interval. Single date '2008'; period '1950-01-01/2013-12-18'; open-ended interval '2013-12-19/..' using two dots."},"message":"Add temporalCoverage: the time interval the data covers, in ISO 8601 format (for example 1950-01-01/2013-12-18 or 2013-12-19/..)."},{"name":"variableMeasured","level":"recommended","expects":["Text","PropertyValue"],"array":true,"message":"Add variableMeasured: the variable that this dataset measures, for example temperature or pressure."},{"name":"version","level":"recommended","expects":["Text","Number"],"array":false,"message":"Add version: the version number for the dataset."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add url: location of a page describing the dataset."},{"name":"includedInDataCatalog","level":"recommended","expects":["DataCatalog"],"array":false,"message":"Add includedInDataCatalog: the catalog to which the dataset belongs."},{"name":"distribution","level":"recommended","expects":["DataDownload"],"array":true,"constraints":{"note":"The description of the location for download of the dataset and the file format for download."},"message":"Add distribution: DataDownload objects describing where to download the dataset and in which format.","nested":{"properties":[{"name":"contentUrl","level":"required","expects":["URL"],"array":false,"message":"Add distribution.contentUrl: the link for the download."},{"name":"encodingFormat","level":"recommended","expects":["Text","URL"],"array":false,"message":"Add distribution.encodingFormat: the file format of the distribution."}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"dataset_description_length","level":"error","description":"description length must be between 50 and 5000 characters."},{"id":"dataset_temporal_iso8601","level":"warning","description":"temporalCoverage should be an ISO 8601 date or interval (start/end), allowing '..' for an open end."},{"id":"dataset_geoshape_format","level":"error","description":"GeoShape box/circle/line/polygon values must be space separated latitude longitude pairs (latitude first); box has exactly 4 numbers (two points)."},{"id":"dataset_distribution_contenturl","level":"error","description":"Every DataDownload in distribution must have contentUrl."},{"id":"dataset_creator_ids","level":"info","description":"Suggest ORCID (https://orcid.org/...) sameAs for Person creators/funders and ROR (https://ror.org/...) for Organization creators/funders."},{"id":"dataset_citation_not_self","level":"warning","description":"citation should reference related academic articles, not the dataset's own citation; use identifier (DOI) for the dataset itself."}],"guidelines":["Examples of datasets: a table or CSV file with data, an organized collection of tables, a file in a proprietary format that contains data, a collection of files that together constitute a meaningful dataset, a structured object with data in another format, images capturing data, files relating to machine learning.","Add structured data to the canonical 'landing' page for each dataset.","If you republish a dataset, use sameAs to point to the canonical page; use isBasedOn when the republished dataset has significant metadata changes or is derived/aggregated from other sources.","Attach DOIs or Compact Identifiers via identifier, repeating it as needed.","Use unique names for distinct datasets whenever possible.","Allow time for re-crawling and re-indexing; it may take several days after publishing for Google to find and crawl the page."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Discussion forum","slug":"discussion-forum","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/discussion-forum","status":"active","statusNote":"For user-generated forum-style content. Use QAPage markup instead for question-and-answer forums. SocialMediaPosting has the same requirements as DiscussionForumPosting.","triggerTypes":["DiscussionForumPosting","SocialMediaPosting"],"entity":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":true,"message":"Add author: information about the author of the post.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add author.name: the name of the author of the post."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add author.url: a link to a web page that uniquely identifies the author of the post, most likely a profile page of the forum."}],"anyOf":[]}},{"name":"datePublished","level":"required","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format."},"message":"Add datePublished: the date and time the post was made, in ISO 8601 format."},{"name":"text","level":"optional","expects":["Text"],"array":false,"message":"Add text: any text in the post, if applicable."},{"name":"image","level":"optional","expects":["ImageObject","URL"],"array":true,"constraints":{"note":"Any inline images within the post, if applicable. If there aren't any images, don't include default, icon, placeholder, or author images in this field."},"message":"Add image: inline images within the post. Do not use default, icon, placeholder, or author images."},{"name":"video","level":"optional","expects":["VideoObject"],"array":true,"message":"Add video: any inline videos within the post, if applicable."},{"name":"comment","level":"optional","expects":["Comment"],"array":true,"constraints":{"note":"A comment about or response to the post, if applicable. Mark up comments in the order in which they appear on the page. Nest replies as a tree of comments to mirror the forum's threading."},"message":"Add comment: comments about or responses to the post, in the order they appear on the page.","nested":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":true,"message":"Add comment author: information about the author of the comment.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add comment author.name: the name of the author of the comment."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add comment author.url: a link to a web page that uniquely identifies the author, likely a forum profile page."}],"anyOf":[]}},{"name":"datePublished","level":"required","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format."},"message":"Add comment datePublished: the date and time the comment was made, in ISO 8601 format."},{"name":"text","level":"optional","expects":["Text"],"array":false,"message":"Add comment text: any text in the comment, if applicable."},{"name":"image","level":"optional","expects":["ImageObject","URL"],"array":true,"constraints":{"note":"Inline images only; no default, icon, placeholder, or author images."},"message":"Add comment image: inline images within the comment, if applicable."},{"name":"video","level":"optional","expects":["VideoObject"],"array":true,"message":"Add comment video: inline videos within the comment, if applicable."},{"name":"comment","level":"optional","expects":["Comment"],"array":true,"message":"Add nested comment: replies to this comment, if applicable."},{"name":"commentCount","level":"optional","expects":["Integer"],"array":false,"message":"Add commentCount: the number of replies to this comment, if applicable."},{"name":"creativeWorkStatus","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["Deleted"]},"message":"Set creativeWorkStatus to Deleted when the comment was deleted but remains for context or threading."},{"name":"dateModified","level":"optional","expects":["DateTime"],"array":false,"message":"Add comment dateModified: when the comment was edited, in ISO 8601 format, if applicable."},{"name":"digitalSourceType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/TrainedAlgorithmicMediaDigitalSource","https://schema.org/AlgorithmicMediaDigitalSource"]},"message":"Add digitalSourceType when the comment was generated by an automated system (LLM or simpler bot)."},{"name":"interactionStatistic","level":"optional","expects":["InteractionCounter"],"array":true,"message":"Add interactionStatistic: user statistics applied to the comment, if applicable."},{"name":"sharedContent","level":"optional","expects":["CreativeWork","WebPage","ImageObject","VideoObject","DiscussionForumPosting","Comment"],"array":false,"message":"Add sharedContent: the primary shared content in the comment, if applicable."},{"name":"url","level":"optional","expects":["URL"],"array":false,"constraints":{"note":"The URL to this specific comment on the page, if applicable. Omit if it only links back to the original post."},"message":"Add comment url: the URL to this specific comment on the page, if applicable."}],"anyOf":[{"level":"required","props":["text","image","video"],"message":"A comment must include one of text, image, or video."}]}},{"name":"commentCount","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Particularly useful if comments are not all present in the comment markup."},"message":"Add commentCount: the number of comments about this post, if applicable."},{"name":"creativeWorkStatus","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["Deleted"]},"message":"Set creativeWorkStatus to Deleted when the post has been deleted but remains for context or threading."},{"name":"dateModified","level":"optional","expects":["DateTime"],"array":false,"message":"Add dateModified: the date and time the post was edited, in ISO 8601 format, if applicable."},{"name":"digitalSourceType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/TrainedAlgorithmicMediaDigitalSource","https://schema.org/AlgorithmicMediaDigitalSource"],"note":"TrainedAlgorithmicMediaDigitalSource: content created by a trained model such as an LLM. AlgorithmicMediaDigitalSource: content created by a simpler algorithmic process such as an automated bot. If omitted, content is assumed to be human-generated."},"message":"Add digitalSourceType when the post was generated by an automated system."},{"name":"headline","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"If there isn't a separate title, don't duplicate or truncate the text into a headline."},"message":"Add headline: the title of the post. Don't duplicate or truncate the post text into a headline."},{"name":"interactionStatistic","level":"optional","expects":["InteractionCounter"],"array":true,"constraints":{"note":"User statistics applied to the main post. Supported interactionType values: LikeAction (likes or upvotes), DislikeAction (dislikes or downvotes), ViewAction (views), CommentAction or ReplyAction (comments/replies), ShareAction (reshares)."},"message":"Add interactionStatistic: user statistics applied to the post, if applicable.","nested":{"properties":[{"name":"interactionType","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/LikeAction","https://schema.org/DislikeAction","https://schema.org/ViewAction","https://schema.org/CommentAction","https://schema.org/ReplyAction","https://schema.org/ShareAction"]},"message":"Add interactionType: the subtype of Action the count refers to."},{"name":"userInteractionCount","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":0},"message":"Add userInteractionCount: the number of times this interaction was performed."}],"anyOf":[]}},{"name":"isPartOf","level":"recommended","expects":["CreativeWork","URL"],"array":false,"message":"Add isPartOf: the primary source of the post if it occurs on a particular part of the website (for example a subforum)."},{"name":"mainEntityOfPage","level":"recommended","expects":["WebPage","URL"],"array":false,"constraints":{"note":"Use when the URL is primarily about a single post, to identify the primary DiscussionForumPosting."},"message":"Add mainEntityOfPage when the page is primarily about this single post."},{"name":"sharedContent","level":"optional","expects":["CreativeWork","WebPage","ImageObject","VideoObject","DiscussionForumPosting","Comment"],"array":false,"constraints":{"note":"The primary shared content in the post: WebPage for a shared link, ImageObject or VideoObject for shared media, or a DiscussionForumPosting/Comment for a quoted or reshared post."},"message":"Add sharedContent: the primary shared content in the post, if applicable."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"In multi-page threads, set this to the first page URL."},"message":"Add url: the canonical URL of the discussion (first page URL for multi-page threads)."}],"anyOf":[{"level":"required","props":["text","image","video"],"message":"To represent the content of the post, include one of text, image, or video. Not required if representing a post on another page (with an external url)."}]},"customChecks":[{"id":"forum_content_or_external","level":"error","description":"Posts and comments must include text, image, or video, unless the DiscussionForumPosting represents a post on another page (its url points to a different page than the current one); downgrade to pass in that case."},{"id":"forum_interaction_type_enum","level":"error","description":"interactionStatistic.interactionType must be one of LikeAction, DislikeAction, ViewAction, CommentAction, ReplyAction, ShareAction (accept short names or full schema.org URLs)."},{"id":"forum_iso_dates","level":"error","description":"datePublished and dateModified on posts and comments must be valid ISO 8601 date-times."},{"id":"forum_headline_duplicate","level":"warning","description":"headline should not equal or be a truncated prefix of text."},{"id":"forum_comment_count_consistency","level":"info","description":"If commentCount is present it should be >= the number of comment objects marked up."},{"id":"forum_not_publisher_content","level":"info","description":"Remind: only use for user-generated posts, not publisher-authored articles or product reviews."}],"guidelines":["Only use DiscussionForumPosting for user-generated posts on a website, not for content primarily authored by the publisher.","Valid: community forums, generic forum platforms, social media platforms with user posts. Invalid: publisher-written articles (even with user comments) and product reviews.","Use QAPage markup instead if the forum follows a question-and-answer pattern.","For multi-page threads, later pages should include the original post, with url set to the main (first) page URL.","Nest comments under the post they relate to; if the forum has its own threading structure, use a tree of comments to represent it.","Mark up comments in the order in which they appear on the page.","Set creativeWorkStatus to Deleted for posts or comments that were deleted but remain for context or threading.","Don't include default, icon, placeholder, or author images in image."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Education Q&A","slug":"education-qa","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/education-qa","status":"limited","statusNote":"Education Q&A carousel shows only for education-related searches, on desktop and mobile. Languages/regions: English (all regions), Portuguese (all regions), Spanish (Mexico only), Vietnamese (all regions). Applies to flashcard pages marked up with Quiz.","triggerTypes":["Quiz"],"entity":{"properties":[{"name":"hasPart","level":"required","expects":["Question"],"array":true,"constraints":{"minItems":1,"note":"Nested information about the specific flashcard question for the quiz. Repeat hasPart for multiple flashcards."},"message":"Quiz requires hasPart with at least one flashcard Question","nested":{"properties":[{"name":"acceptedAnswer","level":"required","expects":["Answer"],"array":false,"constraints":{"note":"The full text of the answer to a flashcard. There must only be one acceptedAnswer property per Question type."},"message":"Question requires exactly one acceptedAnswer","nested":{"properties":[{"name":"text","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full text of the answer."},"message":"Answer requires text"}],"anyOf":[]}},{"name":"eduQuestionType","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["Flashcard"],"note":"The type of question. You must use this fixed value: Flashcard"},"message":"eduQuestionType must be 'Flashcard'"},{"name":"text","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full text of the flashcard question."},"message":"Question requires text: the full flashcard question"}],"anyOf":[]}},{"name":"about","level":"recommended","expects":["Thing"],"array":false,"constraints":{"note":"Nested information about the underlying concept behind the Quiz."},"message":"Add about: the underlying concept of the quiz","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"The name of the underlying concept behind the Quiz, e.g. 'Cell transport'. Multiple entries allowed."},"message":"Add about.name"}],"anyOf":[]}},{"name":"educationalAlignment","level":"recommended","expects":["AlignmentObject"],"array":true,"constraints":{"note":"The quiz's alignment to an established educational framework. Repeat for multiple alignments."},"message":"Add educationalAlignment (educationalSubject and/or educationalLevel)","nested":{"properties":[{"name":"alignmentType","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["educationalSubject","educationalLevel"],"note":"A category of alignment between the learning resource and the framework node (LRMI standard). educationalSubject: the field/domain of study; educationalLevel: the grade or standard."},"message":"alignmentType should be educationalSubject or educationalLevel"},{"name":"targetName","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of a node of an established educational framework, e.g. 'Grade 7: Cell Structure'."},"message":"Add targetName for the educational framework node"}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"eduqa_single_accepted_answer","level":"error","description":"Each Question must have exactly one acceptedAnswer (not an array of several)"},{"id":"eduqa_all_flashcard","level":"error","description":"All questions must use the value Flashcard for eduQuestionType (values such as Multiple choice or Checkbox are not eligible)"},{"id":"eduqa_visible_questions","level":"warning","description":"Questions must be immediately visible on the page, not only in files such as PDFs"},{"id":"eduqa_not_qapage","level":"info","description":"For a single question with user-submitted answers, use QAPage markup instead"}],"guidelines":["Add structured data to the most detailed leaf page possible; don't add it to pages without questions.","All questions must use the Flashcard value for the eduQuestionType property.","Questions must be immediately visible to users on the page, not hidden in files or PDFs.","Make sure Googlebot can crawl your site efficiently.","Pages must contain education-related questions and answers, with at least one accurate question and answer pair.","Follow the same content guidelines as for Q&A pages; inaccurate content may make pages ineligible and violations may lead to a manual action."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Employer aggregate rating","slug":"employer-rating","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/employer-rating","status":"active","statusNote":"","triggerTypes":["EmployerAggregateRating"],"entity":{"properties":[{"name":"itemReviewed","level":"required","expects":["Organization"],"array":false,"constraints":{"note":"Must point to a schema.org/Organization representing the company being rated"},"message":"The organization that is being rated","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The name of the organization being rated"},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"The URL of the organization being rated"}],"anyOf":[]}},{"name":"ratingCount","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"At least one of ratingCount or reviewCount is required"},"message":"The total number of ratings of the organization on your site"},{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"note":"Number, fraction or percentage. Default scale is 1 to 5."},"message":"A numerical quality rating for the organization"},{"name":"reviewCount","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"At least one of ratingCount or reviewCount is required"},"message":"The number of people who provided a review with or without a rating"},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Defaults to 5 if omitted"},"message":"The highest value allowed in this rating system"},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Defaults to 1 if omitted"},"message":"The lowest value allowed in this rating system"}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required"}]},"customChecks":[{"id":"er_count_anyof","level":"error","description":"ratingCount and reviewCount are individually marked required on the doc but only one is needed; enforce the anyOf rule, not both"},{"id":"er_value_in_range","level":"error","description":"ratingValue must be within worstRating..bestRating (defaults 1..5)"}],"guidelines":["Ratings must be available to users from the page where you add EmployerAggregateRating.","Users must be able to post their own ratings on your site, and your site must host those ratings."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Estimated salary","slug":"estimated-salary","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/estimated-salary","status":"deprecated","statusNote":"Phase-out announced Jun 12, 2025 (Simplifying the search results page). Removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters, and doc removed, Sep 9, 2025 (no longer shown in Google Search results). Doc URL now redirects to the updates changelog.","triggerTypes":["Occupation","OccupationAggregationByEmployer"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"estimated_salary_deprecated","level":"warning","description":"Estimated salary rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Event","slug":"event","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/event","status":"active","statusNote":"Available in Australia, Brazil, Canada, Germany, India, Latin America, Spain, UK, US in English, Portuguese, German and Spanish. Virtual experiences with no real-world component aren't supported; events must take place in a physical location.","triggerTypes":["Event"],"entity":{"properties":[{"name":"location","level":"required","expects":["Place"],"array":false,"constraints":{"note":"Set the @type to Place and add location.address and location.name. Virtual-only events (VirtualLocation) aren't supported."},"message":"The location of the event. Set the @type to Place and add location.address and location.name","nested":{"properties":[{"name":"address","level":"required","expects":["PostalAddress"],"array":false,"constraints":{"note":"The venue's detailed street address. A city name alone (for example 'Sydney') is not recommended; give the full address (for example 'Bennelong Point, Sydney NSW 2000, Australia')."},"message":"The venue's detailed street address","nested":{"properties":[{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"The street address"},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"The city or locality"},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"The region, state or province"},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"The postal code"},{"name":"addressCountry","level":"recommended","expects":["Text","Country"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The country, as a two-letter ISO 3166-1 alpha-2 code"}],"anyOf":[]}},{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Don't put the title of the event in this field"},"message":"The detailed name of the place or venue where the event is being held. Don't put the title of the event in this field"}],"anyOf":[]}},{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full title of the event. Don't put the name of the event location; don't include event type, URLs, prices or performer names unless part of the title"},"message":"The full title of the event. Don't put the name of the event location"},{"name":"startDate","level":"required","expects":["DateTime","Date"],"array":false,"constraints":{"note":"ISO 8601. Add both the date and time. Specify the timezone with a UTC/GMT offset; if absent, Google uses the timezone of the event location. Use a date only (for example 2019-08-15) for all-day events; don't default to midnight as a start time."},"message":"The start date and start time of the event in ISO 8601 format"},{"name":"description","level":"recommended","expects":["Text"],"array":false,"message":"Description of the event. Describe all details of the event to make it easier for users to understand and attend"},{"name":"endDate","level":"recommended","expects":["DateTime","Date"],"array":false,"constraints":{"note":"ISO 8601, same format as startDate. For multi-day events specify both start and end dates."},"message":"The end date and end time of the event in ISO 8601 format"},{"name":"eventStatus","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/EventScheduled","https://schema.org/EventCancelled","https://schema.org/EventPostponed","https://schema.org/EventRescheduled"],"note":"Defaults to EventScheduled if omitted. EventCancelled: keep all other values as before the cancelation. EventPostponed: keep the original startDate until the new date is known. EventRescheduled: update startDate and endDate, optionally add previousStartDate. When the status changes, don't remove startDate."},"message":"The status of the event; defaults to EventScheduled"},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"minWidthPx":720,"aspectRatios":["16x9","4x3","1x1"],"minPixels":50000},"note":"Recommended width 1920px, minimum 720px. Multiple high-resolution images recommended. Image URLs must be crawlable and indexable; images must represent the marked up content and be in a file format supported by Google Images"},"message":"URL of an image or logo for the event or tour (1920px wide recommended, minimum 720px)"},{"name":"offers","level":"recommended","expects":["Offer"],"array":true,"constraints":{"note":"A nested Offer, one for each ticket type"},"message":"A nested Offer, one for each ticket type","nested":{"properties":[{"name":"availability","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/InStock","https://schema.org/SoldOut","https://schema.org/PreOrder"],"note":"InStock: tickets in stock; SoldOut: sold out; PreOrder: available for preorder"},"message":"One of InStock, SoldOut, PreOrder"},{"name":"price","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"The lowest available price, including service charges and fees. Use 0 for free events."},"message":"The lowest available price for your tickets, including service charges and fees"},{"name":"priceCurrency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"The 3-letter ISO 4217 currency code"},{"name":"validFrom","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601. Only required on date-restricted offers."},"message":"The date and time when tickets go on sale, in ISO 8601 format"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"Must lead to a landing page that clearly provides the ability to buy tickets, be clickable from the event page, and be crawlable by Googlebot"},"message":"The URL of a page providing the ability to buy tickets"}],"anyOf":[]}},{"name":"organizer","level":"recommended","expects":["Organization","Person"],"array":false,"message":"The person or organization that is hosting the event","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"The name of the person or organization that's hosting the event"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"The event host's domain URL"}],"anyOf":[]}},{"name":"performer","level":"recommended","expects":["Person","PerformingGroup"],"array":true,"message":"The participants performing at the event, such as artists and comedians","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"The name of the participant performing at the event"}],"anyOf":[]}},{"name":"previousStartDate","level":"optional","expects":["DateTime","Date"],"array":true,"constraints":{"note":"Only for rescheduled events; may be repeated for events postponed and rescheduled multiple times. Requires eventStatus EventRescheduled."},"message":"The previously scheduled start date if the event has been rescheduled"}],"anyOf":[]},"customChecks":[{"id":"event_previous_start_requires_rescheduled","level":"error","description":"If previousStartDate is present, eventStatus must be present and equal https://schema.org/EventRescheduled"},{"id":"event_location_physical","level":"error","description":"location must be a Place with a PostalAddress; VirtualLocation-only events (no physical location) are not supported"},{"id":"event_end_after_start","level":"warning","description":"endDate, when present, should not be before startDate and should use the same format as startDate"},{"id":"event_startdate_timezone","level":"warning","description":"startDate with a time component should include a UTC/GMT offset; otherwise Google uses the location's timezone"},{"id":"event_startdate_midnight","level":"warning","description":"startDate time of 00:00 may be a placeholder; don't use midnight unless the event really starts then (use a date only for all-day events)"},{"id":"event_name_not_venue","level":"warning","description":"name should not equal location.name; the event title must not be the venue name and the venue name must not be the event title"},{"id":"event_name_no_price_url","level":"warning","description":"name should not contain URLs or prices"},{"id":"event_offer_price_currency","level":"warning","description":"If offers.price is present, offers.priceCurrency should be present (3-letter ISO 4217)"},{"id":"event_status_keep_startdate","level":"error","description":"startDate must remain present when eventStatus is EventCancelled, EventPostponed or EventRescheduled"}],"guidelines":["Each event should be on its own unique leaf page; prefer a single event per page over event listings.","For events running over several days, specify both start and end dates; for several performances with individual tickets, add a separate Event element for each performance.","Don't mark up non-events as events: products or services, short-term discounts or coupons, business hours, or school-based minor events.","Virtual experiences with no real-world component aren't supported; events must take place in a physical location.","Events must be bookable to the general public.","Include the timezone as a UTC/GMT offset; use a date only for all-day events; don't default to midnight start times.","When an event is canceled, postponed or rescheduled, update eventStatus and keep startDate; don't remove other properties.","offers.url must lead to a crawlable page where tickets can be bought."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Fact check","slug":"factcheck","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/factcheck","status":"deprecated","statusNote":"Phase-out announced Jun 12, 2025 (Simplifying the search results page). Removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters Sep 9, 2025. Doc page still live (last updated Sep 8, 2026) with the notice: We're phasing out support for ClaimReview markup in Google Search; this markup remains supported by the Fact Check Explorer tool.","triggerTypes":["ClaimReview"],"entity":{"properties":[{"name":"claimReviewed","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":75,"note":"Advisory: try to keep this less than 75 characters to minimize wrapping on mobile."},"message":"A short summary of the claim being evaluated."},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"The assessment of the claim. This object supports both a numeric and a textual assessment.","nested":{"properties":[{"name":"alternateName","level":"required","expects":["Text"],"array":false,"message":"The truthfulness rating assigned to ClaimReview.reviewRating, as a human-readable short word or phrase. The textual value is currently the only value shown in search results."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Must be greater than worstRating. Must be able to be evaluated as a number."},"message":"For numeric ratings, the best value possible in the scale from worst to best."},{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Same as alternateName, and used when alternateName is not provided."},{"name":"ratingValue","level":"recommended","expects":["Number"],"array":false,"message":"A numeric rating of this claim, in the range worstRating to bestRating inclusive."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":1,"note":"Must be less than bestRating. Must be able to be evaluated as a number. Must have a minimum value of 1."},"message":"For numeric ratings, the worst value possible in a scale from worst to best."}],"anyOf":[]}},{"name":"url","level":"required","expects":["URL"],"array":false,"message":"Link to the page hosting the full article of the fact check."},{"name":"author","level":"recommended","expects":["Organization","Person"],"array":false,"message":"The publisher of the fact check article, not the publisher of the claim.","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Name of the organization that is publishing the fact check."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"The URL of the publisher of the fact check. This can be a home page, contact page, or other appropriate page."}],"anyOf":[]}},{"name":"itemReviewed","level":"recommended","expects":["Claim"],"array":false,"message":"An object describing the claim being made.","nested":{"properties":[{"name":"appearance","level":"recommended","expects":["URL","CreativeWork"],"array":true,"message":"A link to, or inline description of, a CreativeWork in which this claim appears."},{"name":"author","level":"recommended","expects":["Organization","Person"],"array":false,"message":"The author of the claim, not the author of the fact check.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The publisher of the claim. The publisher can be a person or organization."},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"Indicates the party that is making the claim, regardless of whether the party is a Person or Organization."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["DateTime","Date"],"array":false,"message":"The date when the claim was made or entered public discourse."},{"name":"firstAppearance","level":"recommended","expects":["URL","CreativeWork"],"array":false,"message":"A link to, or inline description of, a CreativeWork in which this specific claim first appears."}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"factcheck_deprecated","level":"warning","description":"ClaimReview rich results are being phased out of Google Search; the markup remains supported by Fact Check Explorer."},{"id":"claimreview_single_per_page","level":"warning","description":"To be eligible for the single fact check rich result, a page must only have one ClaimReview element."},{"id":"rating_worst_lt_best","level":"error","description":"reviewRating.worstRating must be at least 1 and less than bestRating; ratingValue must be within worstRating to bestRating inclusive."},{"id":"rating_text_present","level":"error","description":"reviewRating must have alternateName, or name when alternateName is not provided."}],"guidelines":["Your site must have several pages marked with ClaimReview structured data.","Structured data must match the visible fact check content on the page.","Follow the accountability, transparency, readability and site misrepresentation standards of Google News.","Have a corrections policy or a mechanism for users to report errors.","Websites for political entities (campaigns, parties, elected officials) are not eligible.","Readers must be able to identify the claims checked and the conclusions reached in the article body.","Clearly attribute the specific claim to a distinct origin separate from your organization.","The fact check analysis must be traceable and transparent about sources and methods, with citations to primary sources.","A page hosting ClaimReview must contain at least a brief summary of the fact check and the evaluation.","Do not duplicate the same ClaimReview across multiple pages; aggregated fact checks must meet the criteria and be publicly listed."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"FAQ","slug":"faqpage","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/faqpage","status":"deprecated","statusNote":"Limited to well-known, authoritative government and health sites from Aug 8, 2023. Deprecation notice added May 8, 2026: FAQ rich results no longer appear in Google Search starting May 7, 2026. Doc removed Jun 15, 2026 (URL now redirects to the updates changelog). Search Console report and Rich Results Test support removed in stages from Jun 2026; Search Console API support removal scheduled for Aug 2026.","triggerTypes":["FAQPage"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"faqpage_deprecated","level":"warning","description":"FAQ rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"How-to","slug":"how-to","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/how-to","status":"deprecated","statusNote":"Limited to desktop only Aug 8, 2023 (mobile removed); desktop removed Sep 13, 2023, at which point Google declared the result type deprecated. Search appearance report and Rich Results Test support dropped within 30 days, Search Console API support within 180 days. Doc page removed; URL now redirects to the updates changelog.","triggerTypes":["HowTo"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"how_to_deprecated","level":"warning","description":"How-to rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Image metadata (license)","slug":"image-license-metadata","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/image-license-metadata","status":"active","statusNote":"Google Images can show creator, credit and copyright details and a Licensable badge. Either structured data or IPTC photo metadata (or both) can be used; if they conflict, Google uses the structured data. The license property is needed for the Licensable badge.","triggerTypes":["ImageObject"],"entity":{"properties":[{"name":"contentUrl","level":"required","expects":["URL"],"array":false,"constraints":{"note":"A URL to the actual image content. Google uses contentUrl to determine which image the photo metadata applies to."},"message":"Missing contentUrl: the URL of the actual image file"},{"name":"acquireLicensePage","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL to a page where the user can find information on how to license that image. IPTC equivalent: Licensor URL (of a Licensor)."},"message":"Add acquireLicensePage: a page explaining how to license the image"},{"name":"creator","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"The creator of the image. This is usually the photographer, but it may be a company or organization. IPTC equivalent: Creator."},"message":"Add creator: the photographer, company or organization that created the image","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the creator."},"message":"Add creator.name"}],"anyOf":[]}},{"name":"creditText","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the person and/or organization that is credited for the image when it's published. IPTC equivalent: Credit Line."},"message":"Add creditText: who is credited when the image is published"},{"name":"copyrightNotice","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The copyright notice for claiming the intellectual property for this photograph. IPTC equivalent: Copyright Notice."},"message":"Add copyrightNotice"},{"name":"license","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL to a page that describes the license governing an image's use, for example a terms and conditions page or a Creative Commons license page. Needed for the Licensable badge. IPTC equivalent: Web Statement of Rights."},"message":"Add license: a URL describing the license governing the image's use"}],"anyOf":[{"level":"required","props":["creator","creditText","copyrightNotice","license"],"message":"Include at least one of creator, creditText, copyrightNotice or license"}]},"customChecks":[{"id":"imagelicense_creator_name","level":"warning","description":"If creator is a Person or Organization object, it should include name"},{"id":"imagelicense_licensable_badge","level":"info","description":"The Licensable badge requires license; acquireLicensePage is recommended alongside it"},{"id":"imagelicense_url_values","level":"error","description":"contentUrl, license and acquireLicensePage must be absolute URLs"}],"guidelines":["Each image needs its own ImageObject with contentUrl identifying the image the metadata applies to.","You only need one form of information (structured data or IPTC photo metadata) to be eligible for enhancements like the Licensable badge.","If structured data and IPTC photo metadata conflict, Google uses the structured data.","IPTC mappings: Web Statement of Rights = license, Licensor URL = acquireLicensePage, Credit Line = creditText, Creator = creator, Copyright Notice = copyrightNotice."],"lastUpdatedOnDoc":"2025-12-10"},{"feature":"Job posting","slug":"job-posting","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/job-posting","status":"active","statusNote":"Available in parts of Asia, Europe, MENA, all of Latin America, North America and Sub-Saharan Africa. Education and experience properties are beta: you may not see any appearance or effect right away. Google recommends the Indexing API over sitemaps for job posting URLs.","triggerTypes":["JobPosting"],"entity":{"properties":[{"name":"datePosted","level":"required","expects":["Date","DateTime"],"array":false,"constraints":{"note":"ISO 8601, for example 2017-01-24 or 2017-01-24T19:33:17+00:00"},"message":"The original date that employer posted the job in ISO 8601 format"},{"name":"description","level":"required","expects":["Text"],"array":false,"constraints":{"note":"HTML. Full representation of the job including responsibilities, qualifications, skills, working hours, education and experience requirements. At minimum add paragraph breaks with <br>, <p> or \\n. Recognized tags: <p>, <ul>, <li>. Can't be the same as title."},"message":"The full description of the job in HTML format"},{"name":"hiringOrganization","level":"required","expects":["Organization"],"array":false,"constraints":{"note":"The company offering the job (for example 'Starbucks, Inc'), not the specific location hiring. Use the value 'confidential' for anonymous hiring."},"message":"The organization offering the job position","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Company name, or 'confidential' if hiring anonymously"},"message":"The name of the hiring company"},{"name":"sameAs","level":"recommended","expects":["URL"],"array":false,"message":"The company's URL"},{"name":"logo","level":"recommended","expects":["URL","ImageObject"],"array":false,"constraints":{"note":"For third-party job sites; the image width and height ratio must be between 0.75 and 2.5"},"message":"The hiring organization's logo; width/height ratio must be between 0.75 and 2.5"}],"anyOf":[]}},{"name":"jobLocation","level":"required","expects":["Place"],"array":true,"constraints":{"note":"Physical location(s) where the employee reports to work. Use an array for multiple locations. Not required if applicantLocationRequirements is present (fully remote jobs). addressCountry must be included."},"message":"The physical location(s) of the business where the employee will report to work","nested":{"properties":[{"name":"address","level":"required","expects":["PostalAddress"],"array":false,"message":"The PostalAddress of the work location","nested":{"properties":[{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"The street address"},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"The city"},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"The state or province"},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"The postal code"},{"name":"addressCountry","level":"required","expects":["Text","Country"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"You must include the addressCountry property"}],"anyOf":[]}}],"anyOf":[]}},{"name":"title","level":"required","expects":["Text"],"array":false,"constraints":{"note":"Title of the job only (not of the posting), for example 'Software Engineer'. Don't include job codes, addresses, dates, salaries, company names, or excessive special characters."},"message":"The title of the job (not the title of the posting)"},{"name":"applicantLocationRequirements","level":"optional","expects":["AdministrativeArea","Country","State"],"array":true,"constraints":{"note":"Required for 100% remote jobs that restrict where applicants may be located. The job description must clearly state the eligible location(s)."},"message":"The geographic location(s) in which employees may be located to be eligible for the work from home job","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"The name of the country or state"}],"anyOf":[]}},{"name":"baseSalary","level":"recommended","expects":["MonetaryAmount"],"array":false,"constraints":{"note":"Only employers can provide baseSalary"},"message":"The actual base salary for the job, as provided by the employer","nested":{"properties":[{"name":"currency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"The ISO 4217 currency code"},{"name":"value","level":"recommended","expects":["QuantitativeValue"],"array":false,"message":"The salary amount or range","nested":{"properties":[{"name":"value","level":"recommended","expects":["Number"],"array":false,"message":"An exact salary value"},{"name":"minValue","level":"recommended","expects":["Number"],"array":false,"message":"The minimum of a salary range"},{"name":"maxValue","level":"recommended","expects":["Number"],"array":false,"message":"The maximum of a salary range"},{"name":"unitText","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["HOUR","DAY","WEEK","MONTH","YEAR"]},"message":"One of HOUR, DAY, WEEK, MONTH, YEAR"}],"anyOf":[{"level":"recommended","props":["value","minValue"],"message":"Provide value, or a range with minValue and maxValue"}]}}],"anyOf":[]}},{"name":"directApply","level":"recommended","expects":["Boolean"],"array":false,"message":"Whether the URL associated with this job posting enables direct application for the job"},{"name":"employmentType","level":"recommended","expects":["Text"],"array":true,"constraints":{"enum":["FULL_TIME","PART_TIME","CONTRACTOR","TEMPORARY","INTERN","VOLUNTEER","PER_DIEM","OTHER"],"note":"Case-sensitive; more than one value allowed"},"message":"Type of employment: FULL_TIME, PART_TIME, CONTRACTOR, TEMPORARY, INTERN, VOLUNTEER, PER_DIEM or OTHER"},{"name":"identifier","level":"recommended","expects":["PropertyValue"],"array":false,"message":"The hiring organization's unique identifier for the job","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"The hiring organization name"},{"name":"value","level":"recommended","expects":["Text"],"array":false,"message":"The unique job identifier"}],"anyOf":[]}},{"name":"jobLocationType","level":"optional","expects":["Text"],"array":false,"constraints":{"enum":["TELECOMMUTE"],"note":"Only for jobs that are 100% remote. Requires at least one country via applicantLocationRequirements (preferred) or the country of a jobLocation."},"message":"Set to TELECOMMUTE for jobs in which the employee may or must work remotely 100% of the time"},{"name":"validThrough","level":"recommended","expects":["DateTime","Date"],"array":false,"constraints":{"note":"ISO 8601, for example 2017-02-24T19:33:17+00:00. Required for postings that have an expiration date; omit if the posting never expires or the date is unknown."},"message":"The date when the job posting will expire in ISO 8601 format"},{"name":"educationRequirements","level":"optional","expects":["EducationalOccupationalCredential","Text"],"array":true,"constraints":{"note":"Beta. Use 'no requirements' if there are none."},"message":"The education required for the position","nested":{"properties":[{"name":"credentialCategory","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["high school","associate degree","bachelor degree","professional certificate","postgraduate degree"]},"message":"One of high school, associate degree, bachelor degree, professional certificate, postgraduate degree"}],"anyOf":[]}},{"name":"experienceRequirements","level":"optional","expects":["OccupationalExperienceRequirements","Text"],"array":false,"constraints":{"note":"Beta. Use 'no requirements' if there are none."},"message":"The experience required for the position","nested":{"properties":[{"name":"monthsOfExperience","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"The minimum number of months of experience required"}],"anyOf":[]}},{"name":"experienceInPlaceOfEducation","level":"optional","expects":["Boolean"],"array":false,"constraints":{"note":"Beta"},"message":"Whether the job posting will accept experience in place of its formal educational qualifications"}],"anyOf":[{"level":"required","props":["jobLocation","applicantLocationRequirements"],"message":"Include jobLocation, or applicantLocationRequirements for fully remote jobs"}]},"customChecks":[{"id":"job_telecommute_country","level":"error","description":"If jobLocationType is TELECOMMUTE, at least one country must be specified via applicantLocationRequirements (preferred) or jobLocation.address.addressCountry"},{"id":"job_description_not_title","level":"error","description":"description can't be the same as title"},{"id":"job_description_html_breaks","level":"warning","description":"description should contain paragraph breaks (<br>, <p> or newline); only <p>, <ul>, <li> are recognized"},{"id":"job_expired","level":"error","description":"validThrough in the past means the job is expired; expired postings aren't allowed to keep active markup (expire via past validThrough, 404/410, or removing JobPosting markup)"},{"id":"job_title_clean","level":"warning","description":"title should not contain job codes, addresses, dates, salaries, company names or excessive special characters"},{"id":"job_salary_range","level":"warning","description":"baseSalary.value.minValue must not exceed maxValue; unitText must be HOUR, DAY, WEEK, MONTH or YEAR"},{"id":"job_logo_ratio","level":"warning","description":"hiringOrganization.logo width/height ratio must be between 0.75 and 2.5 (requires fetching the image)"}],"guidelines":["Put structured data on the most detailed leaf page possible; don't add it to pages listing jobs.","Add a JobPosting for each job posting; JobPosting markup must only be used on pages with a single job posting.","Most properties must only occur once per page unless the description says otherwise.","Remove expired jobs: set validThrough in the past, return 404/410, or remove JobPosting markup.","Don't allow incomplete descriptions, misrepresentation, profanity, ads disguised as jobs, postings without a way to apply, or postings that require payment from applicants.","Resume collection is only allowed for open positions.","Prefer the Indexing API over sitemaps for job posting URLs; sitemaps must include canonical job URLs and accurate lastmod values.","Only employers can provide baseSalary."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Learning video","slug":"learning-video","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/learning-video","status":"deprecated","statusNote":"Phase-out announced Jun 12, 2025 (Simplifying the search results page). Removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters, and doc removed, Sep 9, 2025 (no longer shown in Google Search results). Doc URL now redirects to the updates changelog.","triggerTypes":["LearningResource","VideoObject"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"learning_video_deprecated","level":"warning","description":"Learning video rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers. Regular Video structured data is unaffected."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Local business","slug":"local-business","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/local-business","status":"active","statusNote":"Use the most specific LocalBusiness subtype possible, for example Restaurant, DaySpa, HealthClub.","triggerTypes":["LocalBusiness"],"entity":{"properties":[{"name":"address","level":"required","expects":["PostalAddress"],"array":false,"constraints":{"note":"Include as many properties as possible; the more you provide, the higher quality the result"},"message":"The physical location of the business. Include as many properties as possible","nested":{"properties":[{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"The street address"},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"The city or locality"},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"The region, state or province"},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"The postal code"},{"name":"addressCountry","level":"recommended","expects":["Text","Country"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The country, as a two-letter ISO 3166-1 alpha-2 code"}],"anyOf":[]}},{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The name of the business"},{"name":"aggregateRating","level":"optional","expects":["AggregateRating"],"array":false,"constraints":{"note":"Only recommended for sites that capture reviews about other local businesses. Follow the Review snippet guidelines and aggregate rating properties."},"message":"The average rating of the local business based on multiple ratings or reviews"},{"name":"department","level":"optional","expects":["LocalBusiness"],"array":true,"constraints":{"note":"Any property in this table can be used for a department. Name format: '{store name} {department name}', unless the department name is explicitly branded."},"message":"A nested item for a single department"},{"name":"geo","level":"recommended","expects":["GeoCoordinates"],"array":false,"message":"Geographic coordinates of the business","nested":{"properties":[{"name":"latitude","level":"recommended","expects":["Number"],"array":false,"constraints":{"pattern":"^-?\\d+\\.\\d{5,}$","note":"Precision must be at least 5 decimal places"},"message":"The latitude of the business location, with at least 5 decimal places"},{"name":"longitude","level":"recommended","expects":["Number"],"array":false,"constraints":{"pattern":"^-?\\d+\\.\\d{5,}$","note":"Precision must be at least 5 decimal places"},"message":"The longitude of the business location, with at least 5 decimal places"}],"anyOf":[]}},{"name":"menu","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"For food establishments"},"message":"The fully-qualified URL of the menu","appliesTo":["FoodEstablishment"]},{"name":"openingHoursSpecification","level":"recommended","expects":["OpeningHoursSpecification"],"array":true,"constraints":{"note":"24 hours: opens 00:00 and closes 23:59. Closed all day: opens and closes 00:00. Past midnight: one spec with closes earlier than opens (for example opens 18:00, closes 03:00). Seasonal hours: add validFrom and validThrough."},"message":"Hours during which the business location is open","nested":{"properties":[{"name":"closes","level":"recommended","expects":["Time"],"array":false,"constraints":{"pattern":"^\\d{2}:\\d{2}(:\\d{2})?$","note":"hh:mm:ss format"},"message":"The time the business location closes, in hh:mm:ss format"},{"name":"dayOfWeek","level":"recommended","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/Monday","https://schema.org/Tuesday","https://schema.org/Wednesday","https://schema.org/Thursday","https://schema.org/Friday","https://schema.org/Saturday","https://schema.org/Sunday"],"note":"Short names without the URL prefix (Monday...) are also supported"},"message":"One or more of Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday"},{"name":"opens","level":"recommended","expects":["Time"],"array":false,"constraints":{"pattern":"^\\d{2}:\\d{2}(:\\d{2})?$","note":"hh:mm:ss format"},"message":"The time the business location opens, in hh:mm:ss format"},{"name":"validFrom","level":"recommended","expects":["Date"],"array":false,"constraints":{"pattern":"^\\d{4}-\\d{2}-\\d{2}$"},"message":"The start date of a seasonal business closure, in YYYY-MM-DD format"},{"name":"validThrough","level":"recommended","expects":["Date"],"array":false,"constraints":{"pattern":"^\\d{4}-\\d{2}-\\d{2}$"},"message":"The end date of a seasonal business closure, in YYYY-MM-DD format"}],"anyOf":[]}},{"name":"priceRange","level":"recommended","expects":["Text"],"array":false,"constraints":{"maxLength":99,"note":"Numerical range (for example $10-15) or number of currency signs (for example $$$). Must be shorter than 100 characters or Google won't show a price range."},"message":"The relative price range of the business; must be shorter than 100 characters"},{"name":"review","level":"optional","expects":["Review"],"array":true,"constraints":{"note":"Only recommended for sites that capture reviews about other local businesses. Follow the Review snippet guidelines."},"message":"A review of the local business"},{"name":"servesCuisine","level":"recommended","expects":["Text"],"array":true,"message":"The type of cuisine the restaurant serves","appliesTo":["FoodEstablishment"]},{"name":"telephone","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Include the country code and area code"},"message":"A business phone number meant to be the primary contact method for customers; include country and area code"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"Must be a working link"},"message":"The fully-qualified URL of the specific business location"}],"anyOf":[]},"customChecks":[{"id":"lb_specific_subtype","level":"warning","description":"@type LocalBusiness used directly; use the most specific LocalBusiness subtype possible (for example Restaurant, DaySpa, HealthClub)"},{"id":"lb_geo_precision","level":"warning","description":"geo.latitude and geo.longitude must have at least 5 decimal places"},{"id":"lb_price_range_length","level":"warning","description":"priceRange of 100 characters or longer won't be shown"},{"id":"lb_hours_format","level":"error","description":"openingHoursSpecification opens/closes must be valid times (hh:mm or hh:mm:ss); validFrom/validThrough must be YYYY-MM-DD"},{"id":"lb_department_name","level":"warning","description":"department.name should be '{store name} {department name}' unless explicitly branded"},{"id":"lb_self_serving_reviews","level":"warning","description":"aggregateRating/review on LocalBusiness is only recommended for sites capturing reviews about other local businesses (self-serving reviews aren't eligible)"}],"guidelines":["Use the most specific LocalBusiness subtype possible.","Include as many address properties as possible.","Include the country code and area code in telephone.","Only add aggregateRating and review if your site captures reviews about other local businesses; follow the Review snippet guidelines.","Follow Search Essentials, the general structured data guidelines and, if applicable, the carousel guidelines."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Loyalty program","slug":"loyalty-program","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/loyalty-program","status":"active","statusNote":"Available in Australia, Brazil, Canada, France, Germany, Mexico, the UK and the US on desktop and mobile. Nest MemberProgram under Organization (hasMemberProgram); product-level benefits go in UnitPriceSpecification under Offer with validForMemberTier and membershipPointsEarned.","triggerTypes":["MemberProgram"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The name of the loyalty program"},{"name":"description","level":"required","expects":["Text"],"array":false,"message":"The description of the loyalty program, describing the primary benefits for members"},{"name":"hasTiers","level":"required","expects":["MemberProgramTier"],"array":true,"constraints":{"minItems":1,"note":"Give tiers an @id so Offer validForMemberTier can reference them"},"message":"A loyalty program must have at least one tier","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The name of the membership tier"},{"name":"hasTierBenefit","level":"required","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/TierBenefitLoyaltyPoints","https://schema.org/TierBenefitLoyaltyPrice"]},"message":"The benefits of the tier: TierBenefitLoyaltyPoints and/or TierBenefitLoyaltyPrice"},{"name":"hasTierRequirement","level":"recommended","expects":["CreditCard","MonetaryAmount","UnitPriceSpecification","Text"],"array":false,"constraints":{"note":"If not specified, anyone can join the tier for free. CreditCard needs name; MonetaryAmount needs value and currency; UnitPriceSpecification needs price, priceCurrency, billingDuration, billingIncrement, unitCode; Text is free-form."},"message":"The requirement to join the member tier"},{"name":"membershipPointsEarned","level":"recommended","expects":["QuantitativeValue"],"array":false,"constraints":{"note":"Required when hasTierBenefit includes TierBenefitLoyaltyPoints"},"message":"The number of loyalty points earned per currency unit spent"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"A URL of the page where a shopper can sign up for this tier"}],"anyOf":[]}},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"Don't provide multiple URLs"},"message":"A URL of the page where a shopper can sign up for the loyalty program"}],"anyOf":[]},"customChecks":[{"id":"lp_points_requires_earned","level":"error","description":"If a tier's hasTierBenefit includes TierBenefitLoyaltyPoints, membershipPointsEarned must be provided on that tier"},{"id":"lp_single_url","level":"error","description":"MemberProgram.url must be a single URL, not multiple"},{"id":"lp_requirement_fields","level":"error","description":"hasTierRequirement: CreditCard needs name; MonetaryAmount needs value and currency; UnitPriceSpecification needs price, priceCurrency, billingDuration, billingIncrement, unitCode"},{"id":"lp_nested_in_org","level":"warning","description":"MemberProgram should be nested under Organization via hasMemberProgram"},{"id":"lp_tier_ids","level":"info","description":"Tiers should carry an @id so offers can reference them through validForMemberTier"}],"guidelines":["Nest MemberProgram under Organization on the page with your business's administrative details and policies.","Specify per-product loyalty benefits with UnitPriceSpecification under Offer using validForMemberTier and membershipPointsEarned.","Follow the general structured data guidelines and Search Essentials."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Math solver","slug":"math-solver","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/math-solvers","status":"active","statusNote":"Markup belongs on the math solver site's homepage. @type must be [\"MathSolver\", \"LearningResource\"].","triggerTypes":["MathSolver"],"entity":{"properties":[{"name":"@type","level":"required","expects":["Text"],"array":true,"constraints":{"enum":["MathSolver","LearningResource"],"note":"Must be the array [\"MathSolver\", \"LearningResource\"]."},"message":"@type must be [\"MathSolver\", \"LearningResource\"]"},{"name":"potentialAction","level":"required","expects":["SolveMathAction"],"array":true,"constraints":{"note":"The action that leads to a mathematical explanation (for example, a step-by-step solution or graph) of a math expression."},"message":"Missing potentialAction SolveMathAction","nested":{"properties":[{"name":"mathExpression-input","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["required name=math_expression_string"],"note":"A placeholder for a mathematical expression (for example, x^2-3x=0) that Google sends to your website. Expressions can be LaTeX, ASCII-Math or keyboard-writable. Use the value: required name=math_expression_string"},"message":"mathExpression-input must be 'required name=math_expression_string'"},{"name":"target","level":"required","expects":["EntryPoint","URL"],"array":false,"constraints":{"pattern":"\\{math_expression_string\\}","note":"The URL target entrypoint for an action, accepting a math expression via the placeholder, e.g. https://math.example.com/solve?q={math_expression_string}"},"message":"target must be a URL template containing {math_expression_string}"},{"name":"eduQuestionType","level":"recommended","expects":["Text"],"array":true,"constraints":{"enum":["Absolute Value Equation","Algebra","Arc Length","Arithmetic","Biquadratic Equation","Calculus","Characteristic Polynomial","Circle","Derivative","Differential Equation","Distance","Eigenvalue","Eigenvector","Ellipse","Exponential Equation","Function","Function Composition","Geometry","Hyperbola","Inflection Point","Integral","Intercept","Limit","Line Equation","Linear Algebra","Linear Equation","Linear Inequality","Logarithmic Equation","Logarithmic Inequality","Matrix","Midpoint","Parabola","Parallel","Perpendicular","Polynomial Equation","Polynomial Expression","Polynomial Inequality","Quadratic Equation","Quadratic Expression","Quadratic Inequality","Radical Equation","Radical Inequality","Rational Equation","Rational Expression","Rational Inequality","Slope","Statistics","System of Equations","Trigonometry"],"note":"The problem type(s) capable of being solved by the potentialAction.target. Values from Google's problem type definitions; compare case-insensitively."},"message":"eduQuestionType values must come from Google's math problem type list"}],"anyOf":[]}},{"name":"url","level":"required","expects":["URL"],"array":false,"constraints":{"note":"The URL of the MathSolver."},"message":"Missing url: the URL of the math solver"},{"name":"usageInfo","level":"required","expects":["URL"],"array":false,"constraints":{"note":"The privacy policy for your math problem solving site."},"message":"Missing usageInfo: the URL of your privacy policy"},{"name":"assesses","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"The problem type(s) that are solved with the HowTo markup when used together with MathSolver markup. Values from the same problem type list as eduQuestionType."},"message":"Add assesses: problem types solved (from Google's problem type list)"},{"name":"inLanguage","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"The language(s) that are supported by your math problem solving site, e.g. 'en', 'es'."},"message":"Add inLanguage: languages supported by the solver"},{"name":"learningResourceType","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["Math Solver"],"note":"The type of the learning resource. Use this fixed value: Math Solver"},"message":"learningResourceType should be 'Math Solver'"}],"anyOf":[]},"customChecks":[{"id":"mathsolver_type_array","level":"error","description":"@type must include both MathSolver and LearningResource"},{"id":"mathsolver_homepage","level":"warning","description":"MathSolver markup should be placed on the site homepage"},{"id":"mathsolver_assesses_enum","level":"warning","description":"assesses values should come from Google's problem type definitions list (same list as eduQuestionType)"},{"id":"mathsolver_usageinfo_url","level":"error","description":"usageInfo must be an absolute URL to the site's privacy policy"}],"guidelines":["Add MathSolver structured data to the homepage of your site.","Make sure Googlebot can crawl your site efficiently.","If the same math solver is available at multiple URLs, use canonical URLs on each page.","The solution and step-by-step walkthrough must be accessible to users who navigate from Google (additional content may be gated).","Don't use math solver markup for promotional content or content that is not a math solver.","Math solvers must be accurate; inaccurate or low-quality solvers may be removed from the feature."],"lastUpdatedOnDoc":"2025-12-18"},{"feature":"Merchant listing","slug":"merchant-listing","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/merchant-listing","status":"active","statusNote":"Only pages where a shopper can purchase a product are eligible for merchant listing experiences. Required merchant listing properties also make the page eligible for product snippets.","triggerTypes":["Product"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the name of the product."},{"name":"image","level":"required","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"minPixels":50000,"aspectRatios":["16x9","4x3","1x1"],"formats":["BMP","GIF","JPEG","PNG","WebP","SVG","AVIF"]},"note":"Image URLs must be crawlable and indexable. Images must represent the marked up content and be in a format supported by Google Images. Minimum 50K pixels (width x height) is a recommendation."},"message":"Add image: the URL of a product photo. Prefer multiple high resolution images."},{"name":"offers","level":"required","expects":["Offer"],"array":true,"message":"Add offers: a nested Offer to sell the product. AggregateOffer is not supported for merchant listings.","nested":{"properties":[{"name":"price","level":"optional","expects":["Number","Text"],"array":false,"constraints":{"minValue":0,"note":"Required via anyOf with priceSpecification. Unlike product snippets, merchant listing experiences require a price greater than zero. Value can be a JSON number or string, using a dot as decimal separator. If both offers.price and offers.priceSpecification encode an active price, Google uses offers.price and ignores priceSpecification."},"message":"Add offers.price (or priceSpecification.price): the current, active offer price. Must be greater than zero."},{"name":"priceCurrency","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Required via anyOf with priceSpecification.priceCurrency. Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add offers.priceCurrency (or priceSpecification.priceCurrency) in three-letter ISO 4217 format."},{"name":"priceSpecification","level":"optional","expects":["UnitPriceSpecification"],"array":true,"message":"Add priceSpecification for complex pricing (strikethrough, member, unit prices).","nested":{"properties":[{"name":"price","level":"required","expects":["Number","Text"],"array":false,"constraints":{"minValue":0,"note":"Must be > 0."},"message":"Add price: the offer price. Must be greater than zero for merchant listings."},{"name":"priceCurrency","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add priceCurrency in ISO 4217 format."},{"name":"priceType","level":"optional","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/StrikethroughPrice","https://schema.org/ListPrice"],"note":"ListPrice is the former name, StrikethroughPrice is preferred. Cannot be combined with validForMemberTier."},"message":"Add priceType StrikethroughPrice to mark a strikethrough (original) price. Active prices have neither priceType nor validForMemberTier."},{"name":"validForMemberTier","level":"optional","expects":["MemberProgramTier"],"array":true,"constraints":{"note":"Cannot be combined with priceType."},"message":"Add validForMemberTier: links the price to a loyalty tier, using @id reference to the tier defined under Organization."},{"name":"membershipPointsEarned","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Whole number."},"message":"Add membershipPointsEarned: loyalty points earned. Use only together with validForMemberTier."},{"name":"referenceQuantity","level":"optional","expects":["QuantitativeValue"],"array":false,"message":"Add referenceQuantity for unit pricing (value, unitCode such as ML, and valueReference for the base measure).","nested":{"properties":[{"name":"value","level":"required","expects":["Number","Text"],"array":false,"message":"Add referenceQuantity.value."},{"name":"unitCode","level":"required","expects":["Text"],"array":false,"message":"Add referenceQuantity.unitCode, for example ML."},{"name":"valueReference","level":"recommended","expects":["QuantitativeValue"],"array":false,"message":"Add valueReference: the base measure (value and unitCode)."}],"anyOf":[]}},{"name":"validFrom","level":"optional","expects":["DateTime","Date"],"array":false,"message":"Add validFrom: ISO 8601 start of the price validity."},{"name":"validThrough","level":"optional","expects":["DateTime","Date"],"array":false,"message":"Add validThrough: ISO 8601 end of the price validity."}],"anyOf":[]}},{"name":"availability","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/BackOrder","https://schema.org/Discontinued","https://schema.org/InStock","https://schema.org/InStoreOnly","https://schema.org/LimitedAvailability","https://schema.org/OnlineOnly","https://schema.org/OutOfStock","https://schema.org/PreOrder","https://schema.org/PreSale","https://schema.org/SoldOut"],"note":"Short names without prefix are also supported."},"message":"Add availability: specify only one ItemAvailability value."},{"name":"itemCondition","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/NewCondition","https://schema.org/RefurbishedCondition","https://schema.org/UsedCondition"]},"message":"Add itemCondition: specify only one value."},{"name":"hasMerchantReturnPolicy","level":"recommended","expects":["MerchantReturnPolicy"],"array":true,"message":"Add hasMerchantReturnPolicy, or (recommended) a global return policy under Organization.","nested":{"properties":[{"name":"applicableCountry","level":"required","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2}$","note":"Up to 50 countries."},"message":"Add applicableCountry: the ISO 3166-1 alpha-2 country code the return policy applies to."},{"name":"returnPolicyCategory","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/MerchantReturnFiniteReturnWindow","https://schema.org/MerchantReturnNotPermitted","https://schema.org/MerchantReturnUnlimitedWindow"]},"message":"Add returnPolicyCategory: the type of return policy."},{"name":"merchantReturnDays","level":"recommended","expects":["Integer","Date","DateTime"],"array":false,"constraints":{"minValue":0},"message":"Add merchantReturnDays: the number of days from the delivery date that a product can be returned. Required if returnPolicyCategory is MerchantReturnFiniteReturnWindow."},{"name":"returnMethod","level":"recommended","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/ReturnAtKiosk","https://schema.org/ReturnByMail","https://schema.org/ReturnInStore"]},"message":"Add returnMethod: how the item can be returned."},{"name":"returnFees","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FreeReturn","https://schema.org/ReturnFeesCustomerResponsibility","https://schema.org/ReturnShippingFees"]},"message":"Add returnFees: the type of return fees."},{"name":"returnShippingFeesAmount","level":"recommended","expects":["MonetaryAmount"],"array":false,"message":"Add returnShippingFeesAmount: the shipping fee for returning the product. Required if returnFees is ReturnShippingFees.","nested":{"properties":[{"name":"value","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add value (or maxValue) for the amount."},{"name":"maxValue","level":"recommended","expects":["Number"],"array":false,"message":"Add maxValue when the amount is an upper bound."},{"name":"currency","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add currency in ISO 4217 format."}],"anyOf":[{"level":"required","props":["value","maxValue"],"message":"Include value or maxValue in the MonetaryAmount."}]}},{"name":"returnPolicyCountry","level":"optional","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2}$","note":"Up to 50 countries."},"message":"Add returnPolicyCountry: the ISO 3166-1 alpha-2 country where the product has to be sent for return."},{"name":"merchantReturnLink","level":"optional","expects":["URL"],"array":false,"message":"Add merchantReturnLink: the URL of a page that describes the return policy."}],"anyOf":[]}},{"name":"shippingDetails","level":"recommended","expects":["OfferShippingDetails"],"array":true,"message":"Add shippingDetails, or (recommended) a shipping policy under Organization.","nested":{"properties":[{"name":"shippingRate","level":"required","expects":["MonetaryAmount"],"array":false,"message":"Add shippingRate: the shipping cost to the destination. Use value 0 for free shipping.","nested":{"properties":[{"name":"value","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add value (or maxValue) for the amount."},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"message":"Add maxValue when the amount is an upper bound."},{"name":"currency","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add currency in ISO 4217 format."}],"anyOf":[{"level":"required","props":["value","maxValue"],"message":"Include value or maxValue in the MonetaryAmount."},{"level":"required","props":["value","maxValue"],"message":"shippingRate needs value or maxValue"}]}},{"name":"shippingDestination","level":"required","expects":["DefinedRegion"],"array":true,"message":"Add shippingDestination: the region the shipping applies to.","nested":{"properties":[{"name":"addressCountry","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$"},"message":"Add addressCountry: the two-letter ISO 3166-1 alpha-2 country code."},{"name":"addressRegion","level":"optional","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z0-9]{1,3}$"},"message":"Add addressRegion: a 2 or 3 character ISO 3166-2 subdivision code without country prefix."},{"name":"postalCode","level":"optional","expects":["Text"],"array":true,"message":"Add postalCode for postal code specific shipping."},{"name":"postalCodeRange","level":"optional","expects":["PostalCodeRangeSpecification"],"array":true,"message":"Add postalCodeRange with postalCodeBegin and postalCodeEnd.","nested":{"properties":[{"name":"postalCodeBegin","level":"required","expects":["Text"],"array":false,"message":"Add postalCodeBegin."},{"name":"postalCodeEnd","level":"required","expects":["Text"],"array":false,"message":"Add postalCodeEnd."}],"anyOf":[]}}],"anyOf":[]}},{"name":"deliveryTime","level":"required","expects":["ShippingDeliveryTime"],"array":false,"message":"Add deliveryTime: total delay between receipt of the order and goods reaching the customer.","nested":{"properties":[{"name":"handlingTime","level":"recommended","expects":["QuantitativeValue"],"array":false,"message":"Add handlingTime: typical days between order receipt and goods leaving the warehouse.","nested":{"properties":[{"name":"minValue","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add minValue: minimum number of days."},{"name":"maxValue","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add maxValue: maximum number of days."},{"name":"unitCode","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["DAY","d"]},"message":"Add unitCode: DAY or d."}],"anyOf":[]}},{"name":"transitTime","level":"recommended","expects":["QuantitativeValue"],"array":false,"message":"Add transitTime: typical days the order is in transit.","nested":{"properties":[{"name":"minValue","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add minValue: minimum number of days."},{"name":"maxValue","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add maxValue: maximum number of days."},{"name":"unitCode","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["DAY","d"]},"message":"Add unitCode: DAY or d."}],"anyOf":[]}},{"name":"cutoffTime","level":"optional","expects":["Time"],"array":false,"message":"Add cutoffTime: time after which orders are processed the next day, ISO 8601 with offset."},{"name":"businessDays","level":"optional","expects":["OpeningHoursSpecification","DayOfWeek"],"array":true,"message":"Add businessDays: days of the week the order is processed/shipped."}],"anyOf":[]}},{"name":"doesNotShip","level":"optional","expects":["Boolean"],"array":false,"message":"Add doesNotShip: true if shipping to this destination is not available."},{"name":"shippingOrigin","level":"optional","expects":["DefinedRegion"],"array":false,"message":"Add shippingOrigin: where the item ships from.","nested":{"properties":[{"name":"addressCountry","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$"},"message":"Add addressCountry: the two-letter ISO 3166-1 alpha-2 country code."},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z0-9]{1,3}$"},"message":"Add addressRegion: a 2 or 3 character ISO 3166-2 subdivision code without country prefix."},{"name":"postalCode","level":"recommended","expects":["Text"],"array":true,"message":"Add postalCode for postal code specific shipping."},{"name":"postalCodeRange","level":"recommended","expects":["PostalCodeRangeSpecification"],"array":true,"message":"Add postalCodeRange with postalCodeBegin and postalCodeEnd.","nested":{"properties":[{"name":"postalCodeBegin","level":"required","expects":["Text"],"array":false,"message":"Add postalCodeBegin."},{"name":"postalCodeEnd","level":"required","expects":["Text"],"array":false,"message":"Add postalCodeEnd."}],"anyOf":[]}}],"anyOf":[]}}],"anyOf":[]}},{"name":"priceValidUntil","level":"recommended","expects":["Date"],"array":false,"message":"Add priceValidUntil (ISO 8601). Your listing may not display if it indicates a past date."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"Single value only."},"message":"Add url: the product page URL where the buyer can purchase. Can be omitted; don't provide multiple URLs."},{"name":"validFrom","level":"recommended","expects":["DateTime","Date"],"array":false,"message":"Add validFrom: ISO 8601 start of a sale price."},{"name":"validThrough","level":"recommended","expects":["DateTime","Date"],"array":false,"message":"Add validThrough: ISO 8601 end of a sale price."}],"anyOf":[{"level":"required","props":["price","priceSpecification"],"message":"Include offers.price or offers.priceSpecification.price."},{"level":"required","props":["priceCurrency","priceSpecification"],"message":"Include offers.priceCurrency or offers.priceSpecification.priceCurrency."},{"level":"required","props":["price","priceSpecification"],"message":"Offer needs price, or priceSpecification.price"},{"level":"required","props":["priceCurrency","priceSpecification"],"message":"Offer needs priceCurrency, or priceSpecification.priceCurrency"}]}},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"message":"Add aggregateRating. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add ratingValue: the average rating for the item."},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add ratingCount or reviewCount: the total number of ratings for the item on your site."},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required."}]}},{"name":"audience","level":"optional","expects":["PeopleAudience"],"array":false,"message":"Add audience: the suggested gender and age group. Only PeopleAudience is supported.","nested":{"properties":[{"name":"suggestedGender","level":"optional","expects":["Text","Enum"],"array":false,"constraints":{"enum":["male","female","unisex","https://schema.org/Male","https://schema.org/Female"]},"message":"Add suggestedGender: male, female or unisex."},{"name":"suggestedMinAge","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Age groups: newborn 0 to 0.25, infant 0.25 to 1, toddler 1 to 5, kids 5 to 13, adult 13 and up."},"message":"Add suggestedMinAge in years."},{"name":"suggestedMaxAge","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add suggestedMaxAge in years."}],"anyOf":[]}},{"name":"brand","level":"recommended","expects":["Brand","Organization"],"array":false,"message":"Add brand.name: the brand of the product. Specify at most one.","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Add brand.name. Maximum one."}],"anyOf":[]}},{"name":"category","level":"recommended","expects":["Text","CategoryCode"],"array":true,"constraints":{"note":"CategoryCode uses inCodeSet https://www.google.com/basepages/producttype/taxonomy-with-ids.en-US.txt and codeValue as GPC ID or full path with '>' separators (each segment must contain at least one letter)."},"message":"Add category: a custom category or Google Product Category (GPC) as CategoryCode."},{"name":"color","level":"optional","expects":["Text"],"array":false,"message":"Add color, for example red or yellow/sky blue."},{"name":"description","level":"recommended","expects":["Text"],"array":false,"message":"Add description: strongly recommended."},{"name":"gtin","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{8}$|^\\d{12,14}$"},"message":"Add gtin (or the most specific gtin8, gtin12, gtin13, gtin14). Numeric form only; URL form is not supported."},{"name":"gtin8","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{8}$"},"message":"Add gtin8 if applicable."},{"name":"gtin12","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{12}$"},"message":"Add gtin12 if applicable."},{"name":"gtin13","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{13}$"},"message":"Add gtin13 if applicable."},{"name":"gtin14","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{14}$"},"message":"Add gtin14 if applicable."},{"name":"isbn","level":"optional","expects":["Text"],"array":false,"message":"Add isbn (only valid on Book co-typed with Product). ISBN-13 recommended."},{"name":"hasAdultConsideration","level":"optional","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/SexualContentConsideration"]},"message":"Add hasAdultConsideration for adult products."},{"name":"hasCertification","level":"optional","expects":["Certification"],"array":true,"constraints":{"note":"Up to 10 certifications."},"message":"Add hasCertification: energy efficiency or other certifications.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the certification type, for example EPREL (EU energy label) or Vehicle_CO2_Class."},{"name":"issuedBy","level":"required","expects":["Organization"],"array":false,"message":"Add issuedBy: the organization that issued the certification.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add issuedBy.name."}],"anyOf":[]}},{"name":"certificationIdentification","level":"recommended","expects":["Text"],"array":false,"message":"Add certificationIdentification: the certification identifier, for example the EPREL registration number."},{"name":"certificationRating","level":"recommended","expects":["Rating"],"array":false,"message":"Add certificationRating with ratingValue, for example the energy or CO2 class (D).","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Text","Number"],"array":false,"message":"Add certificationRating.ratingValue."}],"anyOf":[]}}],"anyOf":[]}},{"name":"hasEnergyConsumptionDetails","level":"optional","expects":["EnergyConsumptionDetails"],"array":false,"constraints":{"note":"Deprecated but still supported."},"message":"Deprecated: use hasCertification for EU energy labels instead.","nested":{"properties":[{"name":"hasEnergyEfficiencyCategory","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/EUEnergyEfficiencyCategoryA3Plus","https://schema.org/EUEnergyEfficiencyCategoryA2Plus","https://schema.org/EUEnergyEfficiencyCategoryA1Plus","https://schema.org/EUEnergyEfficiencyCategoryA","https://schema.org/EUEnergyEfficiencyCategoryB","https://schema.org/EUEnergyEfficiencyCategoryC","https://schema.org/EUEnergyEfficiencyCategoryD","https://schema.org/EUEnergyEfficiencyCategoryE","https://schema.org/EUEnergyEfficiencyCategoryF","https://schema.org/EUEnergyEfficiencyCategoryG"]},"message":"Add hasEnergyEfficiencyCategory: the product's energy efficiency class."},{"name":"energyEfficiencyScaleMin","level":"recommended","expects":["Enum"],"array":false,"message":"Add energyEfficiencyScaleMin: least efficient class on the label scale."},{"name":"energyEfficiencyScaleMax","level":"recommended","expects":["Enum"],"array":false,"message":"Add energyEfficiencyScaleMax: most efficient class on the label scale."}],"anyOf":[]}},{"name":"inProductGroupWithID","level":"optional","expects":["Text"],"array":false,"message":"Add inProductGroupWithID: the product group ID this variant belongs to. Maximum one."},{"name":"isVariantOf","level":"optional","expects":["ProductGroup"],"array":false,"message":"Add isVariantOf: the ProductGroup this product is a variant of."},{"name":"material","level":"optional","expects":["Text"],"array":false,"message":"Add material, for example Leather or Cotton/Polyester."},{"name":"mpn","level":"optional","expects":["Text"],"array":false,"message":"Add mpn: the manufacturer part number."},{"name":"pattern","level":"optional","expects":["Text"],"array":false,"message":"Add pattern, for example polka dots."},{"name":"review","level":"recommended","expects":["Review"],"array":true,"message":"Add review. The reviewer's name must be a valid Person or Team.","nested":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"maxLength":100,"note":"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'."},"message":"Add author: the author of the review. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid person or organization name."}],"anyOf":[]}},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"Add reviewRating: the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Add datePublished: the date the review was published, in ISO 8601 format."}],"anyOf":[]}},{"name":"size","level":"optional","expects":["Text","SizeSpecification"],"array":false,"message":"Add size, for example XL or medium. Specify at most one value.","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Add name: a human readable size value, for example XL or medium."},{"name":"sizeGroup","level":"recommended","expects":["Enum","Text"],"array":true,"constraints":{"enum":["https://schema.org/WearableSizeGroupBig","https://schema.org/WearableSizeGroupMaternity","https://schema.org/WearableSizeGroupPetite","https://schema.org/WearableSizeGroupPlus","https://schema.org/WearableSizeGroupRegular","https://schema.org/WearableSizeGroupTall"],"note":"Enum list taken from Google Merchant Center supported structured data values (the Search Central table could not be read in full)."},"message":"Add sizeGroup: the suggested size group for the product."},{"name":"sizeSystem","level":"recommended","expects":["Enum","Text"],"array":false,"constraints":{"enum":["https://schema.org/WearableSizeSystemAU","https://schema.org/WearableSizeSystemBR","https://schema.org/WearableSizeSystemCN","https://schema.org/WearableSizeSystemDE","https://schema.org/WearableSizeSystemEurope","https://schema.org/WearableSizeSystemFR","https://schema.org/WearableSizeSystemIT","https://schema.org/WearableSizeSystemJP","https://schema.org/WearableSizeSystemMX","https://schema.org/WearableSizeSystemUK","https://schema.org/WearableSizeSystemUS"],"note":"Enum list taken from Google Merchant Center supported structured data values."},"message":"Add sizeSystem: the size system used."}],"anyOf":[]}},{"name":"sku","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\S+$"},"message":"Add sku: merchant-specific identifier. Unicode characters valid for interchange, no whitespace."},{"name":"subjectOf","level":"optional","expects":["3DModel"],"array":false,"message":"Add subjectOf: a 3D model of the product in glTF format. Maximum one.","nested":{"properties":[{"name":"encoding","level":"required","expects":["MediaObject"],"array":false,"message":"Add encoding with contentUrl to a .gltf or .glb file.","nested":{"properties":[{"name":"contentUrl","level":"required","expects":["URL"],"array":false,"constraints":{"pattern":"\\.(gltf|glb)(\\?.*)?$"},"message":"Add encoding.contentUrl: link to a glTF model file."}],"anyOf":[]}}],"anyOf":[]}}],"anyOf":[{"level":"recommended","props":["gtin","gtin8","gtin12","gtin13","gtin14","isbn","mpn","sku"],"message":"Add a product identifier: gtin (or gtin8/12/13/14), mpn, sku or isbn"}]},"customChecks":[{"id":"price_gt_zero","level":"error","description":"Offer price (offers.price or active priceSpecification.price) must be greater than zero for merchant listings."},{"id":"aggregate_offer_not_supported","level":"error","description":"offers must be Offer, not AggregateOffer, for merchant listings."},{"id":"active_price_shape","level":"error","description":"Active price is a price/priceSpecification without priceType and without validForMemberTier. priceType and validForMemberTier must not appear on the same UnitPriceSpecification. membershipPointsEarned only with validForMemberTier."},{"id":"strikethrough_higher","level":"warning","description":"A StrikethroughPrice should be higher than the active price."},{"id":"validity_order","level":"error","description":"validFrom must be earlier than or equal to validThrough/priceValidUntil."},{"id":"price_valid_until_past","level":"warning","description":"priceValidUntil in the past: listing may not display."},{"id":"finite_window_days","level":"error","description":"If returnPolicyCategory is MerchantReturnFiniteReturnWindow, merchantReturnDays is required."},{"id":"return_shipping_fee_amount","level":"error","description":"If returnFees is ReturnShippingFees, returnShippingFeesAmount is required."},{"id":"single_values","level":"warning","description":"availability, itemCondition, brand, size, inProductGroupWithID, subjectOf and offers.url: specify only one value each."},{"id":"gtin_numeric","level":"error","description":"GTIN values must be numeric (not URL form) and of length 8, 12, 13 or 14."},{"id":"sku_whitespace","level":"error","description":"sku must not contain whitespace."},{"id":"certification_max","level":"warning","description":"At most 10 hasCertification entries."},{"id":"adult_consideration_value","level":"error","description":"hasAdultConsideration only supports https://schema.org/SexualContentConsideration."},{"id":"org_level_policies","level":"info","description":"Google recommends providing a global return policy and shipping policy under Organization rather than per Offer."}],"guidelines":["Product rich results only support pages that focus on a single product (or multiple variants of the same product). Add markup to product pages, not to pages that list products or a category of products.","When offering products for sale in multiple currencies, have a distinct URL per currency.","For a Car, include both Car and Product types if you want to attach ratings to it.","Dynamically generated (JavaScript) markup can make Shopping crawls less frequent and less reliable, which can be an issue for fast changing content like price and availability; prefer markup in the initial HTML.","Content that promotes widely prohibited or regulated goods, services, or information that may facilitate serious harm (firearms and weapons, recreational drugs, tobacco and vaping products, gambling-related products) is not allowed.","Search result enhancements are shown at the discretion of each experience and may change over time; provide as much rich product information as available.","Only pages where a shopper can purchase a product are eligible for merchant listing experiences.","Image URLs must be crawlable and indexable, images must represent the marked up content, and be in a Google Images supported format.","Unit pricing (referenceQuantity) is particularly important in the EU, New Zealand and Australia for products sold by volume, length or weight.","For sale durations use validFrom and validThrough or priceValidUntil (ISO 8601); start must be earlier than or equal to end."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Movie carousel","slug":"movie-carousel","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/movie","status":"limited","statusNote":"The movie carousel is only available on mobile devices. Requires an ItemList of movies (summary page plus detail pages, or a single all-in-one page) following the carousel guidelines.","triggerTypes":["Movie"],"entity":{"properties":[{"name":"image","level":"required","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"aspectRatios":["6x9"],"formats":["JPEG","PNG","GIF"]},"note":"An image that represents the movie. Image URLs must be crawlable and indexable. Images must represent the marked up content. Images must be in .jpg, .png, or .gif format. Images must have a high resolution and have a 6:9 aspect ratio. While Google can crop images that are close to a 6:9 aspect ratio, images largely deviating from this ratio aren't eligible for the feature."},"message":"Missing image: a high-resolution 6:9 image that represents the movie"},{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The name of the movie."},"message":"Missing name: the name of the movie"},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"constraints":{"note":"Annotation for the average review score assigned to the movie. Follow the Review snippet guidelines and the list of required and recommended AggregateRating properties."},"message":"Add aggregateRating: the average review score for the movie"},{"name":"dateCreated","level":"recommended","expects":["Date","DateTime"],"array":false,"constraints":{"note":"The date the movie was released."},"message":"Add dateCreated: the movie's release date"},{"name":"director","level":"recommended","expects":["Person"],"array":true,"constraints":{"note":"The director of the movie, e.g. {\"@type\": \"Person\", \"name\": \"Bradley Cooper\"}."},"message":"Add director as a Person"},{"name":"review","level":"recommended","expects":["Review"],"array":true,"constraints":{"note":"A nested Review of the movie. Follow the Review snippet guidelines and the list of required and recommended review properties."},"message":"Add review: a nested Review of the movie"}],"anyOf":[]},"customChecks":[{"id":"movie_image_aspect","level":"warning","description":"Movie image should be close to a 6:9 (2:3) aspect ratio; images largely deviating from it are not eligible. Requires fetching image dimensions"},{"id":"movie_itemlist_structure","level":"error","description":"Carousel eligibility requires an ItemList whose itemListElement is a list of ListItem; each ListItem requires position (Integer) and either url (summary page approach: URL of the movie detail page) or item containing a full Movie object (all-in-one page approach, each item with its own url fragment)"},{"id":"movie_itemlist_positions","level":"error","description":"ListItem positions should start at 1 and increase sequentially"},{"id":"movie_itemlist_same_type","level":"error","description":"All items in the carousel list must be of the same type (Movie)"},{"id":"movie_itemlist_same_domain","level":"warning","description":"ListItem URLs should point to pages on the same domain as the summary page"},{"id":"movie_detail_pages","level":"info","description":"For the summary page approach, each detail page referenced by ListItem.url should contain Movie markup that passes this spec"}],"guidelines":["Follow the carousel guidelines, Search Essentials and the general structured data guidelines.","Use either a summary page with ListItem url entries pointing to movie detail pages, or a single all-in-one page that hosts all list information including the full Movie data.","Movie images must be crawlable, indexable, high resolution, in .jpg, .png or .gif format, and close to a 6:9 aspect ratio.","Follow the Review snippet guidelines for review and aggregateRating.","Markup that violates the structured data guidelines may lead to a manual action."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Organization","slug":"organization","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/organization","status":"active","statusNote":"There are no required properties; add the properties that apply to your organization. Influences the logo shown in Search results and the knowledge panel, and merchant knowledge panels. The former standalone logo doc redirects here.","triggerTypes":["Organization","OnlineStore","OnlineBusiness"],"entity":{"properties":[{"name":"address","level":"recommended","expects":["PostalAddress"],"array":true,"constraints":{"note":"Physical or mailing address; multiple addresses allowed for multiple locations"},"message":"The address (physical or mailing) of your organization","nested":{"properties":[{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"The street address"},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"The city or locality"},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"The region, state or province"},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"The postal code"},{"name":"addressCountry","level":"recommended","expects":["Text","Country"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The country, as a two-letter ISO 3166-1 alpha-2 code"}],"anyOf":[]}},{"name":"alternateName","level":"optional","expects":["Text"],"array":true,"message":"Another common name that your organization goes by, if applicable"},{"name":"contactPoint","level":"recommended","expects":["ContactPoint"],"array":true,"constraints":{"note":"Follow Google's recommended best practices for customer support contact"},"message":"The best way for a user to contact your business","nested":{"properties":[{"name":"email","level":"recommended","expects":["Text"],"array":false,"message":"The email address to contact your business"},{"name":"telephone","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Include the country code and area code"},"message":"The phone number to contact your business; include country and area code"}],"anyOf":[]}},{"name":"description","level":"optional","expects":["Text"],"array":false,"message":"A detailed description of your organization, if applicable"},{"name":"duns","level":"optional","expects":["Text"],"array":false,"constraints":{"note":"Google recommends iso6523Code with prefix 0060: instead"},"message":"The Dun & Bradstreet DUNS number for identifying your Organization"},{"name":"email","level":"optional","expects":["Text"],"array":false,"message":"The email address to contact your business"},{"name":"foundingDate","level":"optional","expects":["Date"],"array":false,"constraints":{"note":"ISO 8601 date"},"message":"The date your Organization was founded, in ISO 8601 date format"},{"name":"globalLocationNumber","level":"optional","expects":["Text"],"array":false,"message":"The GS1 Global Location Number identifying the location of your Organization"},{"name":"hasMemberProgram","level":"optional","expects":["MemberProgram"],"array":true,"constraints":{"note":"See the loyalty-program spec"},"message":"A loyalty program offered by your business"},{"name":"hasMerchantReturnPolicy","level":"optional","expects":["MerchantReturnPolicy"],"array":true,"constraints":{"note":"See the return-policy spec; can be overridden at product level via merchant listing markup"},"message":"The return policy used by your business"},{"name":"hasShippingService","level":"optional","expects":["ShippingService"],"array":true,"constraints":{"note":"See the shipping-policy spec; can be overridden at product level via merchant listing markup"},"message":"Shipping policy information used by your business"},{"name":"iso6523Code","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^\\d{4}:.+$","note":"ICD (International Code Designator), a colon, then the identifier. Common ICDs: 0060 (DUNS), 0088 (GLN), 0199 (LEI)."},"message":"The ISO 6523 identifier of your organization, as ICD:identifier"},{"name":"legalName","level":"optional","expects":["Text"],"array":false,"message":"The registered, legal name of your Organization, if applicable and different from name"},{"name":"leiCode","level":"optional","expects":["Text"],"array":false,"constraints":{"note":"Google recommends iso6523Code with prefix 0199: instead"},"message":"The ISO 17442 identifier for your Organization"},{"name":"logo","level":"recommended","expects":["URL","ImageObject"],"array":false,"constraints":{"image":{"minWidthPx":112},"note":"At least 112x112px. Image URLs must be crawlable and indexable; images must represent the marked up content and be in a file format supported by Google Images. Should look as intended on a purely white background. An ImageObject must have a valid contentUrl or url."},"message":"A logo representative of your organization, at least 112x112px"},{"name":"naics","level":"optional","expects":["Text"],"array":false,"message":"The North American Industry Classification System (NAICS) code for your Organization"},{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Use the same name and alternateName as your site name"},"message":"The name of your organization"},{"name":"numberOfEmployees","level":"optional","expects":["QuantitativeValue"],"array":false,"constraints":{"note":"A specific value, or a range with minValue and maxValue"},"message":"The number of employees in your Organization","nested":{"properties":[{"name":"value","level":"optional","expects":["Number"],"array":false,"message":"Exact number of employees"},{"name":"minValue","level":"optional","expects":["Number"],"array":false,"message":"Minimum of an employee range"},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"message":"Maximum of an employee range"}],"anyOf":[{"level":"recommended","props":["value","minValue"],"message":"numberOfEmployees needs value, or minValue and maxValue"}]}},{"name":"sameAs","level":"recommended","expects":["URL"],"array":true,"constraints":{"note":"For example social media or review site profiles; multiple allowed"},"message":"The URL of a page on another website with additional information about your organization"},{"name":"taxID","level":"optional","expects":["Text"],"array":false,"constraints":{"note":"Must match the country provided in address"},"message":"The tax ID associated with your Organization, matching the country in address"},{"name":"telephone","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Include the country code and area code"},"message":"A business phone number meant to be the primary contact method for customers"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"The URL of the website of your organization; helps Google uniquely identify it"},{"name":"vatID","level":"optional","expects":["Text"],"array":false,"message":"The VAT code associated with your Organization, if applicable"}],"anyOf":[]},"customChecks":[{"id":"org_logo_min_size","level":"warning","description":"logo image must be at least 112x112px (requires fetching the image)"},{"id":"org_logo_imageobject_url","level":"error","description":"If logo is an ImageObject it must have a valid contentUrl or url"},{"id":"org_iso6523_format","level":"warning","description":"iso6523Code should be ICD:identifier (for example 0199:<LEI>)"},{"id":"org_name_matches_site_name","level":"warning","description":"Organization name/alternateName should match WebSite site name markup"},{"id":"org_specific_subtype","level":"warning","description":"Use the most specific Organization subtype (for example OnlineStore instead of OnlineBusiness; a LocalBusiness subtype for local businesses)"},{"id":"org_taxid_country","level":"warning","description":"taxID should correspond to the address country"}],"guidelines":["Place Organization markup on the home page or a single page describing the organization (for example the about us page); it isn't needed on every page.","Use the most specific Organization subtype; for ecommerce use OnlineStore; for local businesses use the most specific LocalBusiness subtype.","Logo must be at least 112x112px, crawlable, indexable, and look right on a white background.","Use the same name and alternateName as your site name."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Subscription and paywalled content","slug":"paywalled-content","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/paywalled-content","status":"active","statusNote":"Not a visual rich result: tells Google which content is behind a paywall so it is not treated as cloaking. JSON-LD and microdata are accepted.","triggerTypes":["CreativeWork","Article","NewsArticle","Blog","Comment","Course","HowTo","Message","Review","WebPage"],"entity":{"properties":[{"name":"isAccessibleForFree","level":"required","expects":["Boolean"],"array":false,"constraints":{"note":"Whether the article is accessible to everyone, or if it's behind a paywall (or requires a subscription or registration). Set to false if the section is paywalled."},"message":"Missing isAccessibleForFree: set to false for paywalled content"},{"name":"hasPart","level":"recommended","expects":["WebPageElement"],"array":true,"constraints":{"note":"Marks each paywalled section. Use an array for multiple paywalled sections. Don't nest content sections."},"message":"Add hasPart WebPageElement entries identifying the paywalled sections","nested":{"properties":[{"name":"@type","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["WebPageElement"],"note":"Set the @type to WebPageElement."},"message":"hasPart @type should be WebPageElement"},{"name":"cssSelector","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^\\.[A-Za-z_-][A-Za-z0-9_-]*$","note":"A CSS selector that references the class name that you set in the HTML to specify the paywalled section. Only use .class selectors."},"message":"hasPart.cssSelector should be a .class selector matching the paywalled section"},{"name":"isAccessibleForFree","level":"recommended","expects":["Boolean"],"array":false,"constraints":{"note":"Whether this section of the article is behind a paywall (or requires a subscription or registration). Set to false if the section is paywalled."},"message":"hasPart.isAccessibleForFree should be false for the paywalled section"}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"paywall_boolean_value","level":"error","description":"isAccessibleForFree must be a boolean (true/false), or the strings 'True'/'False' in microdata; flag other values"},{"id":"paywall_haspart_when_false","level":"warning","description":"If top-level isAccessibleForFree is false, hasPart WebPageElement entries with cssSelector should identify the paywalled sections"},{"id":"paywall_class_selector_only","level":"error","description":"hasPart.cssSelector must be a class selector (starting with '.'); IDs, tag, attribute or compound selectors are not supported"},{"id":"paywall_selector_matches","level":"warning","description":"Each hasPart.cssSelector class should match at least one element in the HTML"},{"id":"paywall_no_nested_sections","level":"error","description":"Paywalled sections must not be nested: no element matched by one hasPart selector should contain another matched element"}],"guidelines":["JSON-LD and microdata formats are accepted methods for specifying structured data for paywalled content.","Don't nest content sections.","Only use .class selectors for the cssSelector property.","If you don't want the content to be accessible to the browser at serving time, choose a paywall implementation that doesn't supply the paywalled content to the browser.","For AMP pages using amp-subscriptions, make sure the authorization endpoint grants access to Googlebot and keep bot access policies consistent between AMP and non-AMP pages."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Practice problems","slug":"practice-problems","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/practice-problems","status":"deprecated","statusNote":"Deprecation announced Nov 5, 2025 (Here's an update on our efforts to simplify the search results page); support removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters starting Jan 2026. Doc removed Jan 2026 (no longer shown in Google Search results). Education Q&A (Quiz flashcards) is a separate, still documented feature.","triggerTypes":["Quiz"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"practice_problems_deprecated","level":"warning","description":"Practice problems rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers. Do not flag Quiz markup that matches the Education Q&A feature."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Product snippet","slug":"product-snippet","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/product-snippet","status":"active","statusNote":"For product pages where people can't directly purchase the product (for example editorial reviews). Pros and cons appearance only for editorial review pages, in Dutch, English, French, German, Italian, Japanese, Polish, Portuguese, Spanish and Turkish.","triggerTypes":["Product"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the name of the product."},{"name":"review","level":"recommended","expects":["Review"],"array":true,"message":"Add review: a nested Review of the product. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"maxLength":100,"note":"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'. For product reviews the reviewer's name must be a valid Person or Team, for example 'James Smith' or 'CNET Reviewers'."},"message":"Add author: the author of the review. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid person or organization name."}],"anyOf":[]}},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"Add reviewRating: the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Add datePublished: the date the review was published, in ISO 8601 format."},{"name":"positiveNotes","level":"optional","expects":["ItemList"],"array":false,"message":"Add positiveNotes: an optional nested list of positive statements (pros) about the product. Editorial reviews only.","nested":{"properties":[{"name":"itemListElement","level":"required","expects":["ListItem"],"array":true,"message":"Add positiveNotes.itemListElement: the list of statements, each wrapped in a ListItem.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add positiveNotes.itemListElement.name: the key statement of the review."},{"name":"position","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":1},"message":"Add position: position 1 signifies the first statement in the list."}],"anyOf":[]}}],"anyOf":[]}},{"name":"negativeNotes","level":"optional","expects":["ItemList"],"array":false,"message":"Add negativeNotes: an optional nested list of negative statements (cons) about the product. Editorial reviews only.","nested":{"properties":[{"name":"itemListElement","level":"required","expects":["ListItem"],"array":true,"message":"Add negativeNotes.itemListElement: the list of statements, each wrapped in a ListItem.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add negativeNotes.itemListElement.name: the key statement of the review."},{"name":"position","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":1},"message":"Add position: position 1 signifies the first statement in the list."}],"anyOf":[]}}],"anyOf":[]}}],"anyOf":[]}},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"message":"Add aggregateRating: a nested aggregate rating of the product. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add ratingValue: the average rating for the item."},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add ratingCount or reviewCount: the total number of ratings for the item on your site."},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required."}]}},{"name":"offers","level":"recommended","expects":["Offer","AggregateOffer"],"array":true,"constraints":{"note":"When @type is AggregateOffer validate against the AggregateOffer spec in customChecks (lowPrice and priceCurrency required; highPrice, offerCount recommended)."},"message":"Add offers: a nested Offer or AggregateOffer to sell the product. Use Offer (not AggregateOffer) to be eligible for the price drop enhancement.","nested":{"properties":[{"name":"price","level":"recommended","expects":["Number","Text"],"array":false,"constraints":{"minValue":0,"note":"Required via anyOf with priceSpecification. Value can be a JSON number or string, using a dot as decimal separator. If both offers.price and offers.priceSpecification encode an active price, Google uses offers.price and ignores priceSpecification."},"message":"Add offers.price (or priceSpecification.price): the offer price of the product. Use 0 for free products."},{"name":"priceSpecification","level":"recommended","expects":["UnitPriceSpecification","PriceSpecification"],"array":true,"message":"Add priceSpecification.price if offers.price is not provided.","nested":{"properties":[{"name":"price","level":"required","expects":["Number","Text"],"array":false,"constraints":{"minValue":0},"message":"Add priceSpecification.price: the offer price of the product."},{"name":"priceCurrency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add priceSpecification.priceCurrency. Optional for product snippets but strongly recommended; required for merchant listing experiences."}],"anyOf":[]}},{"name":"priceCurrency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add priceCurrency: recommended for product snippets to help Google determine the currency accurately, but required for merchant listing experiences."},{"name":"availability","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/BackOrder","https://schema.org/Discontinued","https://schema.org/InStock","https://schema.org/InStoreOnly","https://schema.org/LimitedAvailability","https://schema.org/OnlineOnly","https://schema.org/OutOfStock","https://schema.org/PreOrder","https://schema.org/PreSale","https://schema.org/SoldOut"],"note":"Short names without the https://schema.org/ prefix (for example InStock) are also supported. Specify only one."},"message":"Add availability: the single most appropriate ItemAvailability value."},{"name":"priceValidUntil","level":"recommended","expects":["Date"],"array":false,"constraints":{"note":"Must not be in the past."},"message":"Add priceValidUntil (ISO 8601). Your product snippet may not display if it indicates a past date."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add url: the URL of the offer."},{"name":"itemCondition","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/NewCondition","https://schema.org/RefurbishedCondition","https://schema.org/UsedCondition"]},"message":"Add itemCondition: the condition of the product, for example NewCondition or UsedCondition."}],"anyOf":[{"level":"required","props":["price","priceSpecification","lowPrice"],"message":"Include offers.price, offers.priceSpecification.price, or lowPrice for an AggregateOffer."}]}},{"name":"brand","level":"recommended","expects":["Brand","Organization"],"array":false,"message":"Add brand: the brand of the product.","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Add brand.name."}],"anyOf":[]}},{"name":"description","level":"recommended","expects":["Text"],"array":false,"message":"Add description: the product description."},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"formats":["BMP","GIF","JPEG","PNG","WebP","SVG","AVIF"]}},"message":"Add image: the URL of a product photo."},{"name":"sku","level":"optional","expects":["Text"],"array":false,"message":"Add sku: the merchant-specific identifier for the product."},{"name":"mpn","level":"optional","expects":["Text"],"array":false,"message":"Add mpn: the manufacturer part number."},{"name":"gtin","level":"optional","expects":["Text"],"array":false,"message":"Add gtin (or gtin8, gtin12, gtin13, gtin14) if applicable."}],"anyOf":[{"level":"required","props":["review","aggregateRating","offers"],"message":"Include one of review, aggregateRating or offers."},{"level":"recommended","props":["sku","mpn","gtin"],"message":"Add a product identifier: gtin (or gtin8/12/13/14), mpn, sku or isbn"}]},"customChecks":[{"id":"offers_without_rating","level":"warning","description":"If offers is present but neither review nor aggregateRating, the Rich Results Test may report a product snippets warning."},{"id":"aggregate_offer_props","level":"error","description":"When offers @type is AggregateOffer: lowPrice (Number) and priceCurrency (ISO 4217) are required; highPrice and offerCount are recommended. Spec: {\"properties\": [{\"name\": \"lowPrice\", \"level\": \"required\", \"expects\": [\"Number\"], \"array\": false, \"constraints\": {\"minValue\": 0}, \"message\": \"Add lowPrice: the lowest price of all offers available. Use a dot as decimal separator.\"}, {\"name\": \"priceCurrency\", \"level\": \"required\", \"expects\": [\"Text\"], \"array\": false, \"constraints\": {\"pattern\": \"^[A-Z]{3}$\", \"note\": \"Three-letter ISO 4217 currency code, for example USD or EUR.\"}, \"message\": \"Add priceCurrency in three-letter ISO 4217 format.\"}, {\"name\": \"highPrice\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"message\": \"Add highPrice: the highest price of all offers available.\"}, {\"name\": \"offerCount\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"constraints\": {\"minValue\": 0}, \"message\": \"Add offerCount: the number of offers for the product.\"}], \"anyOf\": []}"},{"id":"price_valid_until_past","level":"warning","description":"offers.priceValidUntil must not be a past date, otherwise the product snippet may not display."},{"id":"pros_cons_min_statements","level":"error","description":"If positiveNotes or negativeNotes are present, the review must contain at least two statements in total, in any combination of positive and negative (count itemListElement entries across both lists)."},{"id":"pros_cons_editorial_only","level":"warning","description":"Pros and cons are only eligible on editorial product review pages, not merchant product pages or customer product reviews. Flag positiveNotes/negativeNotes on pages that also carry purchasable merchant offers as a reminder."},{"id":"item_list_positions","level":"warning","description":"positiveNotes/negativeNotes itemListElement position values, when given, should start at 1 and increase in list order."},{"id":"price_and_pricespec_both","level":"info","description":"If both offers.price and offers.priceSpecification encode the active price, Google uses offers.price and ignores priceSpecification."},{"id":"review_snippet_rules","level":"error","description":"Nested review and aggregateRating must also satisfy the review-snippet spec (author name < 100 chars, ratingValue within bestRating/worstRating, ratingCount or reviewCount)."}],"guidelines":["Product rich results only support pages that focus on a single product (or multiple variants of the same product). Add markup to product pages, not to pages that list products or a category of products.","When offering products for sale in multiple currencies, have a distinct URL per currency.","For a Car, include both Car and Product types if you want to attach ratings to it.","Dynamically generated (JavaScript) markup can make Shopping crawls less frequent and less reliable, which can be an issue for fast changing content like price and availability; prefer markup in the initial HTML.","Content that promotes widely prohibited or regulated goods, services, or information that may facilitate serious harm (firearms and weapons, recreational drugs, tobacco and vaping products, gambling-related products) is not allowed.","Search result enhancements are shown at the discretion of each experience and may change over time; provide as much rich product information as available.","Only editorial product review pages are eligible for the pros and cons appearance, not merchant product pages or customer product reviews.","Pros and cons need at least two statements about the product, in any combination of positive or negative statements, and should be visible on the page.","Adding the required merchant listing properties also makes product pages eligible for product snippets.","Follow the Review snippet guidelines for review and aggregateRating."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Product variants","slug":"product-variants","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/product-variants","status":"active","statusNote":"Variant markup supplements Product structured data; each variant Product must still meet merchant listing or product snippet requirements.","triggerTypes":["ProductGroup"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the name of the ProductGroup, for example Wool winter coat. Variant names are more specific."},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"message":"Add aggregateRating representative of all variants. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add ratingValue: the average rating for the item."},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add ratingCount or reviewCount: the total number of ratings for the item on your site."},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required."}]}},{"name":"brand","level":"recommended","expects":["Brand"],"array":false,"message":"Add brand: the brand of the ProductGroup (same across all variants).","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"Add brand.name."}],"anyOf":[]}},{"name":"description","level":"recommended","expects":["Text","TextObject"],"array":false,"message":"Add description of the ProductGroup; variant-specific descriptions go on the variant Product."},{"name":"hasAdultConsideration","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/SexualContentConsideration"]},"message":"Add hasAdultConsideration for adult-oriented products."},{"name":"hasVariant","level":"recommended","expects":["Product"],"array":true,"message":"Add hasVariant: a nested Product that is one of the variants of the ProductGroup.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name to each variant Product."},{"name":"sku","level":"recommended","expects":["Text"],"array":false,"message":"Add sku (or gtin): each variant must have a unique ID."},{"name":"gtin","level":"recommended","expects":["Text"],"array":false,"message":"Add gtin (or gtin8/12/13/14) as a variant identifier."},{"name":"inProductGroupWithID","level":"recommended","expects":["Text"],"array":false,"message":"Add inProductGroupWithID matching the group's productGroupID."},{"name":"isVariantOf","level":"recommended","expects":["ProductGroup"],"array":false,"message":"Add isVariantOf referencing the ProductGroup by @id (multi-page sites)."},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Add url: a distinct URL that preselects this variant."},{"name":"offers","level":"recommended","expects":["Offer"],"array":false,"message":"Add offers per variant (merchant listing requirements apply)."},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"message":"Add image for the variant."}],"anyOf":[{"level":"recommended","props":["sku","gtin","gtin8","gtin12","gtin13","gtin14"],"message":"Each variant must have a unique ID (sku or gtin)."}]}},{"name":"productGroupID","level":"recommended","expects":["Text"],"array":false,"message":"Add productGroupID: the identifier of the product group (parent sku)."},{"name":"review","level":"recommended","expects":["Review"],"array":true,"message":"Add review of the ProductGroup. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"maxLength":100,"note":"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'."},"message":"Add author: the author of the review. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid person or organization name."}],"anyOf":[]}},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"Add reviewRating: the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Add datePublished: the date the review was published, in ISO 8601 format."}],"anyOf":[]}},{"name":"url","level":"recommended","expects":["URL"],"array":false,"message":"Single-page sites only: the URL (without variant selectors) where the ProductGroup is located. Don't use on multi-page sites."},{"name":"variesBy","level":"recommended","expects":["DefinedTerm","URL"],"array":true,"constraints":{"enum":["https://schema.org/color","https://schema.org/size","https://schema.org/suggestedAge","https://schema.org/suggestedGender","https://schema.org/material","https://schema.org/pattern"],"note":"Use full Schema.org URLs, for example https://schema.org/color."},"message":"Add variesBy: aspects by which the variants vary, as full Schema.org URLs."}],"anyOf":[]},"customChecks":[{"id":"variant_product_requirements","level":"error","description":"Every hasVariant Product (and any Product with isVariantOf) must also be validated against merchant-listing (if purchasable) or product-snippet requirements."},{"id":"unique_variant_ids","level":"error","description":"Each variant must have a unique ID (sku or gtin); no duplicates within the group."},{"id":"group_id_present","level":"warning","description":"Each product group must have a unique ID via productGroupID or variants' inProductGroupWithID; when both are given they must match."},{"id":"varies_by_props_present","level":"warning","description":"For each variesBy value, each variant should specify the corresponding property (color, size, suggestedAge, suggestedGender, material, pattern) and variants should differ on them."},{"id":"single_page_url","level":"warning","description":"Single-page sites: ProductGroup.url is one canonical URL without variant selectors; variant urls preselect via parameters (for example ?size=small&color=green). Multi-page sites: don't use ProductGroup.url."},{"id":"multi_page_self_contained","level":"info","description":"Multi-page sites: each page must have full, self-contained markup for the entities on that page, repeating the ProductGroup definition and linking variants via isVariantOf."}],"guidelines":["The site must be able to preselect each variant directly with a distinct URL that shows the correct image, price and availability.","Single-page sites: there must be only one distinct canonical URL for the overall ProductGroup; markup doesn't change dynamically as users select variants.","Multi-page sites: each page must have full and self-contained markup for the entities defined on that page.","Each variant must have a unique ID and each product group must have a unique ID; identifiers given on ProductGroup and Product must align.","Add Product structured data in addition to the variant properties, following the required properties for merchant listings or product snippets.","Product rich results only support pages that focus on a single product (or multiple variants of the same product). Add markup to product pages, not to pages that list products or a category of products."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Profile page","slug":"profile-page","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/profile-page","status":"active","statusNote":"For sites where creators (people or organizations) share first-hand perspectives; used in features such as Discussions and Forums.","triggerTypes":["ProfilePage"],"entity":{"properties":[{"name":"mainEntity","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"note":"The person or organization that this profile page is about. Indicates that the primary focus of the page is information about this entity."},"message":"Add mainEntity: the Person or Organization that this profile page is about.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The primary way the person or organization is identified. Prefer the real name with the handle in alternateName; a handle is fine if it is the only identifier."},"message":"Add mainEntity.name: the primary way the person or organization is identified."},{"name":"agentInteractionStatistic","level":"optional","expects":["InteractionCounter"],"array":true,"constraints":{"note":"Statistics about the entity's own behavior. FollowAction: number of other accounts being followed. LikeAction: number of likes (generally of other entities' posts). WriteAction: number of posts. ShareAction: number of reshares of posts. enum applies to interactionType."},"message":"Add agentInteractionStatistic: user statistics about the profile entity's own behavior, if applicable.","nested":{"properties":[{"name":"interactionType","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FollowAction","https://schema.org/LikeAction","https://schema.org/WriteAction","https://schema.org/ShareAction"]},"message":"Add interactionType: FollowAction, LikeAction, WriteAction, or ShareAction."},{"name":"userInteractionCount","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":0},"message":"Add userInteractionCount: the number of times this interaction was performed."}],"anyOf":[]}},{"name":"alternateName","level":"recommended","expects":["Text"],"array":false,"message":"Add alternateName: an alternate public identifier, for example a social media handle if the real name is used in name."},{"name":"description","level":"optional","expects":["Text"],"array":false,"message":"Add description: the user's byline or applicable credential, if applicable."},{"name":"identifier","level":"optional","expects":["Text"],"array":false,"constraints":{"note":"Any unique identifier used within your site, for example an internal database ID that stays stable even if the handle changes."},"message":"Add identifier: a unique identifier used within your site, if applicable."},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":false,"constraints":{"note":"A profile image of the creator. If there are no images, don't include a default image, icon, or placeholder image. Images must be crawlable and indexable, represent the marked up content, and be high resolution."},"message":"Add image: the URL or ImageObject of a profile image. Don't use default, icon, or placeholder images."},{"name":"interactionStatistic","level":"optional","expects":["InteractionCounter"],"array":true,"constraints":{"note":"Statistics applied to the profile entity. Only include stats about the platform the profile page is hosted on. FollowAction: number of followers. LikeAction: number of likes of this entity. BefriendAction: a bi-directional relationship. enum applies to interactionType."},"message":"Add interactionStatistic: user statistics applied to the profile entity on this platform, if applicable.","nested":{"properties":[{"name":"interactionType","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FollowAction","https://schema.org/LikeAction","https://schema.org/BefriendAction"]},"message":"Add interactionType: FollowAction, LikeAction, or BefriendAction."},{"name":"userInteractionCount","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":0},"message":"Add userInteractionCount: the number of times this interaction was performed."}],"anyOf":[]}},{"name":"sameAs","level":"optional","expects":["URL"],"array":true,"message":"Add sameAs: URLs of other external profiles or home pages for the profile, if applicable."}],"anyOf":[]}},{"name":"dateCreated","level":"optional","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format."},"message":"Add dateCreated: the date and time the profile was created, if applicable, in ISO 8601 format."},{"name":"dateModified","level":"optional","expects":["DateTime"],"array":false,"constraints":{"note":"ISO 8601 format. Reflects human-edited metadata changes to the profile."},"message":"Add dateModified: the date and time information in the profile was modified, if applicable, in ISO 8601 format."}],"anyOf":[]},"customChecks":[{"id":"profile_interaction_types","level":"error","description":"interactionStatistic.interactionType must be FollowAction, LikeAction, or BefriendAction; agentInteractionStatistic.interactionType must be FollowAction, LikeAction, WriteAction, or ShareAction (accept short names or schema.org URLs). Flag WriteAction/ShareAction under interactionStatistic and BefriendAction under agentInteractionStatistic."},{"id":"profile_main_entity_type","level":"error","description":"mainEntity @type must be Person or Organization (or a subtype)."},{"id":"profile_date_order","level":"warning","description":"dateModified should not be earlier than dateCreated."},{"id":"profile_placeholder_image","level":"warning","description":"Flag mainEntity.image URLs that look like default avatars or placeholders (for example 'default', 'placeholder', 'avatar-blank', gravatar default)."}],"guidelines":["The primary focus of the page must be a single person or organization that is affiliated with the overall website.","Valid: user profile pages on forums or social media, author pages on news sites, 'About Me' pages on blogs, employee pages on company websites.","Invalid: a store's homepage, or an organization review site where the organization isn't associated with the website.","Use the real name in name and put a social media handle in alternateName; a handle in name is fine if it is the only identifier.","Only include interactionStatistic counts about the platform the profile page is hosted on.","Don't use a default image, icon, or placeholder as the profile image."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Q&A","slug":"qapage","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/qapage","status":"active","statusNote":"For pages that contain a single question followed by its answers, where users can submit answers (forums, product support pages).","triggerTypes":["QAPage"],"entity":{"properties":[{"name":"mainEntity","level":"required","expects":["Question"],"array":false,"constraints":{"note":"The Question for this page must be nested under the mainEntity property of the QAPage."},"message":"QAPage requires mainEntity Question","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full text of the short form of the question, e.g. 'How many teaspoons in a cup?'."},"message":"Question requires name: the short form of the question"},{"name":"answerCount","level":"required","expects":["Integer"],"array":false,"constraints":{"note":"The total number of answers to the question. This may also be 0 for questions with no answers.","minValue":0},"message":"Question requires answerCount (may be 0)"},{"name":"acceptedAnswer","level":"recommended","expects":["Answer"],"array":true,"constraints":{"note":"A top answer to the question. There can be zero or more of these per question. This must represent answers that are accepted in some way, such as by the question author or by moderators. Required: one of acceptedAnswer or suggestedAnswer. (Doc lists this as required in an either/or group; enforced by the anyOf rule.)"},"message":"Add acceptedAnswer or suggestedAnswer","nested":{"properties":[{"name":"text","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full text of the answer. If only a portion is marked up, your content may not be shown and Google cannot determine the best text to display."},"message":"Answer requires the full text"},{"name":"author","level":"recommended","expects":["Person","Organization"],"array":false,"constraints":{"note":"Information about the author of the answer. Follow author markup best practices."},"message":"Add answer author","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the author. Follow author markup best practices."},"message":"Add author.name"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A link to a web page that uniquely identifies the author, likely a profile page on the site."},"message":"Add author.url: a page that uniquely identifies the author"}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the answer was posted, in ISO 8601 format."},"message":"Add answer datePublished (ISO 8601)"},{"name":"dateModified","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the answer was edited, in ISO 8601 format."},"message":"Add answer dateModified (ISO 8601)"},{"name":"comment","level":"recommended","expects":["Comment"],"array":true,"constraints":{"note":"A comment pertaining to the answer. Comments can be nested; each nested Comment follows the Comment spec (see customChecks qapage_comment_spec)."},"message":"Add answer comments as Comment"},{"name":"commentCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The number of comments on this answer.","minValue":0},"message":"Add answer commentCount"},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"note":"Any inline images within the answer."},"message":"Add inline images of the answer"},{"name":"video","level":"recommended","expects":["VideoObject"],"array":true,"constraints":{"note":"Any inline videos within the answer. Follow the Video properties (see video.json)."},"message":"Add inline videos of the answer"},{"name":"digitalSourceType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"note":"If the answer was created by a trained model (AI), specify the digital source type.","enum":["https://schema.org/TrainedAlgorithmicMediaDigitalSource","https://schema.org/AlgorithmicMediaDigitalSource"]},"message":"digitalSourceType must be TrainedAlgorithmicMediaDigitalSource or AlgorithmicMediaDigitalSource"},{"name":"upvoteCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The total number of votes this answer has received. If the page supports upvotes and downvotes, set this to the aggregate value (e.g. 5 upvotes and 2 downvotes gives 3)."},"message":"Add answer upvoteCount"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL that links directly to this answer, e.g. https://www.examplesite.com/question#answer1. It is strongly recommended to provide a URL for each answer because it improves the user experience."},"message":"Add answer url (strongly recommended), e.g. a #fragment link to the answer"}],"anyOf":[]}},{"name":"suggestedAnswer","level":"recommended","expects":["Answer"],"array":true,"constraints":{"note":"One possible answer, but not accepted as a top answer. There can be zero or more per question. Required: one of acceptedAnswer or suggestedAnswer. (Doc lists this as required in an either/or group; enforced by the anyOf rule.)"},"message":"Add suggestedAnswer or acceptedAnswer","nested":{"properties":[{"name":"text","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The full text of the answer. If only a portion is marked up, your content may not be shown and Google cannot determine the best text to display."},"message":"Answer requires the full text"},{"name":"author","level":"recommended","expects":["Person","Organization"],"array":false,"constraints":{"note":"Information about the author of the answer. Follow author markup best practices."},"message":"Add answer author","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the author. Follow author markup best practices."},"message":"Add author.name"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A link to a web page that uniquely identifies the author, likely a profile page on the site."},"message":"Add author.url: a page that uniquely identifies the author"}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the answer was posted, in ISO 8601 format."},"message":"Add answer datePublished (ISO 8601)"},{"name":"dateModified","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the answer was edited, in ISO 8601 format."},"message":"Add answer dateModified (ISO 8601)"},{"name":"comment","level":"recommended","expects":["Comment"],"array":true,"constraints":{"note":"A comment pertaining to the answer. Comments can be nested; each nested Comment follows the Comment spec (see customChecks qapage_comment_spec)."},"message":"Add answer comments as Comment"},{"name":"commentCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The number of comments on this answer.","minValue":0},"message":"Add answer commentCount"},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"note":"Any inline images within the answer."},"message":"Add inline images of the answer"},{"name":"video","level":"recommended","expects":["VideoObject"],"array":true,"constraints":{"note":"Any inline videos within the answer. Follow the Video properties (see video.json)."},"message":"Add inline videos of the answer"},{"name":"digitalSourceType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"note":"If the answer was created by a trained model (AI), specify the digital source type.","enum":["https://schema.org/TrainedAlgorithmicMediaDigitalSource","https://schema.org/AlgorithmicMediaDigitalSource"]},"message":"digitalSourceType must be TrainedAlgorithmicMediaDigitalSource or AlgorithmicMediaDigitalSource"},{"name":"upvoteCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The total number of votes this answer has received. If the page supports upvotes and downvotes, set this to the aggregate value (e.g. 5 upvotes and 2 downvotes gives 3)."},"message":"Add answer upvoteCount"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL that links directly to this answer, e.g. https://www.examplesite.com/question#answer1. It is strongly recommended to provide a URL for each answer because it improves the user experience."},"message":"Add answer url (strongly recommended), e.g. a #fragment link to the answer"}],"anyOf":[]}},{"name":"text","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The full text of the long form of the question."},"message":"Add question text: the long form of the question"},{"name":"author","level":"recommended","expects":["Person","Organization"],"array":false,"constraints":{"note":"Information about the author of the question. Follow author markup best practices."},"message":"Add question author","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the author. Follow author markup best practices."},"message":"Add author.name"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A link to a web page that uniquely identifies the author, likely a profile page on the site."},"message":"Add author.url: a page that uniquely identifies the author"}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the question was posted, in ISO 8601 format."},"message":"Add question datePublished (ISO 8601)"},{"name":"dateModified","level":"recommended","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the question was edited, in ISO 8601 format."},"message":"Add question dateModified (ISO 8601)"},{"name":"comment","level":"recommended","expects":["Comment"],"array":true,"constraints":{"note":"A comment pertaining to the question. Comments can be nested; each nested Comment follows the Comment spec (see customChecks qapage_comment_spec)."},"message":"Add question comments as Comment"},{"name":"commentCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The number of comments on this question.","minValue":0},"message":"Add question commentCount"},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":true,"constraints":{"note":"Any inline images within the question."},"message":"Add inline images of the question"},{"name":"video","level":"recommended","expects":["VideoObject"],"array":true,"constraints":{"note":"Any inline videos within the question. Follow the Video properties (see video.json)."},"message":"Add inline videos of the question"},{"name":"digitalSourceType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"note":"If the question was created by a trained model (AI), specify the digital source type.","enum":["https://schema.org/TrainedAlgorithmicMediaDigitalSource","https://schema.org/AlgorithmicMediaDigitalSource"]},"message":"digitalSourceType must be TrainedAlgorithmicMediaDigitalSource or AlgorithmicMediaDigitalSource"},{"name":"upvoteCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"note":"The total number of votes this question has received. If the page supports upvotes and downvotes, set this to the aggregate value."},"message":"Add question upvoteCount"}],"anyOf":[{"level":"required","props":["acceptedAnswer","suggestedAnswer"],"message":"Question requires acceptedAnswer or suggestedAnswer"}]}}],"anyOf":[]},"customChecks":[{"id":"qapage_single_question","level":"error","description":"QAPage must have exactly one Question as mainEntity; pages with multiple questions are not eligible"},{"id":"qapage_answercount_consistency","level":"warning","description":"answerCount should be at least the number of acceptedAnswer plus suggestedAnswer items marked up"},{"id":"qapage_comment_spec","level":"error","description":"Every Comment (Question.comment, Answer.comment, nested Comment.comment) requires text (full text of the comment); recommended: author (Person or Organization with name and url), datePublished and dateModified (ISO 8601 DateTime), comment (nested Comment), commentCount (Integer), image (URL or ImageObject), video (VideoObject), digitalSourceType (TrainedAlgorithmicMediaDigitalSource or AlgorithmicMediaDigitalSource)"},{"id":"qapage_full_text","level":"warning","description":"Question and Answer text should be the entire text, not a truncated excerpt (e.g. ending with ellipsis)"},{"id":"qapage_answer_url_unique","level":"warning","description":"Each Answer.url should be unique and link directly to that answer (e.g. a #fragment on the page)"},{"id":"qapage_not_faq","level":"info","description":"If the site wrote both question and answers and users cannot submit answers, QAPage is not appropriate"},{"id":"qapage_iso_datetimes","level":"error","description":"datePublished and dateModified must be valid ISO 8601 DateTime values"}],"guidelines":["Only use QAPage markup if your page has information in a question and answer format, which is one question followed by its answers.","Users must be able to submit answers to the question; don't use it for content with only one answer for a given question and no way for users to add alternative answers.","Valid: a forum page or product support page where users submit answers to a single question.","Invalid: an FAQ page written by the site itself with no way for users to submit answers; a product page with multiple questions and answers; a how-to guide, blog post or essay answering a question.","Don't apply QAPage markup to all pages of a site or forum if not all the content is eligible.","Don't use QAPage markup for advertising purposes.","Make sure each Question and Answer includes the entire text of the question or answer.","Use the comment property for clarifications or discussion, not Answer markup.","Content with obscene, profane, sexually explicit, graphically violent, or hateful or harassing language won't be shown.","Education Q&A pages with a single expert-selected answer may instead be eligible for the education Q&A carousel."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Recipe","slug":"recipe","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/recipe","status":"active","statusNote":"Recipes can appear in Google Search results and Google Images. Host carousel eligibility requires ItemList structured data on a summary page.","triggerTypes":["Recipe"],"entity":{"properties":[{"name":"image","level":"required","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"minPixels":50000,"aspectRatios":["16x9","4x3","1x1"]},"note":"Image of the completed dish. Image URLs must be crawlable and indexable. Images must represent the marked up content. Images must be in a file format that's supported by Google Images. For best results, provide multiple high-resolution images (minimum of 50K pixels when multiplying width and height) with aspect ratios 16x9, 4x3, and 1x1."},"message":"Missing image: provide an image of the completed dish"},{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The name of the dish. Use Recipe only for content about preparing a particular dish; 'facial scrub' or 'party ideas' are not valid names for a dish."},"message":"Missing name: the name of the dish"},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"constraints":{"note":"Annotation for the average review score assigned to the item. Follow the Review snippet guidelines and the list of required and recommended AggregateRating properties."},"message":"Add aggregateRating: the average review score for the recipe"},{"name":"author","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"The name of the person or organization that wrote the recipe."},"message":"Add author: the person or organization that wrote the recipe"},{"name":"cookTime","level":"optional","expects":["Duration"],"array":false,"constraints":{"note":"The time it takes to actually cook the dish in ISO 8601 format, if applicable. Always use in combination with prepTime."},"message":"Add cookTime (ISO 8601 duration), always together with prepTime"},{"name":"datePublished","level":"optional","expects":["Date"],"array":false,"constraints":{"note":"The date the recipe was published in ISO 8601 format, if applicable."},"message":"Add datePublished in ISO 8601 format"},{"name":"description","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"A short summary describing the dish."},"message":"Add description: a short summary describing the dish"},{"name":"keywords","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"Other terms for your recipe such as the season ('summer'), the holiday ('Halloween'), or other descriptors ('quick', 'easy', 'authentic'). Separate multiple entries with commas. Don't use a tag that's actually a recipeCategory or recipeCuisine."},"message":"Add keywords (comma separated), not duplicating recipeCategory or recipeCuisine"},{"name":"nutrition","level":"recommended","expects":["NutritionInformation"],"array":false,"constraints":{"note":"Google documents nutrition.calories. If nutrition.calories is defined, recipeYield must be defined with the number of servings."},"message":"Add nutrition.calories","nested":{"properties":[{"name":"calories","level":"recommended","expects":["Energy","Text"],"array":false,"constraints":{"note":"The number of calories in each serving produced with this recipe. Example value: '270 calories'."},"message":"Add nutrition.calories: calories per serving"}],"anyOf":[]}},{"name":"prepTime","level":"optional","expects":["Duration"],"array":false,"constraints":{"note":"The length of time it takes to prepare ingredients and workspace for the dish, in ISO 8601 format, if applicable. Always use in combination with cookTime."},"message":"Add prepTime (ISO 8601 duration), always together with cookTime"},{"name":"recipeCategory","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The type of meal or course your recipe is about. For example: 'dinner', 'main course', or 'dessert, snack'."},"message":"Add recipeCategory: the type of meal or course"},{"name":"recipeCuisine","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The region associated with your recipe. For example, 'French', 'Mediterranean', or 'American'."},"message":"Add recipeCuisine: the region associated with the recipe"},{"name":"recipeIngredient","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"An ingredient used in the recipe. Include only the ingredient text that is necessary for making the recipe. Don't include unnecessary information, such as a definition of the ingredient."},"message":"Add recipeIngredient: one entry per ingredient"},{"name":"recipeInstructions","level":"recommended","expects":["HowToStep","HowToSection","Text"],"array":true,"constraints":{"note":"The steps to make the dish. HowToStep is recommended; HowToSection can group HowToSteps when the recipe has sections. A single text block that requires automatic parsing is not recommended. Don't include metadata that belongs elsewhere (author, recipeCuisine, recipeCategory, keywords). Include only text on how to make the dish; don't include text such as 'Directions', 'Watch the video', 'Step 1'. Nested spec below applies to HowToStep values. HowToSection values require name (Text) and itemListElement (HowToStep list); see customChecks recipe_howtosection."},"message":"Add recipeInstructions, preferably as HowToStep items","nested":{"properties":[{"name":"itemListElement","level":"recommended","expects":["HowToDirection","HowToTip"],"array":true,"constraints":{"note":"A list of detailed substeps, including directions or tips. Optional if text is used. (Doc lists this as required in an either/or group; enforced by the anyOf rule.)"},"message":"HowToStep needs text or itemListElement"},{"name":"text","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The full instruction text of this step. Optional if itemListElement is used. Include only instructional text; don't include 'Directions', 'Watch the video', 'Step 1'. (Doc lists this as required in an either/or group; enforced by the anyOf rule.)"},"message":"HowToStep needs text or itemListElement"},{"name":"image","level":"recommended","expects":["URL","ImageObject"],"array":false,"constraints":{"image":{"formats":["JPEG","PNG","GIF"]},"note":"An image for the step. Image URLs must be crawlable and indexable. Images must represent the marked up content. Images must be in .jpg, .png, or .gif format."},"message":"Add an image for this step"},{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The word or short phrase summarizing the step (for example, 'Arrange pie crust'). Don't use non-descriptive text (for example, 'Step 1: [text]') or other form of step number."},"message":"Add a short descriptive step name (no step numbers)"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL that directly links to the step (if one is available), for example https://example.com/recipe#step1."},"message":"Add url linking directly to the step"},{"name":"video","level":"recommended","expects":["VideoObject","Clip"],"array":false,"constraints":{"note":"A video for this step or a clip of the video."},"message":"Add a video or Clip for this step"}],"anyOf":[{"level":"required","props":["text","itemListElement"],"message":"HowToStep requires text or itemListElement"}]}},{"name":"recipeYield","level":"optional","expects":["Text","Integer"],"array":true,"constraints":{"note":"The quantity produced by the recipe, if applicable. Specify the number of servings with just a number. Additional yields in other units may be included, for example [\"6\", \"24 cookies\"]. Required if any per-serving nutritional information (such as nutrition.calories) is specified."},"message":"Add recipeYield: the number of servings as a number"},{"name":"totalTime","level":"optional","expects":["Duration"],"array":false,"constraints":{"note":"The total time it takes to prepare and cook the dish, in ISO 8601 format, if applicable. Use totalTime or a combination of both cookTime and prepTime."},"message":"Add totalTime, or both cookTime and prepTime (ISO 8601 durations)"},{"name":"video","level":"recommended","expects":["VideoObject"],"array":false,"constraints":{"note":"A video depicting the steps to make the dish. Follow the list of required and recommended Video properties (see video.json)."},"message":"Add video: a VideoObject depicting the steps to make the dish"}],"anyOf":[]},"customChecks":[{"id":"recipe_howtosection","level":"error","description":"When a recipeInstructions item is a HowToSection, it requires name (Text, the name of the section) and itemListElement (list of HowToStep, the detailed steps for the section and/or sub-sections); each nested HowToStep is validated against the HowToStep spec"},{"id":"recipe_calories_requires_yield","level":"error","description":"If nutrition.calories is present, recipeYield must be present and include the number of servings as a number"},{"id":"recipe_cook_prep_pair","level":"warning","description":"cookTime and prepTime should be used together; if only one is present, warn"},{"id":"recipe_time_present","level":"warning","description":"Provide totalTime or both cookTime and prepTime"},{"id":"recipe_iso_durations","level":"error","description":"cookTime, prepTime and totalTime must be valid ISO 8601 durations (e.g. PT1H30M)"},{"id":"recipe_instructions_no_boilerplate","level":"warning","description":"recipeInstructions / HowToStep.text should not contain non-instruction text such as 'Directions', 'Watch the video', 'Step 1'; HowToStep.name should not be 'Step N'"},{"id":"recipe_instructions_single_text","level":"warning","description":"recipeInstructions as a single Text block is not recommended; use HowToStep or HowToSection"},{"id":"recipe_keywords_not_category","level":"warning","description":"keywords should not repeat values used in recipeCategory or recipeCuisine"},{"id":"recipe_single_review_author","level":"error","description":"If the Recipe contains a single review, the reviewer's name must be a valid person or organization (e.g. '50% off ingredients' is not valid)"},{"id":"recipe_itemlist_unique_urls","level":"error","description":"In an ItemList of recipes, every ListItem must have a unique canonical url and a position"},{"id":"recipe_itemlist_listitem_required","level":"error","description":"For host carousel ItemList markup: ItemList.itemListElement (ListItem, annotation for a single item page) is required; each ListItem requires position (Integer, ordinal position of the item page) and url (URL, the canonical URL of the item page)"}],"guidelines":["Use Recipe structured data for content about preparing a particular dish; 'facial scrub' or 'party ideas' are not valid dish names.","For carousel or grid display, provide ItemList structured data summarizing the recipes and a summary page listing all recipes in the collection.","Image URLs must be crawlable and indexable, represent the marked up content, and be in a format supported by Google Images.","Provide multiple high-resolution images (at least 50K pixels, width x height) in 16x9, 4x3 and 1x1 aspect ratios.","Follow the Review snippet guidelines for aggregateRating and review markup.","Include only text on how to make the dish in recipeInstructions; put author, cuisine, category and keywords in their own properties.","Separate multiple keywords with commas and don't reuse recipeCategory or recipeCuisine values as keywords."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Restaurant carousel (local business)","slug":"restaurant-carousel","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/local-business","status":"limited","statusNote":"The Restaurant carousel is currently limited to a small set of restaurant providers; interest is registered through a Google form.","triggerTypes":["Restaurant"],"entity":{"properties":[{"name":"image","level":"required","expects":["URL","ImageObject"],"array":true,"constraints":{"image":{"aspectRatios":["16x9","4x3","1x1"],"minPixels":50000},"note":"One or more images of the restaurant. Image URLs must be crawlable and indexable; images must represent the marked up content and be in a file format supported by Google Images"},"message":"One or more images of the restaurant (minimum 50K pixels, 16x9, 4x3 and 1x1 recommended)"},{"name":"name","level":"required","expects":["Text"],"array":false,"message":"The name of the restaurant"},{"name":"address","level":"recommended","expects":["PostalAddress"],"array":false,"constraints":{"note":"Include as many properties as possible"},"message":"The physical location of the business","nested":{"properties":[{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"The street address"},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"The city or locality"},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"The region, state or province"},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"The postal code"},{"name":"addressCountry","level":"recommended","expects":["Text","Country"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The country, as a two-letter ISO 3166-1 alpha-2 code"}],"anyOf":[]}},{"name":"servesCuisine","level":"recommended","expects":["Text"],"array":true,"message":"The type of cuisine the restaurant serves"}],"anyOf":[]},"customChecks":[{"id":"rc_carousel_list","level":"warning","description":"Carousel eligibility also requires following the Carousel guidelines (ItemList on a summary page); only a small set of providers are eligible"}],"guidelines":["Limited to a small set of restaurant providers.","Follow the Carousel guidelines.","Image URLs must be crawlable and indexable and represent the marked up content."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Merchant return policy (organization-level)","slug":"return-policy","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/return-policy","status":"active","statusNote":"Nested under Organization via hasMerchantReturnPolicy. Precedence: Content API for Shopping > Merchant Center/Search Console settings > product-level markup > organization-level markup. Product-level (Offer) policies support a more limited set of properties (see merchant listing).","triggerTypes":["MerchantReturnPolicy"],"entity":{"properties":[{"name":"applicableCountry","level":"required","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2}$","note":"ISO 3166-1 alpha-2; up to 50 countries. Required unless only merchantReturnLink is used."},"message":"The country code(s) the return policy applies to (where the product is sold and returned from)"},{"name":"returnPolicyCategory","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/MerchantReturnFiniteReturnWindow","https://schema.org/MerchantReturnNotPermitted","https://schema.org/MerchantReturnUnlimitedWindow"],"note":"Required unless only merchantReturnLink is used. If MerchantReturnFiniteReturnWindow, merchantReturnDays is required."},"message":"The type of return policy"},{"name":"merchantReturnLink","level":"required","expects":["URL"],"array":false,"constraints":{"note":"Alternative to applicableCountry + returnPolicyCategory"},"message":"The URL of a web page that describes the return policy to your customers"},{"name":"merchantReturnDays","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Required if returnPolicyCategory is MerchantReturnFiniteReturnWindow. Number of days from the delivery date."},"message":"The number of days from the delivery date that a product can be returned"},{"name":"returnPolicyCountry","level":"recommended","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2}$","note":"ISO 3166-1 alpha-2; up to 50 countries"},"message":"The country where the product has to be sent to for returns"},{"name":"returnMethod","level":"recommended","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/ReturnAtKiosk","https://schema.org/ReturnByMail","https://schema.org/ReturnInStore"]},"message":"The type of return method offered; one or more values"},{"name":"returnFees","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FreeReturn","https://schema.org/ReturnFeesCustomerResponsibility","https://schema.org/ReturnShippingFees"]},"message":"The type of return fees"},{"name":"returnShippingFeesAmount","level":"optional","expects":["MonetaryAmount"],"array":false,"constraints":{"note":"Must be specified only when returnFees equals ReturnShippingFees"},"message":"The cost of shipping for returning a product","nested":{"properties":[{"name":"currency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"ISO 4217 currency code"},{"name":"value","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"The amount"}],"anyOf":[]}},{"name":"returnLabelSource","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/ReturnLabelCustomerResponsibility","https://schema.org/ReturnLabelDownloadAndPrint","https://schema.org/ReturnLabelInBox"]},"message":"How the customer obtains a return shipping label"},{"name":"itemCondition","level":"recommended","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/DamagedCondition","https://schema.org/NewCondition","https://schema.org/RefurbishedCondition","https://schema.org/UsedCondition"]},"message":"Acceptable condition(s) of returned items"},{"name":"refundType","level":"recommended","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/ExchangeRefund","https://schema.org/FullRefund","https://schema.org/StoreCreditRefund"]},"message":"The type of refund available"},{"name":"restockingFee","level":"recommended","expects":["MonetaryAmount","Number"],"array":false,"constraints":{"note":"Number is a percentage of the price paid by the consumer; MonetaryAmount is a fixed fee"},"message":"The restocking fee charged for returns"},{"name":"customerRemorseReturnFees","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FreeReturn","https://schema.org/ReturnFeesCustomerResponsibility","https://schema.org/ReturnShippingFees"]},"message":"Return fee type if the product is returned due to customer remorse"},{"name":"customerRemorseReturnLabelSource","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/ReturnLabelCustomerResponsibility","https://schema.org/ReturnLabelDownloadAndPrint","https://schema.org/ReturnLabelInBox"]},"message":"Return label source for customer remorse returns"},{"name":"customerRemorseReturnShippingFeesAmount","level":"recommended","expects":["MonetaryAmount"],"array":false,"constraints":{"note":"Only required if there's a non-zero shipping fee for remorse returns"},"message":"Shipping fee for customer remorse returns","nested":{"properties":[{"name":"currency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"ISO 4217 currency code"},{"name":"value","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"The amount"}],"anyOf":[]}},{"name":"itemDefectReturnFees","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FreeReturn","https://schema.org/ReturnFeesCustomerResponsibility","https://schema.org/ReturnShippingFees"]},"message":"Return fee type for defect products"},{"name":"itemDefectReturnLabelSource","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/ReturnLabelCustomerResponsibility","https://schema.org/ReturnLabelDownloadAndPrint","https://schema.org/ReturnLabelInBox"]},"message":"Return label source for defect product returns"},{"name":"itemDefectReturnShippingFeesAmount","level":"recommended","expects":["MonetaryAmount"],"array":false,"constraints":{"note":"Only required if there's a non-zero shipping fee for defect returns"},"message":"Shipping fee for defect product returns","nested":{"properties":[{"name":"currency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"ISO 4217 currency code"},{"name":"value","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"The amount"}],"anyOf":[]}},{"name":"returnPolicySeasonalOverride","level":"recommended","expects":["MerchantReturnPolicySeasonalOverride"],"array":true,"constraints":{"note":"For seasonal or holiday exceptions"},"message":"A seasonal override of the return policy","nested":{"properties":[{"name":"returnPolicyCategory","level":"required","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/MerchantReturnFiniteReturnWindow","https://schema.org/MerchantReturnNotPermitted","https://schema.org/MerchantReturnUnlimitedWindow"]},"message":"The type of return policy for the season"},{"name":"merchantReturnDays","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Required if returnPolicyCategory is MerchantReturnFiniteReturnWindow"},"message":"Number of return days during the season"},{"name":"startDate","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Start of the seasonal override"},{"name":"endDate","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"End of the seasonal override"}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"rp_required_option","level":"error","description":"Provide either (applicableCountry AND returnPolicyCategory) or merchantReturnLink. The validator must ignore the per-property required flag on these three and enforce this rule instead."},{"id":"rp_finite_days","level":"error","description":"If returnPolicyCategory (top level or in returnPolicySeasonalOverride) is MerchantReturnFiniteReturnWindow, merchantReturnDays is required"},{"id":"rp_shipping_fees_amount","level":"error","description":"returnShippingFeesAmount must be specified only when returnFees is ReturnShippingFees (and should be present in that case)"},{"id":"rp_country_limit","level":"error","description":"applicableCountry and returnPolicyCountry accept at most 50 countries, each ISO 3166-1 alpha-2"},{"id":"rp_not_permitted_extras","level":"warning","description":"When returnPolicyCategory is MerchantReturnNotPermitted, return fee/method/days properties are not meaningful"}],"guidelines":["Place return information on a single page that describes the return policy of your business, nested under Organization via hasMerchantReturnPolicy.","Product-level return policies (Offer) override organization-level markup and support a more limited property set.","Merchant Center / Search Console settings and the Content API take precedence over markup."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Review snippet","slug":"review-snippet","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/review-snippet","status":"active","statusNote":"Self-serving reviews: pages using LocalBusiness or any Organization type are ineligible for star review features if the reviewed entity controls the reviews about itself.","triggerTypes":["Review","AggregateRating"],"entity":{"properties":[{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"constraints":{"note":"Applies when @type is Review."},"message":"Review: add reviewRating, the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]},"appliesTo":["Review"]},{"name":"author","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"maxLength":100,"note":"Applies when @type is Review. author.name must be shorter than 100 characters, otherwise not eligible for an author-based review snippet. Invalid example: '50% off until Saturday'."},"message":"Review: add author. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid name."}],"anyOf":[]},"appliesTo":["Review"]},{"name":"itemReviewed","level":"required","expects":["Book","Course","CreativeWorkSeason","CreativeWorkSeries","Episode","Event","Game","HowTo","LocalBusiness","MediaObject","Movie","MusicPlaylist","MusicRecording","Organization","Product","Recipe","SoftwareApplication"],"array":false,"constraints":{"note":"Must be one of the listed types or a subtype (for example a LocalBusiness subtype, Movie, Product)."},"message":"Add itemReviewed: the item that is being reviewed (omit only when nested in the reviewed item via review or aggregateRating).","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add itemReviewed.name: the name of the item that is being reviewed. Required even when nested (the parent item's name)."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Review: add datePublished in ISO 8601 format.","appliesTo":["Review"]},{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"note":"Applies when @type is AggregateRating. A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"AggregateRating: add ratingValue, the average rating for the item.","appliesTo":["AggregateRating"]},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; see customChecks.aggregate_count."},"message":"AggregateRating: add ratingCount or reviewCount: the total number of ratings for the item on your site.","appliesTo":["AggregateRating"]},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; see customChecks.aggregate_count."},"message":"AggregateRating: add reviewCount or ratingCount: the number of people who provided a review with or without a rating.","appliesTo":["AggregateRating"]},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"AggregateRating: add bestRating. If omitted, 5 is assumed.","appliesTo":["AggregateRating"]},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"AggregateRating: add worstRating. If omitted, 1 is assumed.","appliesTo":["AggregateRating"]}],"anyOf":[]},"customChecks":[{"id":"type_split","level":"error","description":"Properties apply by @type. Review: author, reviewRating (with ratingValue), itemReviewed (+name) required; datePublished, reviewRating.bestRating, reviewRating.worstRating recommended. AggregateRating: itemReviewed (+name), ratingValue, and one of ratingCount/reviewCount required; bestRating, worstRating recommended. Spec for Review: {\"properties\": [{\"name\": \"author\", \"level\": \"required\", \"expects\": [\"Person\", \"Organization\"], \"array\": false, \"constraints\": {\"maxLength\": 100, \"note\": \"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'.\"}, \"message\": \"Add author: the author of the review. The reviewer's name must be a valid name.\", \"nested\": {\"properties\": [{\"name\": \"name\", \"level\": \"required\", \"expects\": [\"Text\"], \"array\": false, \"constraints\": {\"maxLength\": 99}, \"message\": \"Add author.name: a valid person or organization name.\"}], \"anyOf\": []}}, {\"name\": \"itemReviewed\", \"level\": \"required\", \"expects\": [\"Book\", \"Course\", \"CreativeWorkSeason\", \"CreativeWorkSeries\", \"Episode\", \"Event\", \"Game\", \"HowTo\", \"LocalBusiness\", \"MediaObject\", \"Movie\", \"MusicPlaylist\", \"MusicRecording\", \"Organization\", \"Product\", \"Recipe\", \"SoftwareApplication\"], \"array\": false, \"constraints\": {\"note\": \"Must be one of the supported types or a subtype.\"}, \"message\": \"Add itemReviewed (omit only when the Review is nested in another type via review).\", \"nested\": {\"properties\": [{\"name\": \"name\", \"level\": \"required\", \"expects\": [\"Text\"], \"array\": false, \"message\": \"Add itemReviewed.name: the name of the item that is being reviewed.\"}], \"anyOf\": []}}, {\"name\": \"reviewRating\", \"level\": \"required\", \"expects\": [\"Rating\"], \"array\": false, \"message\": \"Add reviewRating: the rating given in this review.\", \"nested\": {\"properties\": [{\"name\": \"ratingValue\", \"level\": \"required\", \"expects\": [\"Number\", \"Text\"], \"array\": false, \"constraints\": {\"pattern\": \"^\\\\s*\\\\d+(\\\\.\\\\d+)?\\\\s*(%|\\\\s*/\\\\s*\\\\d+(\\\\.\\\\d+)?)?\\\\s*$\", \"note\": \"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating.\"}, \"message\": \"Add reviewRating.ratingValue: the rating given in this review.\"}, {\"name\": \"bestRating\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"message\": \"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed.\"}, {\"name\": \"worstRating\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"message\": \"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed.\"}], \"anyOf\": []}}, {\"name\": \"datePublished\", \"level\": \"recommended\", \"expects\": [\"Date\", \"DateTime\"], \"array\": false, \"message\": \"Add datePublished: the date the review was published, in ISO 8601 format.\"}], \"anyOf\": []} Spec for AggregateRating: {\"properties\": [{\"name\": \"itemReviewed\", \"level\": \"required\", \"expects\": [\"Book\", \"Course\", \"CreativeWorkSeason\", \"CreativeWorkSeries\", \"Episode\", \"Event\", \"Game\", \"HowTo\", \"LocalBusiness\", \"MediaObject\", \"Movie\", \"MusicPlaylist\", \"MusicRecording\", \"Organization\", \"Product\", \"Recipe\", \"SoftwareApplication\"], \"array\": false, \"constraints\": {\"note\": \"Must be one of the supported types or a subtype.\"}, \"message\": \"Add itemReviewed (omit only when the AggregateRating is nested in another type via aggregateRating).\", \"nested\": {\"properties\": [{\"name\": \"name\", \"level\": \"required\", \"expects\": [\"Text\"], \"array\": false, \"message\": \"Add itemReviewed.name: the name of the item that is being reviewed.\"}], \"anyOf\": []}}, {\"name\": \"ratingValue\", \"level\": \"required\", \"expects\": [\"Number\", \"Text\"], \"array\": false, \"constraints\": {\"pattern\": \"^\\\\s*\\\\d+(\\\\.\\\\d+)?\\\\s*(%|\\\\s*/\\\\s*\\\\d+(\\\\.\\\\d+)?)?\\\\s*$\", \"note\": \"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating.\"}, \"message\": \"Add ratingValue: the average rating for the item.\"}, {\"name\": \"ratingCount\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"constraints\": {\"note\": \"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf.\"}, \"message\": \"Add ratingCount or reviewCount: the total number of ratings for the item on your site.\"}, {\"name\": \"reviewCount\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"constraints\": {\"note\": \"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf.\"}, \"message\": \"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating.\"}, {\"name\": \"bestRating\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"message\": \"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed.\"}, {\"name\": \"worstRating\", \"level\": \"recommended\", \"expects\": [\"Number\"], \"array\": false, \"message\": \"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed.\"}], \"anyOf\": [{\"level\": \"required\", \"props\": [\"ratingCount\", \"reviewCount\"], \"message\": \"At least one of ratingCount or reviewCount is required.\"}]}"},{"id":"aggregate_count","level":"error","description":"AggregateRating: at least one of ratingCount or reviewCount is required."},{"id":"item_reviewed_nested","level":"error","description":"itemReviewed is required unless the Review/AggregateRating is nested in its item via review/aggregateRating; in either case the item (itemReviewed or parent) must have a name and be one of the allowed types: Book, Course, CreativeWorkSeason, CreativeWorkSeries, Episode, Event, Game, HowTo, LocalBusiness, MediaObject, Movie, MusicPlaylist, MusicRecording, Organization, Product, Recipe, SoftwareApplication (or subtypes)."},{"id":"rating_in_range","level":"error","description":"ratingValue must lie within worstRating..bestRating (defaults 1 and 5); percentages and fractions (60%, 6 / 10) are allowed. Comma decimal separators (4,4) are invalid."},{"id":"author_name_length","level":"error","description":"author.name must be shorter than 100 characters and be a valid person or organization name (not promotional text)."},{"id":"self_serving","level":"warning","description":"If itemReviewed (or the parent) is LocalBusiness or any Organization type and the reviews are on that entity's own site (including embedded third party widgets such as Google or Facebook reviews), the page is ineligible for star review features."},{"id":"multiple_reviews_need_aggregate","level":"warning","description":"If multiple individual reviews are included, also include an aggregate rating."}],"guidelines":["Make sure the review content you mark up is readily available to users from the marked up page; it must be immediately obvious that the page has review content.","Provide review information about a specific item, not about a category or a list of items.","If you include multiple individual reviews, also include an aggregate rating.","Don't aggregate reviews or ratings from other websites.","Use AggregateRating for an aggregate evaluation by many people.","We recommend only accepting ratings that are accompanied by a review comment and author's name.","Don't include fake or undisclosed incentivized reviews (not based on genuine experience, or written in exchange for money, discounts, vouchers or free products without clear and prominent disclosure).","Self-serving reviews: if the entity being reviewed controls the reviews about itself, pages using LocalBusiness or any other Organization type are ineligible for the star review feature (for example reviews of entity A on entity A's site, directly or via an embedded third party widget).","For local businesses, ratings must be sourced directly from users; don't rely on human editors to create, curate, or compile ratings information."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Merchant shipping policy (organization-level)","slug":"shipping-policy","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/shipping-policy","status":"active","statusNote":"Nested under Organization via hasShippingService. Precedence: Content API for Shopping > Merchant Center/Search Console settings > product-level markup (OfferShippingDetails, a subset of properties) > organization-level markup.","triggerTypes":["ShippingService"],"entity":{"properties":[{"name":"shippingConditions","level":"required","expects":["ShippingConditions"],"array":true,"message":"The shipping cost and/or delivery times that apply for a particular set of conditions","nested":{"properties":[{"name":"doesNotShip","level":"optional","expects":["Boolean"],"array":false,"constraints":{"note":"Only specify if applicable"},"message":"Set to true if shipping from origin to destination isn't available"},{"name":"numItems","level":"optional","expects":["QuantitativeValue"],"array":false,"message":"The range of the number of products in the order","nested":{"properties":[{"name":"minValue","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Defaults to 0"},"message":"Minimum number of items"},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"constraints":{"note":"Defaults to infinity"},"message":"Maximum number of items"},{"name":"unitCode","level":"optional","expects":["Text"],"array":false,"constraints":{"enum":["H87"],"note":"Omit or use H87"},"message":"Omit or use H87"}],"anyOf":[]}},{"name":"orderValue","level":"optional","expects":["MonetaryAmount"],"array":false,"message":"The range of the cost of the order","nested":{"properties":[{"name":"currency","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"The currency code in ISO 4217 format"},{"name":"minValue","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Defaults to 0"},"message":"The minimum value of the order"},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"constraints":{"note":"Defaults to infinity"},"message":"The maximum value of the order"}],"anyOf":[]}},{"name":"seasonalOverride","level":"optional","expects":["OpeningHoursSpecification"],"array":false,"message":"A limited time period for which this shipping conditions object is valid","nested":{"properties":[{"name":"validFrom","level":"optional","expects":["Date"],"array":false,"message":"First date the shipping condition is valid, ISO 8601"},{"name":"validThrough","level":"optional","expects":["Date"],"array":false,"message":"Last date the shipping condition is valid, ISO 8601"}],"anyOf":[{"level":"required","props":["validFrom","validThrough"],"message":"At least one of validFrom and validThrough must be provided"}]}},{"name":"shippingDestination","level":"optional","expects":["DefinedRegion"],"array":true,"message":"The shipping destination, if applicable","nested":{"properties":[{"name":"addressCountry","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The two-letter country code in ISO 3166-1 alpha-2 format"},{"name":"addressRegion","level":"optional","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z0-9]{2,3}$","note":"ISO 3166-2 subdivision code without country prefix (2-3 chars); supported for US, Australia and Japan only"},"message":"Country-specific region code"},{"name":"postalCode","level":"optional","expects":["Text"],"array":true,"constraints":{"note":"Supported for Australia, Canada and US"},"message":"Country-specific postal code"}],"anyOf":[]}},{"name":"shippingOrigin","level":"optional","expects":["DefinedRegion"],"array":false,"message":"The shipping origin, if applicable","nested":{"properties":[{"name":"addressCountry","level":"required","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$","note":"Two-letter ISO 3166-1 alpha-2 country code"},"message":"The two-letter country code in ISO 3166-1 alpha-2 format"},{"name":"addressRegion","level":"optional","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Z0-9]{2,3}$","note":"ISO 3166-2 subdivision code without country prefix (2-3 chars); supported for US, Australia and Japan only"},"message":"Country-specific region code"},{"name":"postalCode","level":"optional","expects":["Text"],"array":true,"constraints":{"note":"Supported for Australia, Canada and US"},"message":"Country-specific postal code"}],"anyOf":[]}},{"name":"shippingRate","level":"optional","expects":["MonetaryAmount","ShippingRateSettings"],"array":false,"constraints":{"note":"Only if doesNotShip is absent or false. MonetaryAmount: currency plus either value (0 for free) or maxValue, not both. ShippingRateSettings: orderPercentage or weightPercentage between 0 and 1."},"message":"The shipping cost for shipments from origin to destination","nested":{"properties":[{"name":"currency","level":"optional","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"3-letter ISO 4217 currency code"},"message":"The currency code for the shipping cost, ISO 4217 (MonetaryAmount)"},{"name":"value","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Use 0 for free shipping; don't combine with maxValue"},"message":"The fixed shipping cost"},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Don't specify both value and maxValue"},"message":"The maximum shipping cost"},{"name":"orderPercentage","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"maxValue":1},"message":"Shipping cost as a fraction of order value (ShippingRateSettings)"},{"name":"weightPercentage","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"maxValue":1},"message":"Shipping cost as a fraction of weight of shipped goods (ShippingRateSettings)"}],"anyOf":[]}},{"name":"transitTime","level":"optional","expects":["ServicePeriod"],"array":false,"constraints":{"note":"Only if doesNotShip is absent or false"},"message":"Expected transit time between leaving origin and arriving at destination","nested":{"properties":[{"name":"businessDays","level":"optional","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/Monday","https://schema.org/Tuesday","https://schema.org/Wednesday","https://schema.org/Thursday","https://schema.org/Friday","https://schema.org/Saturday","https://schema.org/Sunday"]},"message":"Days of the week when an order is in active transit"},{"name":"duration","level":"optional","expects":["QuantitativeValue"],"array":false,"message":"The number of business days in transit","nested":{"properties":[{"name":"minValue","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The minimum number of days"},{"name":"maxValue","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The maximum number of days"},{"name":"value","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The exact number of days, if known"},{"name":"unitCode","level":"optional","expects":["Text"],"array":false,"constraints":{"enum":["DAY","d"]},"message":"The unit of the values; must be DAY or d"}],"anyOf":[]}}],"anyOf":[]}},{"name":"weight","level":"optional","expects":["QuantitativeValue"],"array":false,"message":"The package's weight range","nested":{"properties":[{"name":"minValue","level":"optional","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"Defaults to 0"},"message":"Minimum weight"},{"name":"maxValue","level":"optional","expects":["Number"],"array":false,"constraints":{"note":"Defaults to infinity"},"message":"Maximum weight"},{"name":"unitCode","level":"optional","expects":["Text"],"array":false,"constraints":{"enum":["LBR","KGM"]},"message":"LBR (pound) or KGM (kilogram)"}],"anyOf":[]}}],"anyOf":[]}},{"name":"name","level":"recommended","expects":["Text"],"array":false,"message":"A unique name for your shipping service, for example 'Standard Shipping'"},{"name":"description","level":"recommended","expects":["Text"],"array":false,"message":"A description of your shipping service"},{"name":"fulfillmentType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/FulfillmentTypeDelivery","https://schema.org/FulfillmentTypeCollectionPoint"],"note":"Defaults to FulfillmentTypeDelivery"},"message":"How the product is delivered"},{"name":"handlingTime","level":"recommended","expects":["ServicePeriod"],"array":false,"message":"Handling time (for example in a warehouse) after receiving an order","nested":{"properties":[{"name":"businessDays","level":"optional","expects":["Enum"],"array":true,"constraints":{"enum":["https://schema.org/Monday","https://schema.org/Tuesday","https://schema.org/Wednesday","https://schema.org/Thursday","https://schema.org/Friday","https://schema.org/Saturday","https://schema.org/Sunday"]},"message":"Days of the week when received orders are processed"},{"name":"cutoffTime","level":"optional","expects":["Time"],"array":false,"constraints":{"note":"ISO 8601 time, for example 23:30:00-05:00"},"message":"Time after which orders received that day are not processed the same day"},{"name":"duration","level":"optional","expects":["QuantitativeValue"],"array":false,"message":"Delay between receipt of an order and the goods leaving the warehouse","nested":{"properties":[{"name":"minValue","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The minimum number of days"},{"name":"maxValue","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The maximum number of days"},{"name":"value","level":"optional","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"Non-negative whole number"},"message":"The exact number of days, if known"},{"name":"unitCode","level":"optional","expects":["Text"],"array":false,"constraints":{"enum":["DAY","d"]},"message":"The unit of the values; must be DAY or d"}],"anyOf":[]}}],"anyOf":[]}},{"name":"validForMemberTier","level":"optional","expects":["MemberProgramTier"],"array":false,"message":"The loyalty program and tier this shipping service is valid for, if applicable"}],"anyOf":[]},"customChecks":[{"id":"sp_rate_value_xor_max","level":"error","description":"shippingRate as MonetaryAmount needs currency and exactly one of value or maxValue (not both)"},{"id":"sp_rate_settings_pct","level":"error","description":"shippingRate as ShippingRateSettings needs orderPercentage or weightPercentage, each between 0 and 1"},{"id":"sp_does_not_ship_exclusive","level":"warning","description":"shippingRate and transitTime should only be specified if doesNotShip is absent or false"},{"id":"sp_days_whole","level":"error","description":"handlingTime/transitTime duration values must be non-negative whole numbers and unitCode DAY or d; minValue <= maxValue"},{"id":"sp_seasonal_override_dates","level":"error","description":"seasonalOverride (OpeningHoursSpecification) must have at least one of validFrom or validThrough"},{"id":"sp_region_support","level":"warning","description":"DefinedRegion.addressRegion supported only for US, AU, JP; postalCode only for AU, CA, US"},{"id":"sp_overlap","level":"info","description":"When several ShippingConditions apply, Google uses the lowest cost, then the fastest speed"}],"guidelines":["Place shipping policy information on a single page that describes the shipping policy of your business, nested under Organization via hasShippingService.","Use OfferShippingDetails under Offer for products with non-standard shipping; offer-level properties are a subset of organization-level ones.","Use 0 as shippingRate value for free shipping."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Site name","slug":"site-name","docUrl":"https://developers.google.com/search/docs/appearance/site-names","status":"active","statusNote":"Available in all languages where Google Search is available, mobile and desktop. Supported at domain and subdomain level only (not subdirectories).","triggerTypes":["WebSite"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"Follow the guidelines for choosing a site name: unique, accurate, concise, commonly recognized (for example 'Google' not 'Google, Inc')"},"message":"The name of the website"},{"name":"url","level":"required","expects":["URL"],"array":false,"constraints":{"note":"The canonical home page of the domain or subdomain, for example https://example.com/ or https://news.example.com/"},"message":"The URL of the home page of the site"},{"name":"alternateName","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"List in order of preference, most important first; values must also follow the site name guidelines"},"message":"An alternate name of the website, for example a recognized acronym or shorter name"}],"anyOf":[]},"customChecks":[{"id":"sn_home_page_only","level":"error","description":"WebSite site name markup must be on the home page at the domain or subdomain root; subdirectory home pages (for example https://example.com/news) are not supported"},{"id":"sn_url_is_root","level":"error","description":"url must be the canonical home page (root path) of the domain or subdomain"},{"id":"sn_single_website","level":"warning","description":"Avoid duplicate WebSite blocks; nest into existing WebSite markup if present"},{"id":"sn_consistency","level":"warning","description":"name should match og:site_name, <title>, headings and other home page text, and Organization name"},{"id":"sn_concise","level":"warning","description":"name should be concise and not include legal suffixes such as 'Inc'"},{"id":"sn_indexable","level":"error","description":"Home page must be crawlable: not blocked by robots.txt and not noindex"}],"guidelines":["Put WebSite markup on the home page of the domain or subdomain; subdirectories aren't supported.","Choose a unique, accurate, concise, commonly recognized name; avoid generic names unless they are a well-known brand.","Use the same name consistently across structured data, og:site_name, title, headings and other home page text.","Provide alternateName values in order of preference.","Ensure the home page and duplicates (HTTP/HTTPS, www/non-www) are accessible, not blocked by robots.txt or noindex."],"lastUpdatedOnDoc":"2025-12-10"},{"feature":"Sitelinks search box","slug":"sitelinks-searchbox","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/sitelinks-searchbox","status":"deprecated","statusNote":"Announced Oct 21, 2024 (Farewell, sitelinks search box); no longer shown in Google Search from Nov 21, 2024. Doc removed and nositelinkssearchbox rule archived Nov 29, 2024. Leftover WebSite plus SearchAction markup causes no errors; WebSite markup is still used for site names.","triggerTypes":["WebSite"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"sitelinks_searchbox_deprecated","level":"warning","description":"Sitelinks search box rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Software app","slug":"software-app","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/software-app","status":"active","statusNote":"VideoGame alone is not eligible; co-type VideoGame with another SoftwareApplication type.","triggerTypes":["SoftwareApplication","MobileApplication","WebApplication","VideoGame"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the name of the app."},{"name":"offers","level":"required","expects":["Offer"],"array":true,"message":"Add offers.price: an offer to sell the app. For free apps set offers.price to 0.","nested":{"properties":[{"name":"price","level":"required","expects":["Number","Text"],"array":false,"constraints":{"minValue":0},"message":"Add offers.price. Use 0 for free apps."},{"name":"priceCurrency","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{3}$","note":"Three-letter ISO 4217 currency code, for example USD or EUR."},"message":"Add offers.priceCurrency (required if price is greater than 0), for example USD."}],"anyOf":[]}},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"constraints":{"note":"Required via anyOf with review."},"message":"Add aggregateRating or review: the average review score of the app. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add ratingValue: the average rating for the item."},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add ratingCount or reviewCount: the total number of ratings for the item on your site."},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required."}]}},{"name":"review","level":"recommended","expects":["Review"],"array":true,"constraints":{"note":"Required via anyOf with aggregateRating."},"message":"Add review or aggregateRating: a single review of the app. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"author","level":"required","expects":["Person","Organization"],"array":false,"constraints":{"maxLength":100,"note":"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'."},"message":"Add author: the author of the review. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid person or organization name."}],"anyOf":[]}},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"Add reviewRating: the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]}},{"name":"datePublished","level":"recommended","expects":["Date","DateTime"],"array":false,"message":"Add datePublished: the date the review was published, in ISO 8601 format."}],"anyOf":[]}},{"name":"applicationCategory","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["GameApplication","SocialNetworkingApplication","TravelApplication","ShoppingApplication","SportsApplication","LifestyleApplication","BusinessApplication","DesignApplication","DeveloperApplication","DriverApplication","EducationalApplication","HealthApplication","FinanceApplication","SecurityApplication","BrowserApplication","CommunicationApplication","DesktopEnhancementApplication","EntertainmentApplication","MultimediaApplication","HomeApplication","UtilitiesApplication","ReferenceApplication"],"note":"Values may also appear prefixed with https://schema.org/; compare on the bare name."},"message":"Add applicationCategory: the type of app, for example BusinessApplication or GameApplication. Must be a supported app type."},{"name":"operatingSystem","level":"recommended","expects":["Text"],"array":false,"message":"Add operatingSystem: the operating system(s) required, for example Windows 7, OSX 10.6, Android 1.6."}],"anyOf":[{"level":"required","props":["aggregateRating","review"],"message":"Include a rating or review: aggregateRating or review."}]},"customChecks":[{"id":"currency_if_paid","level":"error","description":"If offers.price is greater than 0, offers.priceCurrency is required."},{"id":"videogame_cotype","level":"error","description":"If @type is only VideoGame, the item is not eligible: co-type VideoGame with another type such as SoftwareApplication, MobileApplication or WebApplication."},{"id":"review_snippet_rules","level":"error","description":"Nested review and aggregateRating must satisfy the review-snippet spec."}],"guidelines":["Follow the Review snippet guidelines for aggregateRating and review.","For free apps set offers.price to 0; for paid apps include offers.priceCurrency.","Google supports MobileApplication and WebApplication subtypes; co-type VideoGame with another type to be eligible."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Speakable","slug":"speakable","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/speakable","status":"limited","statusNote":"Beta and subject to change. Available only for users in the U.S. with Google Home devices set to English, and for English-language content from news publishers.","triggerTypes":["Article","NewsArticle","WebPage"],"entity":{"properties":[{"name":"speakable","level":"required","expects":["SpeakableSpecification"],"array":false,"constraints":{"note":"Indicates sections of a web page that are particularly suited for text-to-speech playback using Google Assistant. Use on Article or WebPage. Content is located by cssSelector or xpath."},"message":"Missing speakable SpeakableSpecification","nested":{"properties":[{"name":"cssSelector","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"Addresses content in the annotated pages (such as class attribute). Use either cssSelector or xpath; don't use both."},"message":"Provide cssSelector (or xpath) to address the speakable content"},{"name":"xpath","level":"recommended","expects":["Text"],"array":true,"constraints":{"note":"Addresses content using xPaths (assuming an XML view of the content). Use either cssSelector or xpath; don't use both."},"message":"Provide xpath (or cssSelector) to address the speakable content"}],"anyOf":[{"level":"required","props":["cssSelector","xpath"],"message":"SpeakableSpecification requires cssSelector or xpath"}]}}],"anyOf":[]},"customChecks":[{"id":"speakable_selector_exclusive","level":"error","description":"Use either cssSelector or xpath in a SpeakableSpecification; don't use both"},{"id":"speakable_selector_matches","level":"warning","description":"Each cssSelector or xpath should resolve to at least one element in the rendered page"},{"id":"speakable_length","level":"warning","description":"Each speakable section should be about 20 to 30 seconds of content, roughly two to three sentences; flag matched text much longer than that"},{"id":"speakable_language","level":"info","description":"Feature only applies to English-language news content; flag if page language is not English"}],"guidelines":["Don't add speakable markup to content that may sound confusing in voice-only and voice-forward situations, like datelines (location where the story was reported), photo captions, or source attributions.","Focus on key points rather than highlighting an entire article.","Content for text-to-speech should be concise headlines and/or summaries that provide users with comprehensible and useful information.","Aim for around 20 to 30 seconds of content per section, roughly two to three sentences."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Special announcement","slug":"special-announcements","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/special-announcements","status":"deprecated","statusNote":"Deprecation notice added Apr 23, 2025: deprecated starting Jul 31, 2025. Also listed in the Jun 12, 2025 phase-out post. Doc removed and Search Console / Rich Results Test support dropped Sep 9, 2025.","triggerTypes":["SpecialAnnouncement"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"special_announcements_deprecated","level":"warning","description":"Special announcement rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Vacation rental","slug":"vacation-rental","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/vacation-rental","status":"limited","statusNote":"Limited to sites that meet eligibility criteria: requires a Google Technical Account Manager, Hotel Center access, and the vacation rental interest form (Early Adopters Program acceptance not guaranteed).","triggerTypes":["VacationRental"],"entity":{"properties":[{"name":"containsPlace","level":"required","expects":["Accommodation"],"array":false,"message":"Add containsPlace: one Accommodation with bed, occupancy, room and amenity details.","nested":{"properties":[{"name":"occupancy","level":"required","expects":["QuantitativeValue"],"array":false,"message":"Add containsPlace.occupancy: the maximum number of guests.","nested":{"properties":[{"name":"value","level":"required","expects":["Integer"],"array":false,"constraints":{"minValue":1},"message":"Add occupancy.value: the maximum number of guests."}],"anyOf":[]}},{"name":"additionalType","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["EntirePlace","PrivateRoom","SharedRoom"]},"message":"Add containsPlace.additionalType: EntirePlace, PrivateRoom or SharedRoom."},{"name":"bed","level":"recommended","expects":["BedDetails"],"array":true,"message":"Add bed: the beds in the rental.","nested":{"properties":[{"name":"numberOfBeds","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":1},"message":"Add bed.numberOfBeds: the number of beds of this type."},{"name":"typeOfBed","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["CaliforniaKing","King","Queen","Full","Double","SemiDouble","Single"],"note":"Suggested values."},"message":"Add bed.typeOfBed."}],"anyOf":[]}},{"name":"amenityFeature","level":"recommended","expects":["LocationFeatureSpecification"],"array":true,"constraints":{"note":"Boolean amenities (value true/false): ac, airportShuttle, balcony, beachAccess, childFriendly, crib, elevator, fireplace, freeBreakfast, gymFitnessEquipment, heating, hotTub, instantBookable, ironingBoard, kitchen, microwave, outdoorGrill, ovenStove, patio, petsAllowed, pool, privateBeachAccess, selfCheckinCheckout, smokingAllowed, tv, washerDryer, wheelchairAccessible, wifi. Text amenities: internetType (Free, Paid, None), parkingType (Free, Paid, None), poolType (Indoor, Outdoor, None), licenseNum (license number with authority, for example 'Paris: 123456ABC'; repeatable)."},"message":"Add amenityFeature: amenities of the property. Names and values must be in English.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["ac","airportShuttle","balcony","beachAccess","childFriendly","crib","elevator","fireplace","freeBreakfast","gymFitnessEquipment","heating","hotTub","instantBookable","ironingBoard","kitchen","microwave","outdoorGrill","ovenStove","patio","petsAllowed","pool","privateBeachAccess","selfCheckinCheckout","smokingAllowed","tv","washerDryer","wheelchairAccessible","wifi","internetType","parkingType","poolType","licenseNum"]},"message":"Add amenityFeature.name: one of the supported amenity names."},{"name":"value","level":"required","expects":["Boolean","Text"],"array":false,"message":"Add amenityFeature.value: true/false, or a text value for internetType, parkingType, poolType, licenseNum."}],"anyOf":[]}},{"name":"floorSize","level":"recommended","expects":["QuantitativeValue"],"array":false,"message":"Add floorSize with value and unitCode FTK/SQFT or MTK/SQM.","nested":{"properties":[{"name":"value","level":"required","expects":["Number"],"array":false,"message":"Add floorSize.value."},{"name":"unitCode","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["FTK","SQFT","MTK","SQM"]},"message":"Add floorSize.unitCode."}],"anyOf":[]}},{"name":"numberOfBathroomsTotal","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0},"message":"Add numberOfBathroomsTotal (RESO conventions; half baths count as 0.5)."},{"name":"numberOfBedrooms","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":0},"message":"Add numberOfBedrooms."},{"name":"numberOfRooms","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":0},"message":"Add numberOfRooms."}],"anyOf":[]}},{"name":"identifier","level":"required","expects":["Text"],"array":false,"message":"Add identifier: a unique, content independent ID for the property, stable across languages and listing edits."},{"name":"image","level":"required","expects":["URL"],"array":true,"constraints":{"minItems":8,"image":{"formats":["BMP","GIF","JPEG","PNG","WebP","SVG","AVIF"]},"note":"Must follow the property listing image requirements."},"message":"Add image: at least 8 photos, including at least one each of bedroom, bathroom and common area."},{"name":"latitude","level":"required","expects":["Number"],"array":false,"constraints":{"pattern":"^-?\\d+\\.\\d{5,}$"},"message":"Add latitude with at least 5 decimal places of precision."},{"name":"longitude","level":"required","expects":["Number"],"array":false,"constraints":{"pattern":"^-?\\d+\\.\\d{5,}$"},"message":"Add longitude with at least 5 decimal places of precision."},{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add name: the name of the vacation rental listing."},{"name":"additionalType","level":"recommended","expects":["Text"],"array":false,"constraints":{"enum":["Apartment","Bungalow","Cabin","Chalet","Cottage","Gite","HolidayVillageRental","House","Villa","VacationRental"],"note":"Suggested values."},"message":"Add additionalType: the type of vacation rental."},{"name":"address","level":"recommended","expects":["PostalAddress"],"array":false,"message":"Add address: the full physical location (no P.O. boxes).","nested":{"properties":[{"name":"addressCountry","level":"recommended","expects":["Text"],"array":false,"constraints":{"pattern":"^[A-Z]{2}$"},"message":"Add addressCountry: two-letter ISO 3166-1 alpha-2 code."},{"name":"addressLocality","level":"recommended","expects":["Text"],"array":false,"message":"Add addressLocality: the city."},{"name":"addressRegion","level":"recommended","expects":["Text"],"array":false,"message":"Add addressRegion: state, region or province."},{"name":"postalCode","level":"recommended","expects":["Text"],"array":false,"message":"Add postalCode."},{"name":"streetAddress","level":"recommended","expects":["Text"],"array":false,"message":"Add streetAddress including unit or apartment number."}],"anyOf":[]}},{"name":"aggregateRating","level":"recommended","expects":["AggregateRating"],"array":false,"message":"Add aggregateRating. Follow the Review snippet guidelines.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add ratingValue: the average rating for the item."},{"name":"ratingCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add ratingCount or reviewCount: the total number of ratings for the item on your site."},{"name":"reviewCount","level":"recommended","expects":["Number"],"array":false,"constraints":{"note":"Listed as required on the doc, but only one of ratingCount or reviewCount is needed; enforced by the required anyOf."},"message":"Add reviewCount or ratingCount: the number of people who provided a review with or without an accompanying rating."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[{"level":"required","props":["ratingCount","reviewCount"],"message":"At least one of ratingCount or reviewCount is required."}]}},{"name":"brand","level":"recommended","expects":["Brand"],"array":false,"message":"Add brand: the brand ID associated in Hotel Center, as {\"@type\": \"Brand\", \"name\": \"brandIdName\"}.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"message":"Add brand.name: the Hotel Center brand ID name."}],"anyOf":[]}},{"name":"checkinTime","level":"recommended","expects":["Time"],"array":false,"constraints":{"pattern":"^\\d{2}:\\d{2}(:\\d{2})?([+-]\\d{2}:\\d{2}|Z)?$"},"message":"Add checkinTime: earliest check-in time in ISO 8601, for example 14:30:00+08:00."},{"name":"checkoutTime","level":"recommended","expects":["Time"],"array":false,"constraints":{"pattern":"^\\d{2}:\\d{2}(:\\d{2})?([+-]\\d{2}:\\d{2}|Z)?$"},"message":"Add checkoutTime: latest checkout time in ISO 8601."},{"name":"description","level":"recommended","expects":["Text"],"array":false,"message":"Add description of the vacation rental."},{"name":"knowsLanguage","level":"recommended","expects":["Text"],"array":true,"constraints":{"pattern":"^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$"},"message":"Add knowsLanguage: languages the host speaks, as IETF BCP 47 codes (en-US, fr-FR)."},{"name":"review","level":"recommended","expects":["Review"],"array":true,"message":"Add review: user reviews. Follow the Review snippet guidelines; datePublished is required.","nested":{"properties":[{"name":"author","level":"required","expects":["Person"],"array":false,"constraints":{"maxLength":100,"note":"author.name must be shorter than 100 characters, otherwise the page is not eligible for an author-based review snippet. Must be a valid name, not for example '50% off until Saturday'."},"message":"Add author: the author of the review. The reviewer's name must be a valid name.","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"maxLength":99},"message":"Add author.name: a valid person or organization name."}],"anyOf":[]}},{"name":"reviewRating","level":"required","expects":["Rating"],"array":false,"message":"Add reviewRating: the rating given in this review.","nested":{"properties":[{"name":"ratingValue","level":"required","expects":["Number","Text"],"array":false,"constraints":{"pattern":"^\\s*\\d+(\\.\\d+)?\\s*(%|\\s*/\\s*\\d+(\\.\\d+)?)?\\s*$","note":"A number, fraction, or percentage (for example 4, 60%, or 6 / 10). Use a dot as decimal separator (4.4, not 4,4). Default scale is 1 to 5; if another scale is intended use bestRating and worstRating."},"message":"Add reviewRating.ratingValue: the rating given in this review."},{"name":"bestRating","level":"recommended","expects":["Number"],"array":false,"message":"Add bestRating: the highest value allowed in this rating system. If omitted, 5 is assumed."},{"name":"worstRating","level":"recommended","expects":["Number"],"array":false,"message":"Add worstRating: the lowest value allowed in this rating system. If omitted, 1 is assumed."}],"anyOf":[]}},{"name":"datePublished","level":"required","expects":["Date","DateTime"],"array":false,"message":"Add datePublished: required for vacation rental reviews (ISO 8601)."},{"name":"contentReferenceTime","level":"optional","expects":["DateTime"],"array":false,"constraints":{"note":"Required only when the property address is in France (addressCountry FR)."},"message":"Add contentReferenceTime: the start date of the author's stay. Required for properties located in France."}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"single_accommodation","level":"error","description":"containsPlace must contain exactly one Accommodation object."},{"id":"lat_lng_precision","level":"error","description":"latitude and longitude need at least 5 decimal places (check the raw JSON literal, numbers or strings)."},{"id":"image_count","level":"error","description":"At least 8 images, including at least one bedroom, one bathroom and one common area image."},{"id":"france_reference_time","level":"error","description":"If address.addressCountry is FR, every review needs contentReferenceTime (start date of the author's stay)."},{"id":"amenity_values","level":"error","description":"Boolean amenities need a boolean value; internetType and parkingType use Free, Paid or None; poolType uses Indoor, Outdoor or None; licenseNum is text and may repeat. All in English."},{"id":"review_date","level":"error","description":"Each review needs datePublished."}],"guidelines":["Comply with the Vacation Rental Policies, Search Essentials, and the general structured data guidelines; violations can lead to a manual action.","The identifier must be independent of listing content and the same for the same listing across languages.","Provide at least 8 photos, including bedroom, bathroom and common area, following the property listing image requirements.","All amenityFeature values must be in English regardless of listing language.","Address should be the full physical location; P.O. boxes are not allowed.","Pages must be accessible to Google (not blocked by robots.txt, noindex or login); submit a sitemap."],"lastUpdatedOnDoc":"2026-09-08"},{"feature":"Vehicle listing","slug":"vehicle-listing","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/vehicle-listing","status":"deprecated","statusNote":"Phase-out announced Jun 12, 2025 (Simplifying the search results page). Removed from Search Console rich result reporting, the Rich Results Test and Search appearance filters, and doc removed, Sep 9, 2025 (no longer shown in Google Search results). Doc URL now redirects to the updates changelog.","triggerTypes":["Car","Vehicle"],"entity":{"properties":[],"anyOf":[]},"customChecks":[{"id":"vehicle_listing_deprecated","level":"warning","description":"Vehicle listing rich results are no longer shown in Google Search. The markup is still valid schema.org but earns no Google rich result; keep it only if useful for other consumers."}],"guidelines":[],"lastUpdatedOnDoc":""},{"feature":"Video key moments","slug":"video-key-moments","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/video","status":"active","statusNote":"Applies when a VideoObject has hasPart Clip or potentialAction SeekToAction. Clip is supported in all languages where Google Search is available; SeekToAction is supported in English, Spanish, Portuguese, Italian, Chinese, French, Japanese, German, Turkish, Korean, Dutch, and Russian. For YouTube videos, Google may enable key moments from timestamps in the video description. Base VideoObject requirements are in video.json.","triggerTypes":["VideoObject"],"entity":{"properties":[{"name":"hasPart","level":"recommended","expects":["Clip"],"array":true,"constraints":{"note":"Clip markup: specify the exact start point and label for each segment. Use Clip or SeekToAction."},"message":"Add hasPart Clip items to define key moments","nested":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"A descriptive title for the content of the clip."},"message":"Clip requires name: a descriptive title for the clip"},{"name":"startOffset","level":"required","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"The start time of the clip expressed as the number of seconds from the beginning of the work."},"message":"Clip requires startOffset in seconds from the start of the video"},{"name":"url","level":"required","expects":["URL"],"array":false,"constraints":{"note":"A URL that points to the start time of the clip. The clip URL must point to the same URL path as the video with additional query parameters that specify the time, e.g. https://www.example.com/example?t=120."},"message":"Clip requires url pointing to the clip start time on the same URL path as the video"},{"name":"endOffset","level":"recommended","expects":["Number"],"array":false,"constraints":{"minValue":0,"note":"The end time of the clip expressed as the number of seconds from the beginning of the work."},"message":"Add Clip endOffset in seconds"}],"anyOf":[]}},{"name":"potentialAction","level":"recommended","expects":["SeekToAction"],"array":false,"constraints":{"note":"SeekToAction markup: tells Google how your URL structure works so it can automatically identify key moments and link to them. Include nested properties startOffset-input and target."},"message":"Add potentialAction SeekToAction to enable automatic key moments","nested":{"properties":[{"name":"startOffset-input","level":"required","expects":["Text"],"array":false,"constraints":{"enum":["required name=seek_to_second_number"],"note":"The placeholder string that Google will identify as your timestamp structure and then replace with the number of seconds to skip to. Use the value: required name=seek_to_second_number"},"message":"SeekToAction requires startOffset-input set to 'required name=seek_to_second_number'"},{"name":"target","level":"required","expects":["EntryPoint","URL"],"array":false,"constraints":{"pattern":"\\{seek_to_second_number\\}","note":"The URL of the page that contains this VideoObject, including a placeholder in the URL structure that indicates where Google would insert the number of seconds to skip to, e.g. https://video.example.com/watch/videoID?t={seek_to_second_number}"},"message":"SeekToAction requires target URL containing {seek_to_second_number}"}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"keymoments_clip_unique_start","level":"error","description":"No two Clip items on the same video defined on the same page may share the same startOffset"},{"id":"keymoments_clip_url_same_path","level":"error","description":"Clip.url must have the same URL path as the video (page) with additional query parameters specifying the time"},{"id":"keymoments_clip_end_after_start","level":"warning","description":"If endOffset is present it should be greater than startOffset"},{"id":"keymoments_min_duration","level":"warning","description":"The video must be at least 30 seconds long; if duration is present and under PT30S, key moments are not eligible"},{"id":"keymoments_requires_base_video","level":"error","description":"The VideoObject must include its required properties (name, thumbnailUrl, uploadDate) for key moments eligibility"},{"id":"keymoments_seektoaction_target_page","level":"warning","description":"SeekToAction target should be the URL of the page containing the VideoObject (same origin and path) plus the {seek_to_second_number} placeholder"},{"id":"keymoments_seektoaction_fetchable","level":"info","description":"For SeekToAction, Google must be able to fetch the video content files; recommend contentUrl"}],"guidelines":["The video must have the ability to deep link into some point other than the start point in the video URL (for example, ?t=30).","Add the structured data to a page where users can watch the video.","The video must be at least 30 seconds long.","Include the required VideoObject properties.","Clip only: no two clips on the same video defined on the same page may share a start time.","SeekToAction only: Google must be able to fetch your video content files.","YouTube timestamps: use [hour]:[minute]:[second] (hour optional if zero), put the label on the same line, one timestamp per line, link to the specified point, label at least one word, list chronologically."],"lastUpdatedOnDoc":"2026-09-24"},{"feature":"Video LIVE badge","slug":"video-live-badge","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/video","status":"active","statusNote":"Applies when a VideoObject has a publication BroadcastEvent. Base VideoObject requirements are in video.json.","triggerTypes":["VideoObject"],"entity":{"properties":[{"name":"publication","level":"required","expects":["BroadcastEvent"],"array":true,"constraints":{"note":"Describes when the video is to be streamed live. Can be a list or a single instance."},"message":"LIVE badge requires publication with a BroadcastEvent","nested":{"properties":[{"name":"isLiveBroadcast","level":"required","expects":["Boolean"],"array":false,"constraints":{"enum":["true"],"note":"Set to true if the video is, has been, or will be streamed live."},"message":"publication.isLiveBroadcast must be true"},{"name":"startDate","level":"required","expects":["DateTime"],"array":false,"constraints":{"note":"Time and date of when the livestream starts or is expected to start, in ISO 8601 format. In the past or present: the stream actually started. In the future: the stream is scheduled to start at that time."},"message":"publication.startDate is required (ISO 8601 DateTime)"},{"name":"endDate","level":"required","expects":["DateTime"],"array":false,"constraints":{"note":"Time and date of when the livestream ends or is expected to end, in ISO 8601 format. Required once the video has finished and is no longer live. If the expected endDate is unknown before the stream starts, provide an approximate endDate. In the past or present: the stream ended. In the future: scheduled to end at that time."},"message":"publication.endDate is required once the stream has ended; provide an approximate one in advance"}],"anyOf":[]}}],"anyOf":[]},"customChecks":[{"id":"live_end_after_start","level":"error","description":"publication.endDate must be after publication.startDate"},{"id":"live_enddate_after_finish","level":"warning","description":"endDate may be omitted only before the stream finishes; if startDate is in the past and endDate is missing, warn that endDate is required once the stream ends and an approximate endDate is recommended beforehand"},{"id":"live_datetime_format","level":"error","description":"startDate and endDate must be ISO 8601 DateTime values"},{"id":"live_requires_base_video","level":"error","description":"The VideoObject must include its required properties (name, thumbnailUrl, uploadDate)"}],"guidelines":["Don't use vulgar or potentially offensive language in the structured data.","Use the Indexing API to notify Google when the video goes live, when it stops streaming and the markup is updated with endDate, and whenever the markup changes.","The Indexing API only supports livestream videos."],"lastUpdatedOnDoc":"2026-09-24"},{"feature":"Video","slug":"video","docUrl":"https://developers.google.com/search/docs/appearance/structured-data/video","status":"active","statusNote":"Videos can appear in the main search results page, Video mode, Google Images, and Google Discover. Key moments (Clip, SeekToAction) and the LIVE badge (BroadcastEvent) are specified in video-key-moments.json and video-live-badge.json.","triggerTypes":["VideoObject"],"entity":{"properties":[{"name":"name","level":"required","expects":["Text"],"array":false,"constraints":{"note":"The title of the video. Make sure to use unique text in the name property for each video on your site."},"message":"Missing name: the title of the video"},{"name":"thumbnailUrl","level":"required","expects":["URL"],"array":true,"constraints":{"image":{"minWidthPx":60,"formats":["BMP","GIF","JPEG","PNG","WebP","SVG","AVIF"]},"note":"A URL pointing to the video's unique thumbnail image file. Follow the thumbnail image guidelines (from the linked video best practices page): minimum 60x30 pixels, larger preferred; at least 80% of the thumbnail's pixels must have an alpha value greater than 250; the file must be accessible to Googlebot and Googlebot-Image (not blocked by robots.txt or login) and available at a stable URL."},"message":"Missing thumbnailUrl: a URL to the video's unique thumbnail image"},{"name":"uploadDate","level":"required","expects":["DateTime"],"array":false,"constraints":{"note":"The date and time the video was first published, in ISO 8601 format. Provide timezone information; otherwise Google defaults to the timezone used by Googlebot."},"message":"Missing uploadDate: ISO 8601 date and time, with timezone, when the video was first published"},{"name":"contentUrl","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL pointing to the video file's actual content bytes, in one of the supported file types (3GP, 3G2, ASF, AVI, DivX, M2V, M3U, M3U8, M4V, MKV, MOV, MP4, MPEG, OGV, QVT, RAM, RM, VOB, WebM, WMV, XAP). Don't link to the page where the video lives. Data URLs are not supported. contentUrl is the most effective way for Google to fetch your video content files."},"message":"Add contentUrl: the URL of the video file itself (not the watch page)"},{"name":"creator","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"The person or organization that created or published the video (author is also accepted). If a person or organization is specified, you must provide either name or alternateName."},"message":"Add creator (or author): the person or organization that created the video","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the creator or organization."},"message":"Add creator.name"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A link to a web page that uniquely identifies the creator or organization (such as a profile page or homepage)."},"message":"Add creator.url: a page that uniquely identifies the creator"}],"anyOf":[{"level":"required","props":["name","alternateName"],"message":"If creator is specified, provide name or alternateName"}]}},{"name":"author","level":"recommended","expects":["Person","Organization"],"array":true,"constraints":{"note":"Accepted alternative to creator: the person or organization that created or published the video. If specified, provide either name or alternateName."},"message":"Add author (or creator)","nested":{"properties":[{"name":"name","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The name of the creator or organization."},"message":"Add author.name"},{"name":"url","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A link to a web page that uniquely identifies the creator or organization (such as a profile page or homepage)."},"message":"Add author.url"}],"anyOf":[{"level":"required","props":["name","alternateName"],"message":"If author is specified, provide name or alternateName"}]}},{"name":"description","level":"recommended","expects":["Text"],"array":false,"constraints":{"note":"The description of the video. Use unique text for each video on your site. HTML tags are ignored."},"message":"Add description: a unique description of the video"},{"name":"duration","level":"recommended","expects":["Duration"],"array":false,"constraints":{"note":"The duration of the video in ISO 8601 format. For example, PT00H30M5S represents a duration of thirty minutes and five seconds."},"message":"Add duration in ISO 8601 format (e.g. PT1M33S)"},{"name":"embedUrl","level":"recommended","expects":["URL"],"array":false,"constraints":{"note":"A URL pointing to a player for the specific video. Don't link to the page where the video lives; this must be the URL of the video player itself, e.g. https://www.example.com/embed/123."},"message":"Add embedUrl: the URL of the video player (not the watch page)"},{"name":"expires","level":"optional","expects":["DateTime"],"array":false,"constraints":{"note":"If applicable, the date and time after which the video will no longer be available, in ISO 8601 format. Don't supply this if the video does not expire. Provide timezone information."},"message":"Add expires only if the video expires (ISO 8601 with timezone)"},{"name":"hasPart","level":"recommended","expects":["Clip"],"array":true,"constraints":{"note":"If your video has important segments, nest the required Clip properties in your VideoObject. Validated by video-key-moments.json."},"message":"Add hasPart Clip items for important video segments (key moments)"},{"name":"ineligibleRegion","level":"optional","expects":["Place","Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2,3}$","note":"The region where the video isn't allowed, if applicable. If not specified, Google assumes the video is allowed everywhere. Countries in two- or three-letter ISO 3166-1 format; use multiple country codes for multiple values. Add either ineligibleRegion or regionsAllowed, whichever makes sense for your site."},"message":"ineligibleRegion: use ISO 3166-1 alpha-2 or alpha-3 country codes"},{"name":"interactionStatistic","level":"optional","expects":["InteractionCounter"],"array":true,"constraints":{"note":"User statistics applied to the video, if applicable."},"message":"Add interactionStatistic (e.g. WatchAction count)","nested":{"properties":[{"name":"interactionType","level":"recommended","expects":["Enum"],"array":false,"constraints":{"enum":["https://schema.org/WatchAction","https://schema.org/LikeAction","https://schema.org/CommentAction","https://schema.org/ShareAction"],"note":"The type of interaction. WatchAction: number of times watched; LikeAction: likes/upvotes; CommentAction: comments; ShareAction: reshares."},"message":"interactionType must be WatchAction, LikeAction, CommentAction or ShareAction"},{"name":"userInteractionCount","level":"recommended","expects":["Integer"],"array":false,"constraints":{"minValue":0,"note":"The number of times this interaction was performed."},"message":"Add userInteractionCount as an integer"}],"anyOf":[]}},{"name":"publication","level":"recommended","expects":["BroadcastEvent"],"array":true,"constraints":{"note":"If your video is happening live and you want to be eligible for the LIVE badge, nest BroadcastEvent properties. Validated by video-live-badge.json."},"message":"Add publication BroadcastEvent for livestreams (LIVE badge)"},{"name":"regionsAllowed","level":"optional","expects":["Place","Text"],"array":true,"constraints":{"pattern":"^[A-Z]{2,3}$","note":"The regions where the video is allowed, if applicable. If not specified, Google assumes the video is allowed everywhere. Countries in two- or three-letter ISO 3166-1 format; use multiple country codes for multiple values. Add either ineligibleRegion or regionsAllowed, whichever makes sense for your site."},"message":"regionsAllowed: use ISO 3166-1 alpha-2 or alpha-3 country codes"}],"anyOf":[{"level":"recommended","props":["contentUrl","embedUrl"],"message":"Provide contentUrl (most effective) or embedUrl so Google can fetch the video"}]},"customChecks":[{"id":"video_uploaddate_timezone","level":"warning","description":"uploadDate and expires should be ISO 8601 DateTime with timezone; without it Google defaults to Googlebot's timezone"},{"id":"video_duration_iso","level":"error","description":"duration must be a valid ISO 8601 duration (e.g. PT00H30M5S)"},{"id":"video_contenturl_not_page","level":"warning","description":"contentUrl and embedUrl must not equal the page URL where the video lives; contentUrl should point to a supported video file type and must not be a data: URL"},{"id":"video_region_conflict","level":"warning","description":"Use either ineligibleRegion or regionsAllowed, not both; country codes must be ISO 3166-1 alpha-2 or alpha-3"},{"id":"video_expires_future","level":"warning","description":"If expires is in the past, the video will no longer be shown"},{"id":"video_unique_name_description","level":"warning","description":"name and description should be unique per video across the site (cross-page check when multiple pages are validated)"},{"id":"video_author_name","level":"error","description":"If creator or author is a Person or Organization, it must have name or alternateName"}],"guidelines":["Don't use vulgar or potentially offensive language in the structured data.","Add structured data to watch pages where users can watch the video.","Provide contentUrl (most effective) or embedUrl so Google can fetch the video content files.","Thumbnails must be crawlable by Googlebot, at a stable URL, in a supported format, and at least 60x30 pixels.","Follow the video indexing best practices and the general structured data guidelines; violations can lead to a manual action."],"lastUpdatedOnDoc":"2026-09-24"}],"general":{"docUrls":["https://developers.google.com/search/docs/appearance/structured-data/sd-policies","https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data","https://developers.google.com/search/docs/appearance/structured-data/generate-structured-data-with-javascript"],"docsLastUpdated":{"sd-policies":"2026-07-10","intro-structured-data":"2025-12-10","generate-structured-data-with-javascript":"2025-12-10"},"rules":[{"id":"supported_format","level":"error","description":"Structured data must use one of the three supported formats to be eligible for rich results: JSON-LD (recommended), Microdata or RDFa.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"prefer_jsonld","level":"info","description":"Google recommends JSON-LD as the easiest solution to implement and maintain at scale.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"jsonld_script_type","level":"error","description":"JSON-LD must be in a <script type=\"application/ld+json\"> element, in either <head> or <body>.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"jsonld_parseable","level":"error","description":"JSON-LD blocks must be valid, parseable JSON; a syntax error makes the whole block unreadable (Rich Results Test reports syntax errors).","source":"https://developers.google.com/search/docs/appearance/structured-data/generate-structured-data-with-javascript"},{"id":"schema_org_context","level":"error","description":"Use the schema.org vocabulary: JSON-LD must declare @context of https://schema.org (http://schema.org also resolves); Microdata itemtype and RDFa vocab must point to schema.org.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"data_vocabulary_unsupported","level":"error","description":"data-vocabulary.org markup is no longer eligible for Google rich results; use schema.org.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"type_present","level":"error","description":"Every top-level item must declare a @type (or itemtype / typeof).","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"specific_type","level":"info","description":"Use the most specific applicable type and property names defined by schema.org.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"required_properties","level":"error","description":"Specify all required properties listed in the documentation for the rich result type; missing required properties make the item ineligible for that rich result.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"recommended_properties","level":"warning","description":"Recommended properties are optional but the more you provide, the higher quality the result is to users; missing ones are warnings, not errors.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"complete_over_many","level":"info","description":"It is more important to supply fewer but complete and accurate recommended properties than every recommended property with incomplete, badly formed or inaccurate data.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"google_docs_override_schema_org","level":"info","description":"Google Search Central docs, not schema.org, define what Google requires; schema.org properties not listed may be ignored by Google but are not errors.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"not_blocked_robots","level":"error","description":"Don't block structured data pages to Googlebot with robots.txt.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"not_noindex","level":"error","description":"Don't block structured data pages with noindex (meta robots or X-Robots-Tag) or any other access control method.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"content_visible","level":"warning","description":"Don't mark up content that is not visible to readers of the page; structured data values should appear in the visible page content.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"true_representation","level":"warning","description":"Structured data must be a true representation of the page content (relevance).","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"no_misleading","level":"warning","description":"Don't mark up irrelevant or misleading content (for example fake reviews or content unrelated to the focus of the page), and don't use structured data to deceive or mislead users.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"spam_policies","level":"info","description":"Follow the spam policies for Google web search; violations can lead to a structured data manual action, which removes rich result eligibility but does not affect web ranking.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"up_to_date","level":"warning","description":"Provide up-to-date information; Google won't show a rich result for time-sensitive content that is no longer relevant (for example past events or expired offers).","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"original_content","level":"info","description":"Provide original content that you or your users have generated.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"location_on_described_page","level":"warning","description":"Put the structured data on the page that it describes, unless the feature doc specifies otherwise.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"duplicates_same_markup","level":"info","description":"If you have duplicate pages for the same content, place the same structured data on all page duplicates.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"image_crawlable_indexable","level":"error","description":"All image URLs specified in structured data must be crawlable and indexable (not blocked by robots.txt, not noindex, return HTTP 200 with an image content type).","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"image_relevant","level":"warning","description":"Make sure every image in structured data is relevant to the page that it's on.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"multiple_items","level":"info","description":"A page may contain multiple items (more than one kind of thing); mark each up, either nested inside a main item or as separate top-level items.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"id_linking","level":"info","description":"When items are listed separately, use @id to connect related items so Google understands how they relate; every @id reference should resolve to a node defined on the page.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"},{"id":"nesting_valid","level":"warning","description":"Nested values must be objects of an expected type for the property (for example author as Person or Organization, offers as Offer); a plain string where an object is expected loses sub-properties.","source":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"},{"id":"absolute_urls","level":"warning","description":"URL-valued properties (url, image, logo, sameAs, item) should be absolute, fully qualified URLs (https://...). Not stated as a rule in the general docs, but several feature docs require the full URL and every Google example uses absolute URLs; relative URLs resolve against the page URL and are error-prone.","source":"https://developers.google.com/search/docs/appearance/structured-data/breadcrumb"},{"id":"iso8601_dates","level":"error","description":"Date, DateTime and Time values must be in ISO 8601 format (for example 2026-10-04 or 2026-10-04T09:30:00-04:00); Duration values use ISO 8601 duration format (for example PT1H30M). Feature docs (Article, Event, Job posting, Recipe, Video) state ISO 8601 for every date, time and duration property.","source":"https://developers.google.com/search/docs/appearance/structured-data/article"},{"id":"datetime_timezone","level":"warning","description":"DateTime values should include a timezone offset or Z; without one Google assumes a default timezone (for example the Googlebot or page locale), which can shift times. Article doc: we recommend that you provide timezone information; otherwise, we will default to the timezone used by Googlebot.","source":"https://developers.google.com/search/docs/appearance/structured-data/article"},{"id":"js_generated_supported","level":"info","description":"Google can process structured data injected with JavaScript (custom JS or Google Tag Manager) if it is present in the rendered DOM; verify with the Rich Results Test URL mode.","source":"https://developers.google.com/search/docs/appearance/structured-data/generate-structured-data-with-javascript"},{"id":"js_product_caution","level":"warning","description":"Dynamically generated Product markup can make Shopping crawls less frequent and less reliable, especially for fast-changing price and availability; prefer server-rendered markup for Product/Offer.","source":"https://developers.google.com/search/docs/appearance/structured-data/generate-structured-data-with-javascript"},{"id":"gtm_use_variables","level":"warning","description":"When using Google Tag Manager, populate JSON-LD from variables extracted from the page rather than hard-coded duplicates, to avoid mismatches between structured data and page content.","source":"https://developers.google.com/search/docs/appearance/structured-data/generate-structured-data-with-javascript"},{"id":"no_guarantee","level":"info","description":"Correct markup makes a page eligible but does not guarantee a rich result will be shown.","source":"https://developers.google.com/search/docs/appearance/structured-data/sd-policies"}]}};
